import toLowerCase from '../../common/utils/toLowerCase'
// import { getComputeObj } from './computeScript';

export default class MetaColumn {
  constructor(metaColumn, erItem) {
    if (metaColumn instanceof MetaColumn) {
      throw new Error('metaColumn should not be MetaColumn')
    }
    this._metaColumn = metaColumn
    this._erItem = erItem

    // 处理并缓存computeScript {get(){}, set: null}
    // this._computeObj = getComputeObj(this._metaColumn.computeScript);
  }

  get erItem() {
    return this._erItem
  }

  get id() {
    return this._metaColumn.id
  }

  get name() {
    return this._metaColumn.name
  }

  get widget() {
    return this._metaColumn.widget
  }

  get visible() {
    return this._metaColumn.visible
  }

  get searchName() {
    if (this.erItem) {
      return this.erItem.name + '.' + this.name
    }
    return this.name
  }

  get displayName() {
    return this._metaColumn.displayName
  }

  get index() {
    return this._metaColumn.index
  }

  get datatype() {
    return toLowerCase(this._metaColumn.dataType)
  }

  get dateRange() {
    return ['daterange', 'datetimerange'].includes(this._metaColumn.widget)
  }

  get dateFormat() {
    return this._metaColumn.dateFormat
  }

  get uniquekey() {
    return true
    // TODO 原有逻辑如下，需要确认
    // return this._metaColumn.unique;
  }

  get display() {
    return this._metaColumn.display
  }

  get searchFlg() {
    return this._metaColumn.searchFlg
  }

  get uiRuleScript() {
    return this._metaColumn.uiRuleScript
  }

  get editor() {
    return this._metaColumn.editor
  }

  get readonly() {
    return this._metaColumn.readonly
  }

  get required() {
    return this._metaColumn.required
  }

  get validation() {
    return this._metaColumn.validation
  }

  get isTrim() {
    return this._metaColumn.isTrim
  }

  get password() {
    return this._metaColumn.password
  }

  get propertyType() {
    return this._metaColumn.metaType
  }

  get defaultValue() {
    return this._metaColumn.defaultValue
  }

  get placeholder() {
    return this._metaColumn.toolTips
  }

  get RelateModel() {
    return this._metaColumn.attrs.RelateModel
  }

  typeIsNormal() {
    return !this.typeIsCompute() && !this.typeIsRelated()
  }

  typeIsCompute() {
    return this.propertyType === 'Compute'
  }

  typeIsRelated() {
    return this.propertyType === 'Related'
  }

  isPrimaryKey() {
    return this._metaColumn.name === 'id' // todo 目前主键都为id
  }

  isString() {
    return this.datatype === 'string'
  }

  isInteger() {
    return this.datatype === 'integer' || this.datatype === 'long'
  }

  isNumber() {
    return (
      this.datatype === 'double' ||
      this.datatype === 'bigdecimal' ||
      this.datatype === 'integer' ||
      this.datatype === 'long'
    )
  }

  getLength() {
    if (this._metaColumn.length !== null && this._metaColumn.length !== '') {
      return Number(this._metaColumn.length)
    }
    return null
  }

  getMinValue() {
    if (this._metaColumn.minValue !== null && this._metaColumn.minValue !== '') {
      return Number(this._metaColumn.minValue)
    }
    return null
  }

  getMaxValue() {
    if (this._metaColumn.maxValue !== null && this._metaColumn.maxValue !== '') {
      return Number(this._metaColumn.maxValue)
    }
    return null
  }

  computeObj() {
    return this._computeObj
  }
}
