import moment from 'moment'

// 获取查询配置的缓存信息
const getSearchConfigCacheData = (idPre) => {
  const cacheData = sessionStorage.getItem(idPre + 'SEARCH_CONFIG') || '{}'
  try {
    return (JSON.parse(cacheData).body.columns || [])
      .filter((item) => !!item.operator)
      .reduce((obj, item) => {
        obj[item.name] = {
          left: '%XXX',
          right: 'XXX%',
          all: '=',
          '=': '='
        }[item.operator]
        return obj
      }, {})
  } catch (e) {
    return {}
  }
}
// 通过 vm 判断是否隐藏搜索标签
const isHideFilterTitle = (vm) => {
  const storage = localStorage.getItem('VXE_TABLE_DATA_CACHE_LIST')
  const obj = storage ? JSON.parse(storage) : null
  // 是否有全局隐藏搜索标签
  const hiddenFilterTitle = window.$tech?.hiddenFilterTitle
  if (hiddenFilterTitle) {
    return true
  }
  // 从loadView数据里拿到存储个人界面初始方案数据
  if (window.$tech?.techAdvancedTable) {
    const seniorTable = vm.$cmd.getUiSchemeData(vm)
    const key = vm.$cmd.getIdPre(vm) + 'showFilterTitle'
    const showFilterTitle = obj[key]
    const options = showFilterTitle || !(key in obj) ? ['title'] : []
    const gridConfig = seniorTable?.gridConfig ? seniorTable?.gridConfig : options
    return gridConfig.indexOf('title') < 0
  } else if (obj) {
    return obj[vm.$cmd.getIdPre(vm) + 'showFilterTitle'] === false
  }
  return false
}

// 切换查询类型
export const changeQueryType = (vm) => {
  const idPre = vm.$cmd.fromTab(vm) ? vm.$ds.idPreTab : vm.$ds.idPre
  const tableMain = vm.$select(idPre + 'table_main')
  // 加强判断 是否开启了高级查询
  if (tableMain && window.$tech?.techAdvancedQuery) {
    const tableSearch = vm.$select(idPre + 'form_main_table_search')
    const tableSearchItems = vm.$select(idPre + 'container_table_search_items_1')
    const cacheData = getSearchConfigCacheData(idPre)
    const advancedQueryData = tableMain.$ds?.advancedQuery?.[idPre] || {}
    tableSearchItems.data.display = !advancedQueryData.isAdvancedQuery
    // 是否隐藏搜索标签 没有隐藏搜索标签 就通过状态进行判断处理
    if (!isHideFilterTitle(vm)) {
      tableSearch.data.display = !advancedQueryData.isAdvancedQuery
    }
    const advancedQuery = vm.$select(idPre + 'container_advanced_query')
    advancedQuery.data.display = !!advancedQueryData.isAdvancedQuery

    let viewGrid = tableMain.$ds.tableView?.data?.views?.grid
    if (!viewGrid) {
      const treeTable = vm.$select(idPre + 'tree_main_wrap_right_table')
      if (treeTable) {
        viewGrid = treeTable.$ds.tableView?.data?.views?.grid
      }
    }

    const advancedQueryGroupSize = viewGrid?.body?.advancedQueryGroupSize
    const advancedQueryConditionSize = viewGrid?.grid?.body?.advancedQueryConditionSize

    const tableMainTable = vm.$select(idPre + 'table_main_table')

    const columns =
      tableMainTable?.data?.items?.filter((item) => !['row_idx', 'operate'].includes(item.field)) ||
      []

    let options = viewGrid?.body?.columns || []

    const mapping = tableMain.$ds.tableView?.data?.fields || {}

    const _options = options
      .filter((item) => item.toSearch !== false) // 过滤掉指定字段不进入高级查询条件里面
      .map((item) => {
        const mappingInfo = mapping[item.name] || {}
        const key = typeof item === 'string' ? item : item.name
        const label = columns.find((column) => column.prop === key)?.title
        return {
          label: label || item.label || item.displayName || mappingInfo.displayName || item.name,
          value: key,
          operator: cacheData[key],
          filters: [
            '=',
            '!=',
            '%XXX%',
            '%XXX',
            'XXX%',
            '<',
            '<=',
            '>',
            '>=',
            'is null',
            'is not null',
            'range',
            'in'
          ]
        }
      })

    advancedQuery.data.itemMapping = options.reduce((total, columnInfo) => {
      const grid = viewGrid
      const formRender = vm.$cmd.meta.formFormat.initForm(
        vm,
        {
          ...grid,
          body: {
            ...grid.body,
            columns: [columnInfo]
          }
        },
        mapping
      )

      const items = formRender.items.map((item) => {
        return {
          ...item,
          items: item.items
            .filter(
              // 过滤组件信息
              (_item) =>
                ![
                  'upload',
                  'checkbox',
                  'radio-group',
                  'switch',
                  'textarea',
                  'transfer',
                  'progress',
                  'timeline',
                  'conditional-tree',
                  'inputrichtext',
                  'calendar',
                  'image',
                  'text'
                ].includes(_item.type)
            )
            .map((_item) => {
              return {
                ..._item,
                dataSource: {
                  form: {
                    [_item.name]: null
                  }
                },
                id: `advanced_form_${_item.name}`,
                required: false,
                innerLabel: false,
                text: '',
                rules: []
              }
            })
        }
      })
      if (items[0]?.items.length > 0) {
        const _item = items[0].items[0]
        const res = _options.find((option) => option.value === _item.name)
        const dataType = _item.dataType?.toLowerCase()
        const dateRange = _item.dateRange
        if (Object.keys(cacheData).length <= 0) {
          if (
            ![
              'string',
              'text',
              'date',
              'datetime',
              'integer',
              'bigdecimal',
              'float',
              'long',
              'double'
            ].includes(dataType) ||
            (['date', 'datetime'].includes(dataType) && dateRange)
          ) {
            if (res) {
              res.operator = '='
            }
          }
        }
        if (['integer', 'bigdecimal', 'float', 'long', 'double'].includes(dataType) && res) {
          res.filters = ['=', '>', '>=', '<', '<=', '!=']
        }

        if (['string', 'text'].includes(dataType) && res) {
          res.filters = ['%XXX%', '=', '!=', '%XXX', 'XXX%', 'is null', 'is not null']
        }

        if (['date', 'datetime'].includes(dataType) && res) {
          res.filters = ['=', '>', '>=', '<', '<=']
          if (_item.widget?.toLowerCase() === 'datetimerange') {
            res.filters = ['range']
            res.operator = 'range'
          }
        }

        if (_item.multiple === true) {
          res.filters = ['in']
          res.operator = 'in'
        }
        const key = typeof columnInfo === 'string' ? columnInfo : columnInfo.name
        total[key] = {
          type: 'form',
          items
        }
      }
      return total
    }, {})
    const form = vm.$select(idPre + 'form_main_table_search_common')
    const dropdownForm = vm.$select(idPre + 'form_main_table_search_dropdown')
    const data = Object.assign({}, form.$ds.form, dropdownForm?.$ds?.form)
    const keys = Object.keys(data).filter((key) => data[key])

    const getValue = (datatype, widget, type, value) => {
      if (datatype === 'string' || datatype === 'text') {
        return value
      }
      if (datatype === 'date' || datatype === 'datetime') {
        const dateRange =
          ['daterange', 'datetimerange', 'monthrange'].includes(widget) || Array.isArray(value)

        if (type === 'timepicker') {
          return value
        }
        if (dateRange) {
          if (datatype === 'datetime') {
            const fmt = 'YYYY-MM-DD HH:mm:ss'
            if (widget === 'monthrange') {
              return value.map((v, i) => moment(v)[i ? 'endOf' : 'startOf']('month').format(fmt))
            } else if (widget === 'daterange') {
              return value.map((v, i) => moment(v)[i ? 'endOf' : 'startOf']('date').format(fmt))
            } else {
              return value.map((v, i) => moment(v).format(fmt))
            }
          } else {
            const fmt = 'YYYY-MM-DD'
            if (widget === 'monthrange') {
              return value.map((v, i) => moment(v)[i ? 'endOf' : 'startOf']('month').format(fmt))
            } else {
              return value.map((v, i) => moment(v)[i ? 'endOf' : 'startOf']('date').format(fmt))
            }
          }
        }
      }
      return value
    }
    tableMain.$ds.advancedQuery = tableMain.$ds.advancedQuery || {}
    tableMain.$ds.advancedQuery[idPre] = tableMain.$ds.advancedQuery[idPre] || {}
    const info = tableMain.$ds.advancedQuery[idPre] || {}
    if (keys.length > 0) {
      const items = keys.reduce((total, key, i) => {
        if (key.includes('___values')) return total
        const mappingInfo = advancedQuery.data.itemMapping[key]
        const mappingType = mappingInfo?.items?.[0]?.items?.[0].type
        const mappingWidget = mappingInfo?.items?.[0]?.items?.[0].widget
        const dataType = mappingInfo?.items?.[0]?.items?.[0].dataType?.toLowerCase() || ''

        const value = getValue(dataType, mappingWidget, mappingType, data[key])
        if (value === undefined || value === null) return total
        if (Array.isArray(value)) {
          if (mappingType === 'datepicker') {
            // const [start, end] = value
            total.push({
              montage: i > 0 ? '&' : '',
              title: key,
              condition: cacheData[key] || 'range',
              content: value,
              values: data[key + '___values']
            })
            // total.push({
            //   montage: '&',
            //   title: key,
            //   condition: cacheData[key] || '<=',
            //   content: end,
            //   values: data[key + '___values']
            // })
          } else {
            data[key].map((val, key) => {
              const montage = i <= 0 ? '' : '|'
              return {
                montage,
                title: key,
                condition: cacheData[key] || '%XXX%',
                content: val,
                values: data[key + '___values']
              }
            })
          }
        } else {
          total.push({
            montage: i > 0 ? '&' : '',
            title: key,
            condition: cacheData[key] || '%XXX%',
            content: data[key],
            values: data[key + '___values']
          })
        }
        return total
      }, [])
      tableMain.$ds.advancedQuery[idPre] = {
        ...info,
        advancedQueryGroup: [
          {
            montage: '',
            items:
              items.length > 0
                ? items
                : [{ montage: '', title: '', condition: '%XXX%', content: '' }]
          }
        ]
      }
    } else {
      tableMain.$ds.advancedQuery[idPre] = {
        ...info,
        advancedQueryGroup: tableMain.$ds.advancedQuery?.[idPre]?.advancedQueryGroup || [
          {
            montage: '',
            items: [{ montage: '', title: '', condition: '%XXX%', content: '' }]
          }
        ]
      }
    }
    advancedQuery.data.advancedQueryGroup = tableMain.$ds.advancedQuery[idPre].advancedQueryGroup
    advancedQuery.data.isSlider =
      'advancedQueryIsSlider' in info ? info.advancedQueryIsSlider : true
    advancedQuery.data.groupSize = advancedQueryGroupSize || window.tech?.techAdvancedQueryGroupSize
    advancedQuery.data.conditionSize =
      advancedQueryConditionSize || window.tech?.techAdvancedQueryConditionSize

    vm.instance.$nextTick(() => {
      advancedQuery?.instance?.setOptions(_options)
    })
  }
}
// 高级查询
export const advancedQueryConfig = {
  type: 'advanced-query',
  id: 'container_advanced_query',
  display: false,
  bind_advancedQueryGroup: '$ds.advancedQueryGroup',
  bind_on_updateCondition: (params) => {
    const { value, self: vm } = params
    const idPre = vm.$cmd.fromTab(vm) ? vm.$ds.idPreTab : vm.$ds.idPre
    const tableMain = vm.$select(idPre + 'table_main')
    tableMain.$ds.advancedQuery = tableMain.$ds.advancedQuery || {}
    tableMain.$ds.advancedQuery[idPre] = {
      ...tableMain.$ds.advancedQuery[idPre],
      advancedQueryGroup: JSON.parse(JSON.stringify(value.conditionGroup))
    }
    // tableMain.$ds.advancedQueryGroup = JSON.parse(JSON.stringify(value.conditionGroup))
  },
  bind_on_out: (params) => {
    const { value, self: vm } = params
    const idPre = vm.$cmd.fromTab(vm) ? vm.$ds.idPreTab : vm.$ds.idPre
    const tableMain = vm.$select(idPre + 'table_main')
    tableMain.$ds.advancedQuery = tableMain.$ds.advancedQuery || {}
    // tableMain.$ds.isAdvancedQuery = false
    tableMain.$ds.advancedQuery[idPre] = {
      ...tableMain.$ds.advancedQuery[idPre],
      isAdvancedQuery: false
    }
    changeQueryType(vm)
  },
  bind_on_query: (params) => {
    const { value, self: vm } = params
    const idPre = vm.$cmd.fromTab(vm) ? vm.$ds.idPreTab : vm.$ds.idPre
    const tableMain = vm.$select(idPre + 'table_main')
    tableMain.$ds.advancedQuery = tableMain.$ds.advancedQuery || {}

    tableMain.$ds.advancedQuery[idPre] = {
      ...tableMain.$ds.advancedQuery[idPre],
      advancedQueryFilter: value.filter,
      advancedQueryGroup: JSON.parse(JSON.stringify(value.conditionGroup))
    }

    // tableMain.$ds.advancedQueryFilter = value.filter
    // tableMain.$ds.advancedQueryGroup = JSON.parse(JSON.stringify(value.conditionGroup))
    // 重置页码
    vm.$ds.paging.pageStart = 0
    vm.$ds.paging.currentPage = 1
    const tableSearch = vm.$select(vm.$cmd.getIdPre(vm) + 'form_main_table_search')
    tableSearch.$cmd.commonSearch(params)
    const tableSearchItems = vm.$select(idPre + 'container_table_search_items_1')
    tableSearchItems.$cmd.setFilterData(params)
    if (value.isSlider) {
      vm.instance.openSlider(false)
    }
    vm.instance.updateFilterConditionGroup()
  },
  bind_on_openSlider: (params) => {
    const { value, self: vm } = params
    const idPre = vm.$cmd.fromTab(vm) ? vm.$ds.idPreTab : vm.$ds.idPre
    const tableMain = vm.$select(idPre + 'table_main')
    tableMain.$ds.advancedQuery = tableMain.$ds.advancedQuery || {}
    tableMain.$ds.advancedQuery[idPre] = {
      ...tableMain.$ds.advancedQuery[idPre],
      advancedQueryIsSlider: value.isShow
    }
    changeQueryType(vm)
  },
  created: (vm) => {
    const idPre = vm.$cmd.fromTab(vm) ? vm.$ds.idPreTab : vm.$ds.idPre
    const tableMain = vm.$select(idPre + 'table_main')
    if (tableMain.$ds?.[idPre]?.advancedQueryFilter?.length > 0) {
      vm.instance.$nextTick(() => vm.instance.query(false))
    }
  }
}
