const timeInterval = () => {
  window.checkVersionTimeInterval = setInterval(() => {
    if (sessionStorage.getItem('nextLoginUpdate') != 'next') {
      checkVersion()
    }
  }, (window.tech?.checkVersion?.timeInterval || 3) * 60000)
}

const checkVersion = async () => {
  let showDialog = false
  async function fetchData(url) {
    try {
      let data = null
      const response = await fetch(url)
      data = await response.text()
      const regex = /"buildTime": "([^"]+)"/g
      const matches = []
      let match
      while ((match = regex.exec(data))) {
        matches.push(match[1])
      }
      // 底座打包的时间不是最新，则显示弹窗
      if (
        window.techPluginsVersion?.buildTime !== undefined &&
        matches[0] !== undefined &&
        window.techPluginsVersion?.buildTime != matches[0]
      ) {
        return true
      }
    } catch (error) {
      console.log('Fetch Error:', error)
    }
  }
  showDialog = (await fetchData(tech.routerBase + 'index.html')) || false
  const getPrepareListApps = async () => {
    try {
      if (!window._prepareListApps) return
      const json = await window.Tech.httpMeta({
        url: '/rpc/open/service',
        data: {
          params: {
            args: {},
            service: 'prepareListApps',
            model: 'meta_app',
            app: 'sie-iidp-app-store'
          }
        }
      })
      let apps = window._prepareListApps
      let data = json.data
      if (apps.length !== data.length) {
        return true
      }

      // 以 comp_name 为键建立 data 的映射
      const dataMap = new Map()
      data.forEach((item) => {
        if (item.comp_name) {
          dataMap.set(item.comp_name, item)
        }
      })

      for (let i = 0; i < apps.length; i++) {
        const app = apps[i]
        const dataItem = dataMap.get(app.comp_name)
        if (!dataItem) {
          return true
        }
        if (
          app.view_file_json?.__packageTime !== undefined &&
          dataItem.view_file_json?.__packageTime !== undefined &&
          app.view_file_json.__packageTime !== dataItem.view_file_json.__packageTime
        ) {
          return true
        }

        // 如果 apps 缺失 view_file_json 而 data 有，则补充（基于匹配项）
        if (app.view_file_json === undefined && dataItem.view_file_json !== undefined) {
          app.view_file_json = dataItem.view_file_json
        }
      }
    } catch (error) {
      console.log('Fetch ListApps Error:', error)
    }
  }
  if (showDialog == false && customProcess?.env === 'base') {
    showDialog = (await getPrepareListApps()) || false
  }
  if (showDialog == true) {
    let dialogCheckVersion = tech_app.page.getNode('dialog_check_version')
    if (dialogCheckVersion?.instance) {
      dialogCheckVersion.data.display = true
      return
    }
    let checkVersionDialog = {
      type: 'dialog',
      id: 'dialog_check_version',
      width: '45%',
      style: {
        'z-index': '99999 !important'
      },
      title: Tech.$t('common.checkVersionTips'),
      display: true,
      customButtons: [
        {
          text: Tech.$t('common.refreshInstantly'),
          action: 'refresh'
        }
      ],
      confirmText: Tech.$t('common.checkVersionConfirm'),
      cancelText:
        (window.tech?.checkVersion?.timeInterval || 3) + Tech.$t('common.checkVersionCancel'),
      bind_on_operates: (params) => {
        // 点击按钮
        const { self: vm, value } = params
        if (value.type === 'confirm') {
          // 下次登录再刷新，清除检查版本定时器
          value.close()
          sessionStorage.setItem('nextLoginUpdate', 'next')
          clearInterval(window.checkVersionTimeInterval)
        } else if (value.type === 'cancel') {
          value.close()
          clearInterval(window.checkVersionTimeInterval)
          timeInterval()
        } else if (value.type === 'refresh') {
          // 立即刷新
          value.close()
          window.location.reload()
        }
      },
      items: [
        {
          id: 'dialog_check_version_content',
          type: 'text',
          value: Tech.$t('common.checkVersionContent')
        }
      ]
    }
    // 弹窗节点不存在，动态添加弹窗
    tech_app.updatePageNode(checkVersionDialog, tech_app, () => {
      tech_app.page.data.items.push(checkVersionDialog)
      setTimeout(() => {
        if (tech_app.page.data.id == 'page_meta_login') {
          let $el = document.getElementById('dialog_check_version')
          // 查询出dialog弹窗节点
          const btn = $el.querySelectorAll('.confirmButton.button')[1]
          if (btn) btn.style.display = 'none'
        }
      }, 0)
    })
  }
}
export const checkAppVersion = () => {
  if (window.tech?.checkVersion?.autoCheck == true) {
    if (sessionStorage.getItem('nextLoginUpdate') != 'next') {
      checkVersion()
      timeInterval()
    }
  }
}
