// 依赖包引入
import { loadAsset, loadApps } from '../../importCommon/core.js'

import EmptyApp from './index.vue'

EmptyApp.install = (app) => {
  app.component(EmptyApp.name, EmptyApp)
}
EmptyApp.loadAsset = async (options, useVue) => {
  return await loadAsset(options, useVue)
}
EmptyApp.loadApps = async (apps, useVue, localOptions = null) => {
  return await loadApps(apps, useVue, localOptions, {})
}

export default EmptyApp
