export default {
  // 网格列&多表头设置'
  type: 'dialog',
  id: 'dialog_meta_set_senior_table',
  width: '80%',
  title: Tech.$t('seniorTable.tableColumnTableheaderSetting'),
  display: false,
  hasFooter: true,
  confirmText: Tech.$t('toolbar.dialogConfirm'),
  cancelText: Tech.$t('toolbar.dialogCancle'),
  bind_on_opreates: (params) => {
    const { self: vm, value } = params
    if (value.type === 'cancel') {
      value.close()
    } else {
      const idPre = vm.$cmd.getIdPre(vm)
      const setTableColumns = vm.$select(idPre + 'set_senior_table')
      const tableVm = vm.$select(idPre + 'table_main_table')

      let unusualItem = setTableColumns.data.tableData.some((item) => !item.title)
      if (unusualItem) {
        window.ELEMENT.Message.error(Tech.$t('seniorTable.theTitleCannotBeEmpty'))
        return
      }

      let titlelItem = setTableColumns.data.tableData.some((item) => item.title.length > 120)
      if (titlelItem) {
        window.ELEMENT.Message.error(Tech.$t('seniorTable.theTitleLength'))
        return
      }

      let list = [] // 判断是否有重复的序号
      const tableList = setTableColumns.data.tableData
      let isMinus = false
      tableList.forEach((item) => {
        list.push(item.sort)
        if (item.sort && (item.sort < 0 || !Number.isInteger(item.sort))) {
          isMinus = true
        }
      })
      // 判断如果有负数或者小数点的序号提示修改
      if (isMinus) {
        window.ELEMENT.Message.error(Tech.$t('seniorTable.hasMinusHint'))
        return
      }
      if (new Set(list).size !== list.length) {
        window.ELEMENT.Message.error(Tech.$t('seniorTable.theSameSortExists'))
        return
      }
      setTableColumns.data.tableData.forEach((item) => {
        // 获取拖拽列宽的值
        let columnWidth = JSON.parse(localStorage.getItem('VXE_TABLE_CUSTOM_COLUMN_WIDTH'))
        let cloneItem = window.Tech._cloneDeep(item)
        cloneItem.isWidthStar = cloneItem.width
        cloneItem.isWidthPercent = cloneItem.width
        const currentKey = tableVm.data.id + '_' + tableVm.data.userName
        // 删除本地存储宽度
        if (columnWidth && columnWidth[currentKey]) {
          if (columnWidth[currentKey][item.name] && cloneItem?.width) {
            delete columnWidth[currentKey][item.name]
          }
        }
        // 更新拖拽列宽
        localStorage.setItem('VXE_TABLE_CUSTOM_COLUMN_WIDTH', JSON.stringify(columnWidth))
        vm.$cmd.setGridColumns(tableVm, cloneItem, setTableColumns.data.tableData)
      })

      // 设置排序
      let items = tableVm.data.items.sort((a, b) => a.sort - b.sort)

      // 更新表格节点
      let newItems = window.Tech._cloneDeep(items)
      tableVm.data.items = []
      newItems.forEach((item) => {
        tableVm.app.updatePageNode(item, tableVm, () => {
          tableVm.data.items.push(item)
        })
      })

      // 缓存高级表格的弹窗数据
      const tableData = window.Tech._cloneDeep(setTableColumns.data.tableData)
      let seniorTableData = tableData.map((item) => ({
        sort: item.sort,
        title: item.title,
        width: item.width,
        filter: item.filter,
        fixed: item.fixed,
        visible: item.visible,
        name: item.name,
        isWidthStar: item.width,
        isWidthPercent: item.width,
        type: item.type
      }))
      tableVm.$ds.seniorTable.grid = seniorTableData
      value.close() // 关闭弹窗

      const advancedQuery = vm.$select(idPre + 'container_advanced_query')
      if (advancedQuery?.instance) {
        advancedQuery?.instance.openSlider(false)
      }
    }
  },
  items: [
    {
      type: 'container',
      id: 'set_senior_table_box',
      className: 'set_senior_table_box',
      dataSource: {
        fieldList: [{ sort: 1, display: 2 }]
      },
      created: (vm) => {
        const idPre = vm.$cmd.getIdPre(vm)
        const tableMain = vm.$select(idPre + 'table_main_table')
        const { views, fields } = tableMain.$ds.tableView.data
        // const gridColumns = views?.grid?.body?.columns || []
        const gridColumns = window.Tech._cloneDeep(
          tableMain.data.items.filter((item) => !['row_idx', 'operate'].includes(item.field))
        )
        let list = []
        // 获取当前表格的列真实渲染的宽
        const columnItem = tableMain?.instance?.$refs?.xGrid.getColumns() || []
        // 获取拖拽列宽的值
        let columnWidth = JSON.parse(localStorage.getItem('VXE_TABLE_CUSTOM_COLUMN_WIDTH'))
        const currentKey = tableMain.data.id + '_' + tableMain.data.userName
        // 删除本地存储宽度
        for (let i = 0; i < gridColumns.length; i++) {
          let width =
            columnItem.find((el) => el.field == gridColumns[i].name)?.renderWidth || undefined
          if (width) width = parseInt(width).toString()
          // 是否有拖拽过的列
          const renderWidth =
            columnWidth && columnWidth[currentKey] && columnWidth[currentKey][gridColumns[i].name]
          if (/\d/.test(gridColumns[i].width) && !renderWidth) {
            if (gridColumns[i].isWidthPercent?.endsWith('%')) {
              width = gridColumns[i].isWidthPercent
            } else if (gridColumns[i]?.isWidthStar?.endsWith('*')) {
              width = gridColumns[i].isWidthStar
            }
          }

          let filter = false
          if (gridColumns[i]?.filter?.show) filter = true
          // 获取表格可视的列
          let sort = columnItem.findIndex((el) => el.field == gridColumns[i].name)
          list.push({
            ...gridColumns[i],
            // sort: sort > -1 ? sort + 1 : i,
            sort: sort > -1 ? sort : i,
            width: width,
            filter: filter
          })
        }
        vm.$ds.fieldList = list
          .sort((a, b) => a.sort - b.sort)
          .map((mapItem, mapIindex) => {
            return {
              ...mapItem,
              sort: mapIindex + 1
            }
          })
      },
      css: `
        .set_senior_table_box .vxe-table--render-default.vxe-editable .vxe-body--column{
          padding: 0.05rem 0;
        }
        .set_senior_table_box .vxe-table--render-default .vxe-cell{
          white-space: normal !important;
          text-overflow: inherit !important;
          max-height: 44px !important;
        }
        .tech-dropdown-pop.set_senior_table_box_operate {
          z-index: 2200 !important;
        }
      
      `,
      items: [
        {
          type: 'table',
          bind_on_editChange: (params) => {
            const { self: vm, value } = params
            if ((value.column.field = 'title' && value.row.title.length > 120)) {
              window.ELEMENT.Message.error(Tech.$t('seniorTable.theTitleLength'))
            }
          },
          isEdit: true,
          id: 'set_senior_table',
          style: {
            minHeight: '3.5rem'
          },
          bind_tableData: '$ds.fieldList',
          gridRowDrop: true,
          draggableHandle: '.el-button',
          commands: {
            // 置顶、上移、下移、置底方法
            moveSortFn: (vm, row, move) => {
              const idPre = vm.$cmd.getIdPre(vm)
              const tableVm = vm.$select(idPre + 'set_senior_table')
              vm.$ds.fieldList = tableVm.data.tableData // 同步tableData数据
              //遍历修改序号
              let rowIndex = vm.$ds.fieldList.findIndex((item) => item.name == row.name) // 查询当前数据的位置
              if (
                (['top', 'up'].includes(move) && rowIndex == 0) ||
                (['buttom', 'down'].includes(move) && vm.$ds.fieldList.length == rowIndex + 1)
              )
                return // rowIndex第一条或者最后一条不执行排序
              vm.$ds.fieldList.splice(rowIndex, 1)

              switch (move) {
                case 'top': // 置顶
                  vm.$ds.fieldList.unshift(row)
                  break
                case 'up': // 上移
                  vm.$ds.fieldList.splice(rowIndex - 1, 0, row)
                  break
                case 'down': // 下移
                  vm.$ds.fieldList.splice(rowIndex + 1, 0, row)
                  break
                default:
                  // 置底
                  vm.$ds.fieldList.push(row)
              }
              vm.$ds.fieldList.map((item, index) => (item.sort = index + 1)) // 重新设置序号
              vm.$cmd.updateSort(vm)
            },
            // 重新设置序号
            updateSort: (vm) => {
              const idPre = vm.$cmd.getIdPre(vm)
              const tableMainTable = vm.$select(idPre + 'table_main_table')
              if (tableMainTable?.instance) {
                const instance = tableMainTable.instance
                const key = instance.id + '_' + instance.userName
                try {
                  // 这里的缓存信息是 vxe-table 的缓存信息 影响到的了排序
                  const store = localStorage.getItem('VXE_CUSTOM_STORE')
                  const storeData = JSON.parse(store)
                  if (key in storeData) {
                    delete storeData[key]
                    localStorage.setItem('VXE_CUSTOM_STORE', JSON.stringify(storeData))
                  }
                } catch (e) {
                  console.log(`【updateSort】`, e)
                }
              }
            }
          },
          items: [
            {
              type: 'container',
              field: 'draggable',
              name: 'draggable',
              style: {
                display: 'flex',
                justifyContent: 'center',
                alignItems: 'center'
              },
              width: 60,
              title: '',
              items: [
                {
                  type: 'button',
                  options: {
                    icon: 'el-icon-rank',
                    size: 'mini',
                    type: 'text'
                  }
                }
              ]
            },
            {
              type: 'seq',
              width: 60,
              title: '#'
            },
            {
              type: 'number',
              field: 'sort',
              name: 'sort',
              maxValue: 100,
              title: Tech.$t('gridView.sort')
            },
            {
              type: 'input',
              field: 'title',
              name: 'title',
              title: Tech.$t('seniorTable.title')
            },
            {
              type: 'switch',
              field: 'visible',
              name: 'visible',
              model: {},
              formatItem: (row, item) => {
                item.model = row
                return item
              },
              title: Tech.$t('seniorTable.reveal')
            },
            {
              type: 'switch',
              field: 'filter',
              name: 'filter',
              model: {},
              formatItem: (row, item) => {
                item.model = row
                return item
              },
              title: Tech.$t('seniorTable.filterable')
            },
            {
              type: 'input',
              field: 'width',
              name: 'width',
              title: Tech.$t('seniorTable.width')
            },
            {
              type: 'select',
              field: 'fixed',
              name: 'fixed',
              options: [
                { label: Tech.$t('seniorTable.left'), value: 'left' },
                { label: Tech.$t('seniorTable.right'), value: 'right' }
              ],
              model: {},
              formatItem: (row, item) => {
                item.model = row

                return item
              },
              title: Tech.$t('seniorTable.beFixedTo')
            },
            {
              type: 'meta-dropdown',
              field: 'operate',
              name: 'operate',
              title: Tech.$t('seniorTable.controls'),
              id: 'set_senior_table_box_operate',
              className: 'set_senior_table_box_operate',
              dropdownClassName: 'set_senior_table_box_operate',
              dropdownStyle: {
                //弹窗的style样式
                width: '1.2rem',
                padding: '0.1rem 0',
                textAlign: 'center'
              },
              dropdownType: 'default',
              splitButton: true,
              placement: 'bottom',

              bind_on_click: (params) => {
                setTimeout(() => {
                  let { self: vm } = params
                  let row = vm.data.items[1].currentData.row
                  vm.$cmd.moveSortFn(vm, row, 'top') // 置顶
                })
              },
              items: [
                {
                  name: 'default',
                  size: 'medium',
                  value: Tech.$t('seniorTable.pinned')
                },
                {
                  type: 'container',
                  id: 'set_senior_table_box_operate_buttons',
                  created: (vm) => {
                    vm.data.items = []
                    let tmpItems = [
                      { lable: Tech.$t('seniorTable.pinned'), value: 'top' },
                      { lable: Tech.$t('seniorTable.moveUp'), value: 'up' },
                      { lable: Tech.$t('seniorTable.moveDown'), value: 'down' },
                      { lable: Tech.$t('seniorTable.bottom'), value: 'buttom' }
                    ]

                    tmpItems.map((sItem, sIndex) => {
                      let buttonItem = {
                        type: 'button',
                        value: sItem.lable,
                        sort: sItem.value,
                        style: {
                          height: '0.36rem',
                          width: '100%',
                          padding: '0',
                          margin: '0',
                          border: '0',
                          lineHeight: '0.36rem',
                          color: '#666',
                          fontSize: '0.14rem',
                          backgroundColor: '#fff'
                        },

                        bind_on_click: (params) => {
                          let { self: vm } = params
                          vm.$cmd.moveSortFn(vm, vm.parent.data.currentData.row, vm.data.sort) // 置顶、上移、下移、置底
                        }
                      }

                      vm.app.updatePageNode(buttonItem, vm, () => {
                        vm.data.items.push(buttonItem)
                      })
                    })
                  },
                  items: []
                }
              ]
            }
          ],
          bind_on_cellClick: (params) => {
            let { self: vm } = params
            vm.$select(
              vm.$cmd.getIdPre(vm) + 'set_senior_table_box_operate_buttons'
            ).data.currentData = params.value
          },
          bind_on_dragRowEnd: (params) => {
            const { self: vm } = params
            const idPre = vm.$cmd.getIdPre(vm)
            const tableVm = vm.$select(idPre + 'set_senior_table')
            vm.$ds.fieldList = tableVm.data.tableData // 同步tableData数据
            vm.$ds.fieldList.map((item, index) => (item.sort = index + 1))
            vm.$cmd.updateSort(vm)
            if (tableVm.instance) {
              tableVm.instance.updateTable()
              tableVm.instance.$nextTick(() => {
                tableVm.instance.rowDrop() // 滚动到对应位置
              })
            }
          }
        }
      ]
    }
  ]
}
