import cloneDeep from 'lodash/cloneDeep'
import mergeWith from 'lodash/mergeWith'
import {
  getRegexRule,
  requiredRule,
  validateMetaModelPropertyFactory
} from '../common/rules/validate'
import toLowerCase from '../common/utils/toLowerCase'
import LookupRender from '../lookup/lookup-render'
import { checkFormChange, getLinkageParams } from '../common/onchange'

import MetaContext from './model/metaContext'
import formUtils from './../../form-utils'

import { formatApipParams } from '../../../snest/utils'
export default class FormRender {
  constructor(modelMeta, options = {}) {
    this.options = options
    this.modelMeta = modelMeta
    this.formatModelMeta()
    this.metaContext = new MetaContext(modelMeta)
    this.defaultSelfAdaptionW = true // 默认一行自适应
    this.disabledRules = options.disabledRules || false
    const data = this.setLayout(options)
    this.items = data
  }

  setLayout(options) {
    const metaContext = this.metaContext
    let items = metaContext.getSortedColumnsList().filter((c) => {
      c.modelId = this.metaContext.modelId
      if (c.hidden) {
        // 隐藏的属性都不可编辑
        return false
      }
      if (options.type === 'add') {
        // 在新增时，排除以下格式的列
        // 1. 属性类型是Related的列
        if (c.typeIsRelated()) {
          return false
        }
        // 2. 自增的id列
        if (c.editor && c.editor.type === 'text') {
          return false
        }
      }
      return true
    })
    this.metaColumnData = items
    if (this.metaContext.customView) {
      for (const item of this.metaContext.customView) {
        this.getCustomView(item, items, options)
      }
      return this.metaContext.customView
    } else if (this.defaultSelfAdaptionW) {
      // 默认为true 目前不用前端视图就用这一种模式
      return this.getDefaultView(items, options)
    }
  }

  formatModelMeta() {
    if (this.modelMeta?.view?.body?.customView) {
      if (!this.modelMeta.view.body.columns) {
        this.modelMeta.view.body.columns = []
      }
      this.modelMeta.view.body.columns = this.mergeCuloms(
        this.modelMeta.view.body.columns,
        this.modelMeta.view.body.customView
      )
    }
  }

  getCustomView(obj, items, options) {
    obj.modelId = this.metaContext.modelId
    if (obj.type === 'row') {
      obj.minCols = this.searchForm ? 3 : 4 // 最少几列 搜索3列 表单tab页4列  列数太少时执行
    }
    if (
      Object.prototype.toString.call(obj.visibleFilter) === '[object Array]' &&
      obj.visibleFilter.length &&
      !obj.display
    ) {
      obj.display = () => {
        return obj.visibleFilter.includes(this.modelMeta.vm.$ds.clickType)
      }
    }
    if (obj.items?.length) {
      obj.items.forEach((i) => {
        let field = items.filter((j) => j.name === i.name)
        if (field?.length === 1) {
          field = field[0]
        } else if (field?.length) {
          field = field.find((k) => i.key === k._metaColumn.key)
        } else if (field?.length === 0) {
          field = null
        }

        if (i.custom === undefined || i.custom === false) {
          if (field?._metaColumn) {
            if (field._metaColumn.custom) {
              field._metaColumn.text = field._metaColumn?.displayName
              Object.assign(i, field._metaColumn)
            } else {
              if (field) {
                const res = this.getFromLayout(field, '', options)
                Object.assign(i, res)
              }
            }
          }
        } else {
          if (field) {
            const res = this.getFromLayout(field, '', options)
            Object.assign(i, Object.assign(res, i))
          }
          if (i.type === 'lookup') {
            Object.assign(i, this.dealLookup(i))
          }
        }

        // this.disableUpdateFn(i, options);

        // disable为fn时要转换
        if (
          i.disabled !== undefined &&
          Object.prototype.toString.call(i.disabled) === '[object String]'
        ) {
          try {
            i.disabled = new Function('return ' + i.disabled)()
          } catch (error) {
            console.log(' === openView Api reqPrep error == ', error)
          }
        }

        // if (i.saveTo) {
        //   if (!this.propParams[i.saveTo]) {
        //     this.propParams[i.saveTo] = [];
        //   }
        //   if (!this.propParams[i.saveTo].includes(i.name)) this.propParams[i.saveTo].push(i.name);
        // }
        // if (i.formPageTitle) {
        //   this.config.formPageHeaderProp = i.name;
        // }
        if (this.searchForm) {
          // 不需要默认值
          i.defaultValue !== undefined && delete i.defaultValue
        }
        this.getCustomView(i, items, options)
      })
    }
  }

  getDefaultView(items, options) {
    let data = []
    var idArray = []
    var newAarray = []
    for (const k of items) {
      const item = cloneDeep(k)
      item.modelId = this.metaContext.modelId
      // //直接取form配的label
      // if (item._metaColumn?.label) item._metaColumn.displayName = item._metaColumn?.label

      try {
        if (
          Object.prototype.toString.call(item._metaColumn.visibleFilter) === '[object Array]' &&
          item._metaColumn.visibleFilter.length &&
          !item._metaColumn.display
        ) {
          item._metaColumn.display = () => {
            return item._metaColumn.visibleFilter.includes(this.modelMeta.vm.$ds.clickType)
          }
        }
      } catch (e) {}

      if (item._metaColumn.saveTo) {
        if (!this.propParams[item._metaColumn.saveTo]) {
          this.propParams[item._metaColumn.saveTo] = []
        }
        if (!this.propParams[item._metaColumn.saveTo].includes(item.name))
          this.propParams[item._metaColumn.saveTo].push(item.name)
      }
      const tt = this.getFromLayout(item, '', options)

      // 解析disable_update
      this.disableUpdateFn(item._metaColumn, options)

      if (item?._metaColumn?.groupConf) {
        if (idArray.indexOf(item._metaColumn.groupConf.id) === -1) {
          let obj = {}
          if (item?._metaColumn?.custom) {
            obj = Object.assign(tt, item._metaColumn)
            if (obj.type === 'lookup') {
              Object.assign(obj, this.dealLookup(item))
            }
          } else {
            obj = Object.assign(item._metaColumn, tt)
          }
          newAarray.push({
            // 'name':tt.name,
            title: obj.groupConf.name,
            id: obj.groupConf.id,
            items: [obj]
          })
          idArray.push(obj.groupConf.id)
        } else {
          newAarray.forEach((dom, k) => {
            if (newAarray[k].id == item._metaColumn.groupConf.id) {
              let obj = {}
              if (item?._metaColumn?.custom) {
                obj = Object.assign(tt, item._metaColumn)
                if (obj.type === 'lookup') {
                  Object.assign(obj, this.dealLookup(item))
                }
              } else {
                obj = Object.assign(item._metaColumn, tt)
              }
              newAarray[k].items.push(obj)
            }
          })
        }
      } else if (item?._metaColumn?.custom) {
        const param = Object.assign(tt, item._metaColumn)
        if (param.type === 'lookup') {
          Object.assign(param, this.dealLookup(item))
        }
        data.push(param)
      } else {
        const obj = Object.assign(item._metaColumn, tt)
        data.push(obj)
      }
    }
    if (newAarray.length) {
      let collapse = {
        type: 'collapse',
        accordion: false,
        dataType: 'Collapse',
        activeNames: [],
        items: [],
        beforeDestroy: (vm) => {
          if (vm.data._groupItemsWatch) {
            // 检查之前是否有对应watch 有则先销毁
            vm.data._groupItemsWatch()
            vm.data._groupItemsWatch = null
          }
        },
        mounted: (vm) => {
          if (vm.data._groupItemsWatch) {
            // 检查之前是否有对应watch 有则先销毁
            vm.data._groupItemsWatch()
            vm.data._groupItemsWatch = null
          }
          const formVm = vm.$select(vm.$cmd.getIdPre(vm) + 'form_main_detail_top_common')
          const form = formVm.$ds.form
          // 建watch
          vm.data._groupItemsWatch = window.Tech.watchFn(
            () => form,
            (val) => {
              // 判断分组的字段组内字段是否都为隐藏字段，如果全部隐藏了，需隐藏当前分组
              const items = vm?.data?.items
              items.forEach((item) => {
                const list = item?.items?.[0]?.items?.[0]?.items
                if (list) {
                  const arr = list.filter(
                    (e) => e.display && e.hidden != true && e.hide !== true && e.type !== 'hidden'
                  )
                  if (arr.length === 0) {
                    item.display = false
                  } else {
                    item.display = true
                  }
                }
              })
            },
            { deep: true, immediate: true }
          )
        }
      }
      let formOuterLabel = {
        type: 'form-container',
        items: []
      }
      // 分组信息在表单左侧显示 不以折叠面板显示
      let isFormOuterLabel = this.modelMeta?.view?.body?.groupType === 'outerLabel' ? true : false
      newAarray.forEach((ele) => {
        const groupObj = formUtils.addRowWrap(ele)
        const idPre = this.modelMeta.vm.$ds.idPreTab || this.modelMeta.vm.$ds.idPre
        // 兼容旧的id
        if (!window.techOldIdMap) {
          window.techOldIdMap = new Map()
        }
        window.techOldIdMap.set(ele.id, idPre + ele.id)
        collapse.activeNames.push(idPre + ele.id)

        let formContainer = {
          type: 'form-container',
          items: groupObj?.items
        }

        if (isFormOuterLabel) {
          formContainer = {
            type: 'form-container',
            className: 'form-group-content-container',
            style: {
              display: 'flex'
            },
            items: [
              {
                type: 'container',
                layoutClassName: 'form-group-container-outer-label',
                css: '.form-group-content-container .form-group-container-outer-label{width:60px;font-weight:600;padding-top:35px;margin-right:8px;font-size:14px;color:#231815}',
                items: [
                  {
                    type: 'text',
                    value: groupObj.title
                  }
                ]
              },
              {
                type: 'form-container',
                style: {
                  flex: 1
                },
                items: groupObj?.items
              }
            ]
          }
        }

        try {
          // 适配之前没有拼菜单id的情况
          let nestSchema = (schema, parent = {}, index = 0) => {
            let oldId = ''
            if (schema && schema?.id === undefined) {
              let distParentId = undefined
              let distIndex = -1
              if (parent?.oldId !== undefined) {
                distParentId = parent.oldId
                distIndex = index
              }
              if (distParentId !== undefined) {
                let appendParam = distIndex
                if (schema?.name !== undefined) {
                  appendParam = schema.name
                }
                oldId = distParentId + '_items_' + appendParam
                schema.oldId = oldId
              }
            }
            let newId = ''
            if (schema && schema?.id === undefined) {
              let distParentId = undefined
              let distIndex = -1
              if (parent?.id !== undefined) {
                distParentId = parent.id
                distIndex = index
              }
              if (distParentId !== undefined) {
                let appendParam = distIndex
                if (schema?.name !== undefined) {
                  appendParam = schema.name
                }
                newId = distParentId + '_items_' + appendParam
                schema.id = newId
              }
            }
            if (oldId) {
              window.techOldIdMap.set(oldId, newId)
            }
            if (schema?.items) {
              for (let i = 0; i < schema.items.length; i++) {
                schema.items[i] = nestSchema(schema.items[i], schema, i)
              }
            }
            return schema
          }

          let handlerOldId = (schema, preParent = {}) => {
            return nestSchema(schema, preParent)
          }
          handlerOldId(window.Tech._cloneDeep(formContainer || {}), {
            id: idPre + ele.id,
            oldId: ele.id
          })
          nestSchema = null
          handlerOldId = null
        } catch (e) {}

        let gObj = {
          title: ele.title,
          id: idPre + ele.id,
          items: [formContainer]
        }
        if (isFormOuterLabel) {
          formOuterLabel.items.push(gObj)
        } else {
          collapse.items.push(gObj)
        }
      })
      if (isFormOuterLabel) {
        data.unshift(formOuterLabel)
      } else {
        data.unshift(collapse)
      }
    }

    // js字符串方法 转 js方法
    if (!data?.[0]?.__isStrFuncChange) {
      // 在第一个元素添加是否初次转换过的标识
      data = this.metaContext.dealCustomViewStrFunc(data)
      if (data?.[0] !== undefined) {
        data[0].__isStrFuncChange = true
      }
    }

    return data
  }

  // eslint-disable-next-line no-unused-vars
  getFromLayout(item, type, options) {
    const isTextShow = options.type !== 'add'
    if (!item) return {}
    const itemConfig = {
      name: item.name,
      text: this.metaContext.getColumnFullName(item),
      readonly: item.readonly, // || item.typeIsRelated() || (item.typeIsCompute() && !item.computeObj.set)
      rules: [],
      // disabled: item._metaColumn.disabled || false,
      placeholder: item.placeholder || item._metaColumn?.placeholder || undefined,
      modelId: this.metaContext.modelId,
      dataType: item.datatype,
      name: item._metaColumn.name,
      validation: item._metaColumn.validation,
      selectOption: item._metaColumn.selectOption
    }
    let disableType = Object.prototype.toString.call(item._metaColumn.disabled)
    if (disableType === '[object Boolean]') {
      itemConfig.disabled = item._metaColumn.disabled
    } else if (disableType !== '[object String]' && disableType !== '[object Function]') {
      if (item._metaColumn?.widget != 'codeeditor') {
        itemConfig.disabled = false
      }
    }
    // 如果有配置disable_update 则以disable_update优先
    if (item._metaColumn?.disable_update !== undefined) {
      delete itemConfig.disabled
    }
    const curColumn = this.modelMeta.view.body.columns.find(
      (columnsItem) => columnsItem?.name == itemConfig.name
    )
    const isColumnRequire = curColumn?.required
    // cache配置，获取缓存默认值
    if (curColumn?.cache) {
      itemConfig.cache = curColumn.cache
    }

    if (item?._metaColumn?.clearable !== undefined) {
      itemConfig.clearable = item._metaColumn.clearable
    }

    if (this.modelMeta.vm.data.isRule == false && !isColumnRequire) {
      //如果view中的columns有require也要添加必填
      item._metaColumn.validation = {}
    }
    // search中columns配置了required也需要添加
    if (item.required && (this.modelMeta.vm.data.isRule != false || isColumnRequire)) {
      itemConfig.rules.push(requiredRule(item))
    }

    if (item.visible !== undefined) {
      if (item.visible !== true && item.visible !== false) {
        itemConfig.visibility = (formData) => {
          let str = item.visible.replace('this', 'formData')
          let fn = new Function('formData', 'return ' + str)
          return fn(formData)
        }
      }
    }

    // 表单不是来源于tab情况下 在主表单过滤tab子表单的包含字段的显示
    try {
      if (!this.options.isFromTab && this.modelMeta.view.body && this.modelMeta.view.body.tabs) {
        let tabsArr = this.modelMeta.view.body.tabs
        // eslint-disable-next-line @typescript-eslint/prefer-for-of
        for (let v = 0; v < tabsArr.length; v++) {
          if (
            tabsArr[v]?.body &&
            tabsArr[v].body.type === 'form' &&
            tabsArr[v].body.field === undefined
          ) {
            let subColumns = tabsArr[v].body?.columns
            if (subColumns.indexOf(item.name) !== -1) {
              itemConfig.type = 'hidden'
              break
            }
          }
        }
      }
    } catch (e) {}

    let filterArr = ['onetomany'] //  'manytomany'
    // 组件属性Map
    let compsMap = {
      codeeditor: {
        colStyle: { width: '100%' },
        span: 24
      }
      // InputText: {
      //   type: 'input'
      // }
    }

    // 处理自定义view弹窗相关逻辑
    if (item._metaColumn?.view?.customClick?.customSelect) {
      item._metaColumn.view.customClick = this.dealCustomView(
        item._metaColumn?.view?.customClick?.customSelect,
        item._metaColumn?.view?.customClick || {}
      )
    }
    if (filterArr.includes(item.datatype)) {
      itemConfig.type = 'hidden'
    } else if (['manytoone'].includes(item.datatype)) {
      if (item?._metaColumn) {
        item._metaColumn.widget = 'lookup'
      }
      itemConfig.type = 'lookup'
      Object.assign(itemConfig, this.dealLookup(item))
    } else if (
      (['selection', 'manytomany'].includes(item.datatype) &&
        ['method', 'model', 'manytomany'].includes(
          String.prototype.toLowerCase.call(String(item._metaColumn.selectionType))
        ) &&
        !item._metaColumn.multiple &&
        item._metaColumn.widget !== 'cascader') ||
      item._metaColumn.transformLookup
    ) {
      // 针对selection类型多选的情况需要转lookup的配置transformLookup可以展示成lookup
      if (item?._metaColumn) {
        item._metaColumn.widget = 'lookup'
      }
      itemConfig.type = 'lookup'
      itemConfig.options = []
      if (item?._metaColumn) {
        item._metaColumn.widget = 'lookup'
      }
      Object.assign(itemConfig, this.dealLookup(item))
    } else {
      switch (toLowerCase(item.datatype)) {
        case 'dict':
          itemConfig.type = 'select'
          itemConfig.options = []
          item._metaColumn.remote = true
          itemConfig.needPreloadData = true
          itemConfig.defaultValue = item._metaColumn.defaultValue
          itemConfig.getData = async (f) => {
            let sendItemConfig = item?._metaColumn || item || {}
            let lookupFilter = []

            let linkageParams = {}
            let appendAppParams = {
              app: this.modelMeta?.vm?.$ds?._metaParamsApp || 'base'
            }
            let sendF = f?.mForm === undefined ? f : f.mForm
            let getLinkageRes = getLinkageParams(sendItemConfig, sendF) // 拼接联动参数
            if (Object.prototype.toString.call(getLinkageRes) === '[object Object]') {
              linkageParams = getLinkageRes
            } else if (Object.prototype.toString.call(getLinkageRes) === '[object Array]') {
              lookupFilter = this.modelMeta.vm.$cmd.meta.addSearch(lookupFilter, getLinkageRes)
            }
            // 搜索默认值的选线
            // 多选的情况
            const hasMultiFilter =
              f.config.multiple &&
              (f.config?.defaultValue?.length || f.config.dataSource?.form[f.config.name]?.length)

            if (
              (f.config.defaultValue || f.config.dataSource?.form[f.config.name]) &&
              Object.prototype.toString.call(f.config.defaultValue) !== '[object Object]' &&
              hasMultiFilter &&
              !f.config.hasDefaultSearch
            ) {
              // 需要兼容多选的情况
              lookupFilter.push([
                f.config.dictValue,
                f.config.multiple ? 'in' : '=',
                f.config.dataSource.form[f.config.name] || f.config.defaultValue
              ])
            }
            const selectionMethod = item._metaColumn?.selectionMethod || item.selectionMethod
            let getModelName = item._metaColumn?.modelName || item.modelName

            let sendParams = {
              model: getModelName ? getModelName : this.modelMeta.vm.$ds._metaParamsModel,
              service: selectionMethod ? selectionMethod : 'lookup',
              args: {
                filter: lookupFilter,
                useDisplayForModel: true,
                // limit: 21,
                // offset: 0,
                field: item._metaColumn?.name || item.name,
                keyword: f?.query || '', // 添加搜索参数
                ...linkageParams,
                ...appendAppParams
              }
            }
            try {
              let reqPrepFn = itemConfig.reqPrep || item._metaColumn?.reqPrep || item.reqPrep
              if (reqPrepFn) {
                if (Object.prototype.toString.call(reqPrepFn) === '[object String]') {
                  reqPrepFn = new Function('return ' + reqPrepFn).bind(window)()
                }
                sendParams = reqPrepFn(
                  tech_app.page.getNode(tech_app.page.data.id),
                  sendParams,
                  itemConfig
                )
                itemConfig.reqPrep = reqPrepFn
              }
            } catch (e) {}

            let res = await this.modelMeta.vm.request('lookup', sendParams)

            try {
              let reqAfterFn = itemConfig.reqAfter || item._metaColumn?.reqAfter || item.reqAfter
              if (reqAfterFn) {
                if (Object.prototype.toString.call(reqAfterFn) === '[object String]') {
                  reqAfterFn = new Function('return ' + reqAfterFn).bind(window)()
                }
                res = reqAfterFn(tech_app.page.getNode(tech_app.page.data.id), res, itemConfig)
                itemConfig.reqAfter = reqAfterFn
              }
            } catch (e) {}

            // 记录有默认值的情况，是否已经搜索过，用于判断是否添加filter
            if (res.data) {
              f.config.hasDefaultSearch = true
            }

            item._metaColumn.values = res?.data || []
            // console.log(' ==== res == ', res);
            let tmpOptions = []
            for (let k in item._metaColumn.values) {
              if (item._metaColumn.values[k].label) {
                tmpOptions.push({
                  ...item._metaColumn.values[k],
                  text: item._metaColumn.values[k].label,
                  value: item._metaColumn.values[k].value
                })
              }

              // 去重添加
              const matchIndedx = itemConfig.options.findIndex(
                (option) => option.value == item._metaColumn.values[k].value
              )
              if (matchIndedx === -1) {
                itemConfig.options.push({
                  ...item._metaColumn.values[k],
                  text: item._metaColumn.values[k].label,
                  value: item._metaColumn.values[k].value
                })
              }
            }

            return { items: tmpOptions }
          }
          if (itemConfig.readonly || item.readonly === true) {
            itemConfig.disabled = true
          }
          itemConfig.showSearchValue = (val) => {
            let reVal = val
            const findObj = itemConfig.options.find((findItem) => findItem.value === val)
            if (findObj) {
              reVal = findObj.text || ''
            }
            return reVal
          }
          break
        case 'auto':
          itemConfig.readonly = true
          itemConfig.visibility = isTextShow != null ? isTextShow : () => this.defaultVisibility()
          break
        case 'boolean':
          itemConfig.type = 'select' // select switch *test mock
          itemConfig.options = [
            { text: Tech.$t('gridView.yes'), value: true },
            { text: Tech.$t('gridView.no'), value: false }
          ]
          itemConfig.showSearchValue = (val) => {
            return val ? Tech.$t('gridView.yes') : Tech.$t('gridView.no')
          }
          break
        // 分时间点和时间范围

        case 'date':
          itemConfig.type = 'datepicker'
          if ((item?._metaColumn && item._metaColumn.dateRange) || item._metaColumn.daterange) {
            item._metaColumn.widget = 'daterange'
          }
          if (
            (item?._metaColumn && item._metaColumn.datetimeRange) ||
            item._metaColumn.datetimerange
          ) {
            item._metaColumn.widget = 'datetimerange'
          }
          itemConfig.pickerType = item._metaColumn.widget || 'date'
          itemConfig.size = 'mini'
          itemConfig.format = item._metaColumn.dateFormat || 'yyyy-MM-dd'
          itemConfig.valueFormat = item._metaColumn.dateFormat || 'yyyy-MM-dd'
          break
        case 'datetime':
          itemConfig.type = 'datepicker'

          if (
            !item._metaColumn.widget &&
            (item?._metaColumn?.dateRange || item?._metaColumn?.daterange)
          ) {
            item._metaColumn.widget = 'daterange'
          }
          if (
            !item._metaColumn.widget &&
            (item?._metaColumn?.datetimeRange || item?._metaColumn?.datetimerange)
          ) {
            item._metaColumn.widget = 'datetimerange'
          }
          // 兼容webgme返回字段不匹配问题
          // if (['InputText', 'PulldownList', 'RadioButton'].includes(item._metaColumn.widget)) {
          //   item._metaColumn.widget = 'datetime'
          // }
          itemConfig.pickerType = item._metaColumn.widget || 'datetime'
          itemConfig.size = 'mini'
          itemConfig.format = item._metaColumn.dateFormat || 'yyyy-MM-dd HH:mm:ss'
          itemConfig.valueFormat = item._metaColumn.dateFormat || 'yyyy-MM-dd HH:mm:ss'
          break
        case 'integer':
        case 'long': {
          break
        }
        case 'float':
        case 'double':
          itemConfig.type = 'input'
          break
        case 'bigdecimal': {
          itemConfig.type = 'input'
          break
        }
        case 'enum': {
          itemConfig.type = 'select'
          itemConfig.options = []
          if (item._metaColumn?.attrs?.Values) {
            for (let k in item._metaColumn.attrs.Values) {
              itemConfig.options.push({
                text: item._metaColumn.attrs.Values[k],
                value: k
              })
            }
          } else {
            for (let k in item._metaColumn.values) {
              if (item._metaColumn.values[k].label) {
                itemConfig.options.push({
                  text: item._metaColumn.values[k].label,
                  value: item._metaColumn.values[k].value
                })
              } else {
                itemConfig.options.push({
                  text: item._metaColumn.values[k],
                  value: k
                })
              }
            }
          }

          if (itemConfig.readonly || item.readonly === true) {
            itemConfig.disabled = true
          }
          itemConfig.showSearchValue = (val) => {
            let reVal = val
            const findObj = itemConfig.options.find((findItem) => findItem.value === val)
            if (findObj) {
              reVal = findObj.text || ''
            }
            return reVal
          }
          break
        }
        case 'selection': {
          itemConfig.type = 'select'
          itemConfig.options = []
          item._metaColumn.remote = false
          if (item._metaColumn?.multiple !== undefined) {
            itemConfig.multiple = item._metaColumn?.multiple ?? false
          }
          if (item._metaColumn.widget === 'cascader') {
            // 如果没有单独配置props.multiple，则同步设置props。multiple
            if (!item._metaColumn.props) {
              item._metaColumn.props = {}
            }
            if (item._metaColumn.props.multiple === undefined) {
              item._metaColumn.props.multiple = item._metaColumn.multiple
            }
          }
          // ['method', 'model', 'manyToMany'].includes(item._metaColumn.selectionType)
          // item.datatype === 'manytomany'
          if (
            ['method', 'model', 'manytomany'].includes(
              String.prototype.toLowerCase.call(String(item._metaColumn.selectionType))
            )
          ) {
            if (!item._metaColumn.multiple && item._metaColumn.widget !== 'cascader') {
              // 若数据类型是 manytomany 没有配置 multiple则不走select
              break
            } else {
              item._metaColumn.remote = true // 配置远程搜索
              // 请求接口异步拼接options
              // this.modelMeta.vm;
              // console.log(' ==== this.modelMeta.vm === ', this.modelMeta.vm);
              itemConfig.getData = async (f) => {
                let sendItemConfig = item?._metaColumn || item || {}
                let lookupFilter = []

                let linkageParams = {}
                let sendF = f?.mForm === undefined ? f : f.mForm
                let getLinkageRes = getLinkageParams(sendItemConfig, sendF) // 拼接联动参数
                if (Object.prototype.toString.call(getLinkageRes) === '[object Object]') {
                  linkageParams = getLinkageRes
                } else if (Object.prototype.toString.call(getLinkageRes) === '[object Array]') {
                  lookupFilter = this.modelMeta.vm.$cmd.meta.addSearch(lookupFilter, getLinkageRes)
                }

                // 搜索默认值的选线
                // 多选的情况
                const hasMultiFilter =
                  f.config.multiple &&
                  (f.config?.defaultValue?.length ||
                    f.config.dataSource?.form[f.config.name]?.length)

                if (
                  (f.config.defaultValue || f.config.dataSource?.form[f.config.name]?.length) &&
                  Object.prototype.toString.call(f.config.defaultValue) !== '[object Object]' &&
                  !hasMultiFilter &&
                  !f.config.hasDefaultSearch
                ) {
                  // 需要兼容多选的情况
                  lookupFilter.push([
                    'id',
                    '=',
                    f.config.dataSource.form[f.config.name] || f.config.defaultValue
                  ])
                } else if (
                  hasMultiFilter &&
                  !f.config.hasDefaultSearch &&
                  !f.config.dataSource?.form[f.config.name]?.length
                ) {
                  // 多选的情况
                  lookupFilter.push([
                    'id',
                    'in',
                    f.config.dataSource.form[f.config.name] || f.config.defaultValue
                  ])
                }

                const selectionMethod = item._metaColumn?.selectionMethod || item.selectionMethod
                let getModelName2 = item._metaColumn?.modelName || item.modelName

                let sendParams = {
                  model: getModelName2 ? getModelName2 : this.modelMeta.vm.$ds._metaParamsModel,
                  service: selectionMethod ? selectionMethod : 'lookup',

                  args: {
                    filter: lookupFilter,
                    useDisplayForModel: true,
                    // limit: 21,
                    // offset: 0,
                    field: item._metaColumn?.name || item.name,
                    keyword: f?.query || '', // 添加搜索参数
                    ...linkageParams
                  }
                }
                // 判断是否有app
                if (item?._metaColumn?.appName) {
                  sendParams.app = item._metaColumn.appName
                }
                try {
                  let reqPrepFn = itemConfig.reqPrep || item._metaColumn?.reqPrep || item.reqPrep
                  if (reqPrepFn) {
                    if (Object.prototype.toString.call(reqPrepFn) === '[object String]') {
                      reqPrepFn = new Function('return ' + reqPrepFn).bind(window)()
                    }
                    sendParams = reqPrepFn(
                      tech_app.page.getNode(tech_app.page.data.id),
                      sendParams,
                      itemConfig
                    )
                    itemConfig.reqPrep = reqPrepFn
                  }
                } catch (e) {}

                let res = await this.modelMeta.vm.request('lookup', sendParams)

                try {
                  let reqAfterFn =
                    itemConfig.reqAfter || item._metaColumn?.reqAfter || item.reqAfter
                  if (reqAfterFn) {
                    if (Object.prototype.toString.call(reqAfterFn) === '[object String]') {
                      reqAfterFn = new Function('return ' + reqAfterFn).bind(window)()
                    }
                    res = reqAfterFn(tech_app.page.getNode(tech_app.page.data.id), res, itemConfig)
                    itemConfig.reqAfter = reqAfterFn
                  }
                } catch (e) {}

                // 记录有默认值的情况，是否已经搜索过，用于判断是否添加filter
                if (res.data) {
                  f.config.hasDefaultSearch = true
                }
                item._metaColumn.values = res?.data || []
                // console.log(' ==== res == ', res);
                // 级联选择器，通过视图配置level，截取展示层级
                if (item._metaColumn.widget == 'cascader') {
                  item._metaColumn.values.forEach((el1) => {
                    if (item._metaColumn.props?.level == 1) {
                      delete el1.children
                    } else {
                      if (el1?.children && el1?.children.length > 0) {
                        el1?.children.forEach((el2) => {
                          if (item._metaColumn.props?.level == 2) {
                            delete el2.children
                          }
                        })
                      }
                    }
                  })
                }
                let tmpOptions = []
                for (let k in item._metaColumn.values) {
                  if (item._metaColumn.values[k].label) {
                    tmpOptions.push({
                      ...item._metaColumn.values[k],
                      text: item._metaColumn.values[k].label,
                      value: item._metaColumn.values[k].value
                    })

                    // 去重添加
                    const matchIndedx = itemConfig.options.findIndex(
                      (option) => option.value == item._metaColumn.values[k].value
                    )
                    if (matchIndedx === -1) {
                      itemConfig.options.push({
                        ...item._metaColumn.values[k],
                        text: item._metaColumn.values[k].label,
                        value: item._metaColumn.values[k].value
                      })
                    }
                  }
                }
                return { items: tmpOptions }
              }
              // itemConfig.getData(); // 为了初始显示
            }
          }

          for (let k in item._metaColumn.values) {
            if (item._metaColumn.values[k].label) {
              itemConfig.options.push({
                ...item._metaColumn.values[k],
                text: item._metaColumn.values[k].label,
                value: item._metaColumn.values[k].value
              })
            }
          }
          if (itemConfig.readonly || item.readonly === true) {
            itemConfig.disabled = true
          }
          itemConfig.showSearchValue = (val, options, type) => {
            if (type == 'cascader') {
              // 级联情况
              if (Object.prototype.toString.call(val) === '[object Array]') {
                // 数组情况
                const recursionVal = (options, showIndex, showStr) => {
                  let itemObj = options.find((item) => item.value == val[showIndex])
                  showStr.push(itemObj?.label || '')
                  if (itemObj.children) {
                    showIndex++
                    recursionVal(itemObj.children, showIndex, showStr)
                  }
                  let newStr = showStr.toString().replace(/,/g, '/')

                  return newStr
                }
                let showIndex = 0
                let showStr = []
                return recursionVal(options, showIndex, showStr)
              } else {
                // 不是数组情况
                const recursionVal = (options, showStr) => {
                  if (options) {
                    for (let i1 = 0; i1 < options.length; i1++) {
                      if (showStr.length) {
                        break
                      }
                      let itemObj = options.find((item) => item.value == val)
                      if (itemObj) {
                        if (showStr.length === 0) {
                          showStr.push(itemObj?.label || '')
                          break
                        }
                      }

                      if (options[i1]?.children && !showStr.length) {
                        recursionVal(options[i1]?.children, showStr)
                      }
                    }
                  }
                  let newStr = showStr.toString().replace(/,/g, '/')

                  return newStr
                }
                let showStr = []

                return recursionVal(options, showStr)
              }
            } else {
              // 非级联情况
              if (
                itemConfig?.multiple &&
                Object.prototype.toString.call(val) === '[object Array]'
              ) {
                // 多选值为数组情况
                let reArr = []
                val.map((itemV) => {
                  let reVal = itemV
                  let findObj
                  if (options) {
                    findObj = options.find((findItem) => findItem.value === itemV)
                  } else {
                    findObj = itemConfig.options.find((findItem) => findItem.value === itemV)
                  }
                  if (findObj) {
                    let text = findObj.text ? findObj.text : findObj.label
                    reVal = text || ''
                  }
                  reArr.push(reVal)
                })
                return reArr.join(' ')
              } else {
                // 单选非数组情况
                let reVal = val
                let findObj
                if (options) {
                  findObj = options.find((findItem) => findItem.value === val)
                } else {
                  findObj = itemConfig.options.find((findItem) => findItem.value === val)
                }
                if (findObj) {
                  let text = findObj.text ? findObj.text : findObj.label
                  reVal = text || ''
                }
                return reVal
              }
            }
          }
          break
        }
        case 'enummodel': {
          itemConfig.type = 'select'
          itemConfig.options = item.editor.options.data.map((kv) => ({
            text: kv.label,
            value: kv.id
          }))
          if (itemConfig.readonly) {
            itemConfig.disabled = true
          }
          break
        }
        case 'string': {
          itemConfig.trim = item.isTrim
          itemConfig['showPassword'] = item.password // 密码类型
          if (item.validation) {
            // itemConfig.rules.push(
            //   getRegexRule(
            //     item.validation.regex,
            //     `${item.validation.type ? item.validation.type : 'validation'
            //     } 校验失败`
            //   )
            // );
            let itemName = item?.text || item?.displayName || item?.name || ''
            let validMsg = item.validation.message || itemName + Tech.$t('gridView.formatError')
            itemConfig.rules.push(getRegexRule(item.validation.regex, validMsg))
          }
          break
        }
        case 'text': {
          itemConfig.type = 'textarea'
          itemConfig.trim = item.isTrim
          // if (item._metaColumn.widget == 'codeeditor') {
          //   itemConfig.layoutStyle = { width: '98.5%' }
          // }

          break
        }
        case 'json': {
          itemConfig.type = 'codeeditor'
          for (const key in compsMap.codeeditor) {
            if (Object.hasOwnProperty.call(compsMap.codeeditor, key)) {
              const element = compsMap.codeeditor[key]
              itemConfig[key] = element
            }
          }
          break
        }
        case 'file': {
          itemConfig.type = 'upload'
          itemConfig.multiple = item._metaColumn.multiple
          itemConfig.accept = item._metaColumn.contentType
          itemConfig['auto-upload'] = true
          itemConfig.action = ''
          // length 为后端模型配置(默认值为1)，limit 为视图配置
          itemConfig.limit = item?._metaColumn?.limit ?? item._metaColumn.length ?? 1
          itemConfig.tip = Tech.$t('gridView.uploadMax') + (itemConfig.limit ?? 1)
          if (itemConfig.accept)
            itemConfig.tip += Tech.$t('gridView.uploadFileType') + itemConfig.accept
          // 文件下载服务地址
          itemConfig.downloadApi = (id) => {
            return window.Tech.metaApi.metaDownload(window.tech.apiHost, id)
          }
          // 文件上传服务
          itemConfig.uploadApi = (param, uploadProgressEvent) => {
            const maxSize = item._metaColumn.maxSize
            if (maxSize) {
              if (maxSize.indexOf('KB') > -1 || maxSize.indexOf('kb') > -1) {
                if (param.file.size / 1024 > parseFloat(maxSize))
                  return Promise.reject(Tech.$t('translationManagement.maxSizeTxt') + maxSize)
              } else {
                if (param.file.size / 1024 / 1024 > parseFloat(maxSize)) {
                  return Promise.reject(
                    Tech.$t('translationManagement.maxSizeTxt') + parseFloat(maxSize) + 'Mb'
                  )
                }
              }
            }
            const paramsData = new FormData()
            paramsData.append('file', param.file)
            paramsData.append('model_id', this.modelMeta.vm.$ds._metaParamsModel)
            paramsData.append('uid', param.file.uid)
            paramsData.append('description', '')
            if (window?.$tech?.uploadPublicViews?.includes(this.modelMeta?.view?.view_id)) {
              paramsData.append('bucketType', 'public')
            }
            return window.Tech.metaApi.metaUpload(
              paramsData,
              window.tech.apiHost,
              uploadProgressEvent
            )
          }
          break
        }
        case 'condition': {
          itemConfig.type = 'select'
          itemConfig.options = itemConfig.selectOption
        }
        case 'manytomany': {
          itemConfig.type = 'lookup'
          itemConfig.options = []
          if (item?._metaColumn) {
            item._metaColumn.widget = 'lookup'
          }
          Object.assign(itemConfig, this.dealLookup(item))
        }
        default:
          break
      }
    }
    // console.log(itemConfig)
    if (item.widget && item.widget != 'radio' && item.widget != 'InputText') {
      if (
        ![
          'year',
          'month',
          'date',
          'dates',
          'months',
          'years',
          'week',
          'datetime',
          'datetimerange',
          'daterange',
          'monthrange'
        ].includes(item.widget)
      ) {
        itemConfig.type = item.widget
      }
      if (compsMap[item.widget]) {
        for (const key in compsMap[item.widget]) {
          if (Object.hasOwnProperty.call(compsMap[item.widget], key)) {
            const element = compsMap[item.widget][key]
            itemConfig[key] = element
          }
        }
      }
    }
    itemConfig.rules.push({
      trigger: 'change',
      validator: validateMetaModelPropertyFactory(item)
    })
    // 禁用校验
    if (this.disabledRules) {
      delete itemConfig.rules
    }

    // 处理联动方法
    checkFormChange(itemConfig, item._metaColumn, this.modelMeta)

    return itemConfig
  }
  dealLookup(item) {
    // 异步调用方法，取消默认请求
    if (item._metaColumn?.defaultSelected) {
      this.modelMeta.vm.$ds.delaySearch = true
    }

    let itemConfig = {}
    if (item._metaColumn?.multiple !== undefined) {
      itemConfig.multiple = item._metaColumn?.multiple ?? false
    }
    itemConfig.collapseTags = item._metaColumn?.collapseTags ?? false
    let selectLookup = new LookupRender(
      {
        formObj: this,
        formModelMeta: this.modelMeta,
        ...item,
        modelId: this.metaContext.modelId
      },
      {
        tabsRenderObj: this.options.tabsRenderObj,
        metaPageObj: this.options.metaPageObj,
        baseUrl: this.baseUrl,
        pageTableKey: this.options.pageTableKey,
        getCurVm: () => {
          return this.options.getCurVm()
        }
      }
    )

    itemConfig.lookupConfig = selectLookup.config
    itemConfig.showSearchValue = (val, options, type) => {
      if (type == 'cascader') {
        const recursionVal = (options, showIndex, showStr) => {
          let itemObj = options.find((item) => item.id == val[showIndex])
          showStr.push(itemObj.name)
          if (itemObj.children) {
            showIndex++
            recursionVal(itemObj.children, showIndex, showStr)
          }
          let newStr = showStr.toString().replace(/,/g, '/')

          return newStr
        }
        let showIndex = 0
        let showStr = []
        return recursionVal(options, showIndex, showStr)
      } else if (selectLookup.option) {
        itemConfig.option = selectLookup.option
        let reVal = val
        const findObj = itemConfig.option.find((findItem) => findItem.value === val)
        if (findObj) {
          reVal = findObj.label || ''
        }
        return reVal
      }
    }
    return itemConfig
  }
  // useOpenView自定义确认按钮事件
  async dealCustomConfirm(selectVm, confirm, result = []) {
    let cusConfirm = confirm
    if (cusConfirm) {
      if (Object.prototype.toString.call(cusConfirm) === '[object String]') {
        try {
          cusConfirm = window.tech_app.utils._cloneDeep(cusConfirm)
          cusConfirm = new Function('return ' + confirm)()
        } catch (error) {
          console.log(' === openView Api reqPrep error == ', error)
        }
      }
      let confirmResult = undefined
      if (selectVm.$cmd.isAsync(cusConfirm)) {
        confirmResult = await cusConfirm(selectVm, result)
      } else {
        confirmResult = cusConfirm(selectVm, result)
      }
      if (confirmResult === false) {
        return
      }
    }
  }
  // 处理openview相关逻辑
  dealCustomView(customSelect, srcView = {}) {
    // 根据参数生成schema结构
    let dialogSchema, useSelectTreeSchema, useSelectListSchema, openViewSchema
    if (customSelect.showType === 'dialog') {
      dialogSchema = {
        type: 'dialog',
        title: '',
        width: '',
        hasFooter: false,
        created(vm) {
          // 设置弹框标题和宽度
          vm.data.title = vm.data.customSelect.title
          vm.data.width = vm.data.customSelect.width || '60%'
          vm.data.hasFooter = vm.data.customSelect.hasFooter === false ? false : true
          // 关闭来源表单的搜索展开项
          const dropdownObj = vm.$select(vm.data.dataSource?.idPre + 'dropdown_pop_form')
          if (dropdownObj?.instance?.setOpen) {
            dropdownObj.instance.setOpen(false)
          }
        },
        beforeOperate: async (params) => {
          let fieldVm = params.self
          if (!fieldVm.data.view.customClick.dataSource) {
            fieldVm.data.view.customClick.dataSource = {}
          }
          fieldVm.data.view.customClick.dataSource.operateId = fieldVm.data.id
          // 若没有配置 __parentId 放底部容器 container_page_bottom
          if (!fieldVm.data.view.customClick.__parentId) {
            let curPre = fieldVm.$ds.idPreTab ?? fieldVm.$ds.idPre
            let bottomId = curPre + 'container_page_bottom'
            if (fieldVm.$select(bottomId)) {
              fieldVm.data.view.customClick.__parentId = bottomId
            }
            if (!fieldVm.data.view.customClick?.customSelect?.useOpenView?.app) {
              try {
                // 同步app参数
                if (!fieldVm.data.view.customClick.dataSource) {
                  fieldVm.data.view.customClick.dataSource = {}
                }
                if (fieldVm.$ds._metaParamsApp) {
                  fieldVm.data.view.customClick.dataSource._metaParamsApp =
                    fieldVm.$ds._metaParamsApp
                }
              } catch (e) {}
            }
          }
          return true
        },
        items: []
      }
    }
    // 触发onChange
    let triggerOnChange = (triggerVm, key, value) => {
      try {
        let mForm = triggerVm?.instance?.mForm || triggerVm?.instance?.useForm
        let getOnChange = mForm?.fields?.get(key)?.config?.onChange
        if (mForm && getOnChange) {
          if (Object.prototype.toString.call(getOnChange) === '[object String]') {
            try {
              getOnChange = new Function('return ' + getOnChange)().bind(window)
            } catch (e) {
              console.log(key, ' === onChange error == ', e)
            }
          }
          getOnChange(mForm, value, { prop: key })
        }
      } catch (e) {}
      // 主表单情况 调用表单改变
      try {
        if (triggerVm?.$ds?.idPre && !triggerVm?.$ds?.idPreTab) {
          triggerVm
            .$select(triggerVm.$ds.idPre + 'form_main_detail_top_common')
            ?.instance?.formChangeFieldInput(
              triggerVm?.instance?.mForm?.values || triggerVm?.instance?.useForm?.values || {}
            )
        }
      } catch (e) {}
    }
    // 使用选择树情况
    if (customSelect.useSelectTree) {
      const { preId, httpMetaConfig, type, confirm } = customSelect.useSelectTree
      let treeDataSource = {
        data: []
      }
      let treeItem = {
        id: `${preId}custom_dialog_tree`,
        type: 'tree',
        name: 'custom_dialog_tree_data',
        transformTotree: true,
        bind_data: '$ds.data',
        toolbarConfig: {
          search: {
            showInput: true
          }
        },
        created: async (vm) => {
          const selectVm = vm.$select(vm.$ds.operateId)
          vm.$ds.data = []
          // 请求数据
          if (httpMetaConfig) {
            try {
              let httpMetaConfigFormat = await formatApipParams({
                formatData: httpMetaConfig,
                vm: selectVm
              })
              const res = await window.Tech.httpMeta(httpMetaConfigFormat)
              vm.$ds.data = res.data
            } catch (error) {
              console.log(error)
            }
          }
        }
      }
      dialogSchema.style = { zIndex: 2220 }
      useSelectTreeSchema = {
        type: 'container',
        style: {
          maxHeight: '4rem',
          minHeight: '30vh'
        },
        css: `
          #${preId}custom_dialog_tree .ii-tree-main{
            padding: 5px 0 !important;
          }
        `,
        dataSource: treeDataSource,
        items: [treeItem]
      }
      // 调整弹窗宽度
      if (dialogSchema) {
        dialogSchema.width = '530px'
      }
      const originCreated = treeItem.created
      switch (type) {
        case 'single':
          treeDataSource.curClickTreeNode = null
          treeItem.treeConfig = {
            nodeKey: 'id',
            defaultExpandAll: true,
            delUnParent: true,
            showTree: true
          }
          treeItem.bind_curNodeKey = '${$ds.curClickTreeNode?.value}'
          treeItem.created = async (vm) => {
            const selectVm = vm.$select(vm.$ds.operateId)
            const selectArr =
              window.Tech._cloneDeep(selectVm.$ds.form[`${selectVm.instance.name}___values`]) || []
            vm.$ds.curClickTreeNode = selectArr
            await originCreated(vm)
          }
          treeItem.bind_on_clickTreeNode = (params) => {
            const { id, name } = params.value.selectedData.data
            params.self.$ds.curClickTreeNode = { value: id, label: name }
          }
          break

        case 'mutiple':
          treeDataSource.checkList = []
          treeDataSource.curCheckedKeys = []
          treeItem.isPermission = true
          treeItem.bind_curCheckedKeys = '$ds.curCheckedKeys'
          treeItem.bind_on_check = (params) => {
            params.self.$ds.checkList = params.value.checked.checkedNodes.map((item) => ({
              value: item.id,
              label: item.name
            }))
          }
          treeItem.created = async (vm) => {
            const selectVm = vm.$select(vm.$ds.operateId)
            const selectArr =
              window.Tech._cloneDeep(selectVm.$ds.form[`${selectVm.instance.name}___values`]) || []
            vm.$ds.curCheckedKeys = selectArr.map((item) => item.value)
            vm.$ds.checkList = selectArr.map((item) => item.value)
            await originCreated(vm)
          }
          break
        default:
          break
      }
      dialogSchema.bind_on_opreates = (params) => {
        // 点击按钮
        const { self: vm, value } = params

        if (value.type === 'confirm') {
          // 拿到table选中的id
          const treeVm = vm.$select(`${preId}custom_dialog_tree`)
          // 赋值给input
          const selectVm = vm.$select(vm.$ds.operateId)
          if (type === 'mutiple') {
            selectVm.$ds.form[selectVm.instance.name] = window.Tech._cloneDeep(treeVm.$ds.checkList)
          } else if (type === 'single') {
            selectVm.$ds.form[selectVm.instance.name] = window.Tech._cloneDeep(
              treeVm.$ds.curClickTreeNode
            )
          }
          triggerOnChange(
            selectVm,
            selectVm.instance.name,
            selectVm.$ds.form[selectVm.instance.name]
          )
          if (confirm) {
            this.dealCustomConfirm(selectVm, confirm, treeVm.$ds.checkList)
          }
        }
        value.close() // 关闭弹窗方法
      }
    }
    // 右侧使用openView 情况
    if (customSelect.useOpenView) {
      const {
        preId,
        model,
        type,
        checkbox,
        // setFormValues,
        // setFormLabels,
        // getTableValues,
        onlyReturnValue,
        api,
        confirm,
        app,
        zIndex,
        inheritData
      } = customSelect.useOpenView
      let valueField = customSelect?.useOpenView?.valueField || 'id'
      let labelField = customSelect?.useOpenView?.labelField || 'name'
      let height = customSelect?.height || '60vh'
      openViewSchema = {
        type: 'container',
        items: [],
        view: {
          created: {
            // beforeOperate: async (a, b, c) => {
            //   // 过滤后端视图
            //   // customSelect.useOpenView.loadViewAfter('view')
            // },
            inheritData,
            openView: {
              preId, // 全局业务唯一标识前缀 不能重复
              model, // 后端模型名
              type,
              valueField,
              labelField,
              checkbox,
              api,
              confirm,
              app,
              zIndex,
              height,
              deriveFromCustomSelect: true
              // mainTableHeight: '4rem'
            }
          }
        }
      }
      if (dialogSchema && checkbox === 'multiple') {
        dialogSchema.className = 'dialog_useOpenView_multiple'
        dialogSchema.css = `.dialog_useOpenView_multiple.choice-dialog-wrapper.ii-base-style .choice-dialog .body{padding: 10px 10px 0 10px}`
        dialogSchema.bind_on_opreates = async (params) => {
          // 点击按钮
          const { self: vm, value } = params
          // 如果是从openView中打开了搜索展开项，选完数据时展开
          const actionNodeId = vm.data.dataSource?.actionNodeId
          if (actionNodeId?.indexOf('form_main_table_search_dropdown') > -1) {
            const dropdownObj = vm.$select(vm.data.dataSource?.idPre + 'dropdown_pop_form')
            if (dropdownObj?.instance?.setOpen) {
              dropdownObj.instance.setOpen(true)
            }
          }
          if (value.type === 'confirm') {
            // 拿到table选中的id
            const tableVm = vm.$select(`${preId}table_main_table`)
            // 赋值给input
            const selectVm = vm.$select(vm.$ds.operateId)
            //  做转换
            if (tableVm.$ds.transferSelected?.length) {
              selectVm.$ds.form[selectVm.instance.name] = window.Tech._cloneDeep(
                tableVm.$ds.transferSelected
              ).map((item) => ({ value: item.value, label: item.text || item.label }))
            } else {
              selectVm.$ds.form[selectVm.instance.name] = null
            }
            triggerOnChange(
              selectVm,
              selectVm.instance.name,
              selectVm.$ds.form[selectVm.instance.name]
            )
            if (confirm) {
              this.dealCustomConfirm(selectVm, confirm, tableVm.$ds.transferSelected)
            }
          }
          value.close() // 关闭弹窗方法
        }
      }
      if (dialogSchema && checkbox === 'single') {
        dialogSchema.className = 'dialog_useOpenView_single'
        dialogSchema.css = `.dialog_useOpenView_single.choice-dialog-wrapper.ii-base-style .choice-dialog .body{padding: 0 10px 0 10px}`

        dialogSchema.bind_on_opreates = async (params) => {
          // 点击按钮
          const { self: vm, value } = params
          // 如果是从openView中打开了搜索展开项，选完数据时展开
          const actionNodeId = vm.data.dataSource?.actionNodeId
          if (actionNodeId?.indexOf('form_main_table_search_dropdown') > -1) {
            const dropdownObj = vm.$select(vm.data.dataSource?.idPre + 'dropdown_pop_form')
            if (dropdownObj?.instance?.setOpen) {
              dropdownObj.instance.setOpen(true)
            }
          }

          if (value.type === 'confirm') {
            // 更换写法 - 为了beforeOperate修改的属性能通过引用地址修改到，需配"_noCache": false,
            let setFormValues = customSelect?.useOpenView?.setFormValues ?? ''
            let setFormLabels = customSelect?.useOpenView?.setFormLabels ?? ''
            let getTableValues = customSelect?.useOpenView?.getTableValues ?? ''
            // 拿到table选中的id
            const tableVm = vm.$select(`${preId}table_main_table`)
            // 赋值给input
            const selectVm = vm.$select(vm.$ds.operateId)
            // let obj
            let obj = tableVm?.instance?.getInstance()?.getRadioRecord()
            // if ((obj = tableVm.$ds.checkedDataList[0])) {
            if (obj) {
              if (onlyReturnValue) {
                selectVm.$ds.form[selectVm.instance.name] = obj[valueField]
                triggerOnChange(selectVm, selectVm.instance.name, obj[valueField])
              } else {
                let distVal = {
                  value: obj[valueField],
                  label: obj[labelField]
                }
                selectVm.$ds.form[selectVm.instance.name] = distVal
                triggerOnChange(selectVm, selectVm.instance.name, distVal)
              }
              const tableNames = getTableValues?.split(',') || []
              const setFormLabelsArr = setFormLabels?.split(',') || []
              setFormValues?.split(',')?.forEach((valueField, index) => {
                if (setFormLabelsArr[index] && setFormLabelsArr[index] !== 'null') {
                  let distVal = {
                    value: obj[tableNames[index] || valueField],
                    label: obj[setFormLabelsArr[index] || labelField]
                  }
                  selectVm.$ds.form[valueField] = distVal
                  triggerOnChange(selectVm, valueField, distVal)
                } else {
                  selectVm.$ds.form[valueField] = obj[tableNames[index] || valueField]
                  triggerOnChange(selectVm, valueField, obj[tableNames[index] || valueField])
                }
              })
            } else {
              selectVm.$ds.form[selectVm.instance.name] = null
              triggerOnChange(selectVm, selectVm.instance.name, null)
            }
            if (confirm) {
              this.dealCustomConfirm(selectVm, confirm, tableVm.$ds.checkedDataList)
            }
          }
          value.close() // 关闭弹窗方法
        }
        dialogSchema.bind_on_customClickClear = async (params) => {
          const { self: vm, value } = params
          // 清除回填的其他表单项
          let setFormValues = customSelect?.useOpenView?.setFormValues ?? ''
          if (setFormValues) {
            const setFormValuesArr = setFormValues?.split(',') || []
            setFormValuesArr.forEach((valueField, index) => {
              vm.$ds.form[valueField] = null
            })
          }
          // 自定义清除事件
          const customClear = customSelect?.useOpenView?.customClear
          if (customClear) {
            if (Object.prototype.toString.call(customClear) === '[object String]') {
              try {
                customClear = window.tech_app.utils._cloneDeep(customClear)
                customClear = new Function('return ' + customClear)()
              } catch (error) {
                console.log(' === openView Api reqPrep error == ', error)
              }
            }
            let customClearResult = undefined
            if (vm.$cmd.isAsync(customClear)) {
              customClearResult = await customClear(vm)
            } else {
              customClearResult = customClear(vm)
            }
          }
        }
      }
      dialogSchema.bind_on_setDropdownOffset = (params) => {
        // 弹框拖动时，隐藏展开项
        const dropdownObj = params.self.$select(preId + 'dropdown_pop_form')
        if (dropdownObj?.$ds?.isOpen) {
          if (dropdownObj?.instance?.setOpen) {
            dropdownObj.instance.setOpen(false)
          }
        }
      }
    }
    if (dialogSchema) {
      dialogSchema.items = [useSelectTreeSchema, useSelectListSchema, openViewSchema].filter(
        (schema) => schema
      )
      // 合并视图配置的beforeOperate
      if (srcView?.beforeOperate) {
        Tech.$set(
          srcView,
          'beforeOperate',
          async (params) => {
            await Scope.dialogSchema.beforeOperate(params)
            if (typeof Super.beforeOperate === 'string') {
              Super.beforeOperate = new Function('return ' + Super.beforeOperate)()
            }
            return Super.beforeOperate(params)
          },
          { dialogSchema }
        )
      }
      dialogSchema = {
        ...dialogSchema,
        ...srcView
      }
      return dialogSchema
    }
    return null
  }

  // 不可编辑
  disableUpdateFn(i, options) {
    if (i.disable_update) {
      if (i.disabled !== undefined) return
      i.disabled = () => {
        if (i.disable_update === 'edit' && this.modelMeta.vm.$ds.clickType === 'edit') {
          // 清空校验规则
          i.rules = []
          return true
        }
        return false
      }
    }
  }

  mergeCuloms(backView = [], custiomView = []) {
    let viewColumns = this.getViewFormItem(custiomView)
    let mergeDist = mergeWith(backView, viewColumns)
    if (mergeDist.dataType === undefined) {
      mergeDist.dataType = ''
    }
    return mergeWith(backView, viewColumns)
  }
  getViewFormItem(view, culoms) {
    if (!culoms) {
      culoms = []
    }
    if (Array.isArray(view)) {
      view.forEach((item) => {
        if (item.name && item.customFront === undefined) {
          //  && item.dataType !== undefined
          culoms.push(item)
        }
        // if (item.dataType === undefined) {
        //   item.dataType = '';
        // }
        if (item.items) {
          culoms = this.getViewFormItem(item.items, culoms)
        }
      })
      return culoms
    } else {
      return culoms
    }
  }
}
