    addDrawerForm: async (vm, rowData = {}, btn = {}) => {
      const idPre = vm.$cmd.getIdPre(vm)
      const tabTable = vm.$select(idPre + 'table_main_table')
      if (Object.keys(rowData).length) {
        setTimeout(() => {
          // 赋值子表行数据的选中状态
          tabTable.$ds.mainTableRowData = rowData
          tabTable.$ds.selectedTableData[0] = rowData
          tabTable.instance.setBoxSelected(rowData, 'isReset', null)
        })
      }
      // 根据loadView接口 与公共方法 返回构造items
      let viewConfig = await vm.$cmd.getDrawerFromView(vm)
      // 取loadview的数据
      const seniorTable = vm.$cmd.getUiSchemeData(vm)
      let formViewData = seniorTable?.form

      const processFormColumns = (columns) => {
        // 添加数组检查，防止非数组输入导致错误
        if (!Array.isArray(columns)) {
          return []
        }

        const loadViewData = vm.$ds.tabConfig?.manyToManyInfos?.loadViewData
        const fieldName = vm.$ds.tabConfig?.manyToManyInfos?.field

        const columnsRes = columns.map((item) => {
          // 处理字符串类型的字段
          if (typeof item === 'string') {
            if (item.includes('.')) {
              const fieldParts = item.split('.')
              // 确保分割后有足够的部分
              if (fieldParts.length > 1 && fieldParts[0] === fieldName) {
                const fieldRes = fieldParts[1]
                // 确保viewConfig存在再操作
                if (
                  viewConfig &&
                  loadViewData?.fields?.[fieldRes] &&
                  !viewConfig.fields?.[fieldRes]
                ) {
                  // 确保fields对象存在
                  if (!viewConfig.fields) {
                    viewConfig.fields = {}
                  }
                  viewConfig.fields[fieldRes] = loadViewData.fields[fieldRes]
                }
                return {
                  name: fieldRes,
                  disabled: true // 点·的不可编辑
                }
              }
            } else if (viewConfig.fields?.[item]?.related) {
              if (viewConfig.fields[item].related.split('.')[0] !== fieldName) {
                return null
              }
              return {
                name: item,
                disabled: true // 不可编辑
              }
            }
            return item // 如果格式不正确，返回原始值
          }
          // 处理对象类型的字段
          else if (Object.prototype.toString.call(item) === '[object Object]') {
            if (item.name?.includes('.')) {
              const fieldParts = item.name.split('.')
              // 确保分割后有足够的部分
              if (fieldParts.length > 1 && fieldParts[0] === fieldName) {
                const fieldRes = fieldParts[1]
                // 确保viewConfig存在再操作
                if (
                  viewConfig &&
                  loadViewData?.fields?.[fieldRes] &&
                  !viewConfig.fields?.[fieldRes]
                ) {
                  // 确保fields对象存在
                  if (!viewConfig.fields) {
                    viewConfig.fields = {}
                  }
                  viewConfig.fields[fieldRes] = loadViewData.fields[fieldRes]
                }
                return {
                  ...item,
                  name: fieldRes,
                  disabled: true // 点·的不可编辑
                }
              }
            } else if (viewConfig.fields?.[item.name]?.related) {
              if (viewConfig.fields[item.name].related.split('.')[0] !== fieldName) {
                return null
              }
              return {
                ...item,
                disabled: true // 不可编辑
              }
            }
            return item // 如果格式不正确，返回原始值
          }
          // 其他情况保持不变
          return item
        })

        return columnsRes.filter((item) => item !== null)
      }

      if (vm.$ds?.tabConfig?.manyToManyInfos) {
        viewConfig.views.form.body.columns = processFormColumns(
          viewConfig?.views?.form?.body?.columns
        )
      }
      let data = vm.$cmd.meta.formFormat.initForm(vm, viewConfig?.views?.form, viewConfig?.fields)
      if (formViewData && !vm.$ds.fromOpenview) {
        const list = viewConfig?.views?.form?.body?.columns
        const columnsList = formViewData.body.columns
        const mergedArr = list.map((item1) => {
          const matchingItem = columnsList.find((item2) => item2.name === item1.name)
          return { ...item1, ...matchingItem }
        })
        const arr = list.map((obj) => obj.name || obj)
        formViewData.body.columns = mergedArr.filter((e) => arr.includes(e.name) || arr.includes(e))
        if (vm.$ds?.tabConfig?.manyToManyInfos) {
          formViewData.body.columns = processFormColumns(formViewData.body.columns)
        }
        data = vm.$cmd.meta.formFormat.initForm(vm, formViewData, viewConfig?.fields)
      }
      // 取本地缓存的数据
      const cacheData = sessionStorage.getItem(idPre + 'FORM_VIEW')
      const cacheView = cacheData ? JSON.parse(cacheData) : null
      if (cacheView && !vm.$ds.fromOpenview) {
        if (vm.$ds?.tabConfig?.manyToManyInfos) {
          cacheView.body.columns = processFormColumns(cacheView.body.columns)
        }
        data = vm.$cmd.meta.formFormat.initForm(vm, cacheView, viewConfig?.fields)
      }
      await vm.$cmd.showDrawerForm(vm, rowData, { btn, viewData: data, viewConfig: viewConfig })
    },
