export default function lazyLoadApps(arr) {
  if (window._lazyLoadAppsTimeout) {
    clearTimeout(window._lazyLoadAppsTimeout)
  }
  if (!window._appLazyLoaded) {
    window._appLazyLoaded = new Map()
  }
  window._lazyLoadAppsTimeout = setTimeout(async () => {
    for (let i = 0; i < arr.length; i++) {
      if (tech_app.page.data.id != 'page_meta_login') break
      try {
        let curUrl = new URL(location.href)
        let topParams = new URLSearchParams(curUrl.search)
        let srcFrontHost = topParams.get('frontHost')
        let baseUrl = location.origin
        if (srcFrontHost) {
          // 判断是否有frontHost配置
          srcFrontHost = decodeURIComponent(srcFrontHost)
          baseUrl = location.protocol + '//' + srcFrontHost.split('/')[0]
        }
        const getFileUrl = async (srcPath, type) => {
          let appJsonPath = ''
          try {
            appJsonPath =
              window.tech.srcOutApps.apps[arr[i].name][window?.tech?.env || 'master'][
                arr[i].comp_name
              ]
          } catch (e) {}
          if (!appJsonPath) {
            return
          }
          let prePath = '' // 获取的前缀路径
          try {
            prePath = appJsonPath.split('config/app.json')[0]
          } catch (e) {}
          let fileUrl = prePath + srcPath
          if (!window._appLazyLoaded.get(fileUrl)?.loaded) {
            // console.log(' ================= fileUrl === ', fileUrl)
            // fetch(fileUrl)
            if (type === 'css') {
              await window.Tech.asyncLoadCssNew(fileUrl, document)
            } else if (type === 'js') {
              // 不能提前eval语法 因为里面可能有多语言变量定义
              // await window.Tech.asyncLoadJsNew(fileUrl, document)
            }
            // 添加app已加载过的标识
            window._appLazyLoaded.set(fileUrl, { loaded: true })
          }
        }
        await new Promise((resolve) => setTimeout(resolve, 40))
        if (tech_app.page.data.id != 'page_meta_login') break
        for (let n = 0; n < arr[i].view_file_json.assets.css.length; n++) {
          await getFileUrl(arr[i].view_file_json.assets.css[n], 'css')
        }
        for (let m = 0; m < arr[i].view_file_json.assets.js.length; m++) {
          await getFileUrl(arr[i].view_file_json.assets.js[m], 'js')
        }
      } catch (e) {}
    }
    console.log(' === _lazyLoadAppsTimeout ===== end ')
  }, 500)
}
