function findItemsWithDataType(list, result) {
  for (let i = 0; i < list.length; i++) {
    const element = list[i]
    if (element.dataType && element.dataType !== 'Collapse' && element.display) {
      result.push(element)
    } else {
      if (element.items && element.items.length > 0) {
        findItemsWithDataType(element.items, result)
      }
    }
  }
}

export default {
  // 动态设置表单字段
  type: 'dialog',
  id: 'dialog_meta_set_drawer_form',
  width: '80%',
  title: Tech.$t('seniorTable.formElementConfiguration'),
  display: false,
  hasFooter: true,
  confirmText: Tech.$t('toolbar.dialogConfirm'),
  cancelText: Tech.$t('toolbar.dialogCancle'),
  bind_on_opreates: async (params) => {
    const { self: vm, value } = params
    const idPre = vm.$cmd.getIdPre(vm)
    if (value.type === 'cancel') {
      value.close()
    } else {
      const tableVm = vm.$select(idPre + 'set_drawer_form_table')
      let commonForm = vm.$select(idPre + 'table_drawer_form')
      const { views } = commonForm.$ds.tableView.data
      const formView = { ...views?.form }
      const tableList = tableVm.data.tableData
      // tableList.sort((a, b) => a.sort - b.sort)
      let list = []
      let isMinus = false //是否存在负数
      let haveFloat = false //是否存在小数
      tableList.forEach((item) => {
        if (item.sort) {
          list.push(item.sort)
          if (item.sort < 0 || !Number.isInteger(item.sort)) {
            isMinus = true
          }
        }
        if (item.row && (item.row < 0 || !Number.isInteger(item.row))) {
          haveFloat = true
        }
      })
      // 判断如果有负数或者小数点的行组提示修改
      if (haveFloat) {
        window.ELEMENT.Message.error(Tech.$t('seniorTable.rowErrorHint'))
        return
      }
      // 判断如果有负数或者小数点的序号提示修改
      if (isMinus) {
        window.ELEMENT.Message.error(Tech.$t('seniorTable.hasMinusHint'))
        return
      }
      // 判断是否有重复的序号
      if (new Set(list).size !== list.length) {
        window.ELEMENT.Message.error(Tech.$t('seniorTable.theSameSortExists'))
        return
      }
      let columns = formView?.body.columns
      for (let item of columns) {
        let obj = {}
        for (let i = 0; i < tableList.length; i++) {
          if (typeof item === 'string' && item === tableList[i].name) {
            obj.name = tableList[i].name
          } else if (Object.prototype.toString.call(item) === '[object Object]') {
            obj = item
          }
          if (obj.name === tableList[i].name) {
            obj.displayName = tableList[i].displayName
            obj.sort = tableList[i].sort
            obj.display = tableList[i].display
            obj.disabled = tableList[i].disabled
            obj.row = tableList[i].row
            obj.span = tableList[i].span
            obj.custom = true
            obj.required = tableList[i].required
            obj.groupConf = tableList[i].groupConf
          }
        }
        columns[columns.indexOf(item)] = obj
      }
      let outputArray2 = columns.reduce(function (acc, obj) {
        var groupConfValue = obj.groupConf
        var existingGroup = acc.find(function (item) {
          return item.groupConf && item.groupConf.name === groupConfValue
        })
        if (existingGroup) {
          obj.groupConf = existingGroup.groupConf
        } else {
          if (groupConfValue) {
            obj.groupConf =
              typeof groupConfValue === 'object'
                ? groupConfValue
                : { id: 'group' + (acc.length + 1), name: groupConfValue }
          } else {
            obj.groupConf = null
          }
          if (obj.groupConf) {
            acc.push(obj)
          }
        }
        return acc
      }, [])
      columns = columns.filter(function (obj) {
        return !obj.hidden && !obj.hide && obj.type !== 'hidden'
      })
      columns.sort((a, b) => a.sort - b.sort)
      formView.body.columns = columns
      // 缓存formView
      sessionStorage.setItem(idPre + 'FORM_VIEW', JSON.stringify(formView))
      // 根据loadView接口 与公共方法 返回构造items
      let viewConfig = await vm.$cmd.getDrawerFromView(vm)
      let data = vm.$cmd.meta.formFormat.initForm(vm, formView, viewConfig?.fields)
      // 重新加载表单
      const formMain = vm.$select(idPre + 'table_drawer_form')
      formMain.data.items = []
      if (data.items && data.items.length > 0) {
        data.items.forEach((item) => {
          formMain.app.updatePageNode(item, formMain, () => {
            formMain.data.items.push(item)
          })
        })
      }
      const onlyLookRequiredNode = vm.$select(vm.$ds.idPre + 'only_look_required')
      if (onlyLookRequiredNode?.instance) {
        onlyLookRequiredNode.instance.setCheck?.(false)
        onlyLookRequiredNode.instance.change?.(null)
      }
      value.close()
    }
  },
  items: [
    {
      type: 'container',
      id: 'set_drawer_form_table_box',
      className: 'set_drawer_form_table_box',
      style: {
        minHeight: '3rem'
      },
      dataSource: {
        fieldList: []
      },
      created: (vm) => {
        const idPre = vm.$cmd.getIdPre(vm)
        const tableVm = vm.$select(idPre + 'set_drawer_form_table')
        // 取本地缓存的数据
        const cacheData = sessionStorage.getItem(idPre + 'FORM_VIEW')
        const cacheView = cacheData ? JSON.parse(cacheData) : null
        const tableMainVm = vm.$select(idPre + 'table_main')
        const tableView = tableMainVm.$ds.tableView.data
        const { views, fields } = tableView
        const seniorForm = vm.$cmd.getUiSchemeData(tableMainVm)
        // 获取页面显示的表单字段，通过递归遍历所有的子元素找到包含dataType和display:true的
        const formVm = vm.$select(idPre + 'table_drawer_form')
        const fieldList = []
        if (formVm?.data?.items) {
          findItemsWithDataType(formVm.data.items, fieldList)
        }
        let showArr = [] //页面显示的表单字段
        if (fieldList && fieldList.length > 0) {
          fieldList.forEach((item) => {
            showArr.push(item.name)
          })
        }
        let viewColumns = views?.form?.body?.columns
        // 拿到视图里的columns先过滤掉视图配置了隐藏的字段
        viewColumns = viewColumns.filter(
          (item) => item.display !== false && !item.hidden && !item.hide && item.type !== 'hidden'
        )
        const viewColumnsList = vm.$cmd.meta.getColumnForFieldsList(viewColumns, fields)
        let showColumns = viewColumnsList
        let seniorFormColumn = []
        if (cacheView) {
          seniorFormColumn = cacheView?.body?.columns
        } else if (!cacheView && seniorForm?.form?.body?.columns) {
          seniorFormColumn = seniorForm?.form?.body?.columns
        }
        if (seniorFormColumn.length > 0) {
          const seniorFormColumnList = vm.$cmd.meta.getColumnForFieldsList(seniorFormColumn, fields)
          // 如果是走的缓存和方案，需过滤掉视图内没有的字段，再合并视图新增的字段
          for (let i = 0; i < viewColumnsList.length; i++) {
            for (let j = 0; j < seniorFormColumnList.length; j++) {
              if (seniorFormColumnList[j].name === viewColumnsList[i].name) {
                viewColumnsList[i] = { ...viewColumnsList[i], ...seniorFormColumnList[j] }
              }
            }
          }
          showColumns = viewColumnsList
        }
        let list = showColumns
        // 先过滤一遍页面不显示或者没有配置bind_display的字段
        const showList = list.filter((item) => showArr.includes(item.name) || !item.bind_display)
        const mergedArray = showList
        // 初始化数据前，将分组进行转换
        mergedArray.forEach((item) => {
          item.groupConf = item.groupConf ? item.groupConf.name : ''
        })
        vm.$ds.fieldList = mergedArray
        tableVm.data.tableData.sort((a, b) => a?.sort - b?.sort)
      },
      css: `
        .set_drawer_form_table_box .vxe-table--render-default.vxe-editable .vxe-body--column{
          padding: 0.05rem 0;
        }
        .set_drawer_form_table_box .vxe-table--render-default .vxe-cell{
          white-space: normal !important;
          text-overflow: inherit !important;
        }
      `,
      items: [
        {
          type: 'table',
          isEdit: true,
          id: 'set_drawer_form_table',
          // bind_columns: '$ds.searchColumns',
          bind_tableData: '$ds.fieldList',
          style: {
            minHeight: '3.5rem'
          },
          items: [
            {
              type: 'seq',
              width: 60,
              title: Tech.$t('transferTable.serial')
            },
            {
              type: 'text',
              field: 'name',
              title: Tech.$t('gridView.field')
            },
            {
              field: 'displayName',
              type: 'input',
              name: 'displayName',
              title: Tech.$t('seniorTable.displayName'),
              formatItem: (row, item) => {
                item.displayName = row.label ? row.label : row.displayName
                return item
              }
            },
            {
              type: 'switch',
              field: 'display',
              name: 'display',
              title: Tech.$t('seniorTable.display'),
              model: {},
              formatItem: (row, item) => {
                item.model = row
                item.disabled = row.hasOwnProperty('bind_display')
                return item
              }
            },
            {
              type: 'switch',
              field: 'disabled',
              name: 'disabled',
              model: {},
              formatItem: (row, item) => {
                item.model = row
                item.disabled =
                  row.hasOwnProperty('bind_disabled') || row.hasOwnProperty('disable_update')
                return item
              },
              title: Tech.$t('seniorTable.whetherToDisable')
            },
            {
              type: 'switch',
              field: 'required',
              name: 'required',
              model: {},
              formatItem: (row, item) => {
                item.model = row
                return item
              },
              title: Tech.$t('seniorTable.isRequired')
            },
            {
              type: 'input',
              field: 'groupConf',
              name: 'groupConf',
              title: Tech.$t('seniorTable.groupName')
            },
            {
              type: 'number',
              field: 'row',
              name: 'row',
              maxValue: 100,
              model: {},
              formatItem: (row, item) => {
                item.model = row
                return item
              },
              title: Tech.$t('seniorTable.rowGroup')
            },
            {
              type: 'select',
              field: 'span',
              name: 'span',
              options: [
                { label: 4, value: 4 },
                { label: 6, value: 6 },
                { label: 8, value: 8 },
                { label: 12, value: 12 },
                { label: 16, value: 16 },
                { label: 24, value: 24 }
              ],
              model: {},
              formatItem: (row, item) => {
                item.model = row
                return item
              },
              title: Tech.$t('seniorTable.width')
            },
            {
              type: 'number',
              field: 'sort',
              name: 'sort',
              maxValue: 100,
              model: {},
              formatItem: (row, item) => {
                item.model = row
                return item
              },
              title: Tech.$t('gridView.sort')
            }
          ]
        }
      ]
    }
  ]
}
