/***rbac_role_menu_form-tabs
 *  主表单中字表tab
 */
export default {
  id: 'form-tabs',
  name: 'form-tabs',
  type: 'container',
  className: 'form-tabs-wrap-ctn',
  style: {
    display: 'flex',
    height: '100%',
    width: '100%',
    background: 'rgb(225, 231, 236)'
  },
  items: [
    {
      type: 'container',
      id: 'form-tabs-wrap',
      className: 'form-tabs-wrap-css',
      style: {
        'overflow-x': 'auto',
        'margin-top': '0.08rem',
        display: 'flex',
        height: 'calc(100% - 0.08rem)',
        width: '100%'
      },
      css: '.form-tabs-wrap-css .tech-tabs > .el-tabs > .el-tabs__content{overflow-y: auto;}',
      items: [
        {
          type: 'tabs',
          id: 'form-tabs-node',
          close: false,
          activeId: '',
          activeWork: true, // 切换到的tab才生效
          style: {
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
            width: '100%',
            'margin-top': '0.02rem'
          },
          created: async (vm) => {
            const table_detail = vm.$select(`${vm.$ds.idPre}table_detail`)
            // tab上下拖动
            vm.instance.$nextTick(() => {
              const container_table_main_wrap = document.getElementById(
                vm.$ds.idPre + 'container_table_main_wrap'
              )
              if (!container_table_main_wrap) return
              const container_table_tab_wrap =
                container_table_main_wrap.querySelector('.el-tabs__header')
              container_table_tab_wrap.style.cursor = 'move'
              container_table_tab_wrap.style.height = 'auto'
              container_table_tab_wrap.addEventListener('mousedown', (e) => {
                try {
                  const container_form_main_wrap1 = vm.$select(
                    vm.$ds.idPre + 'container_form_main_wrap'
                  )
                  // container_form_main_wrap1.data.style.maxHeight = '100%'
                  let container_form_main_wrap = document.getElementById(
                    vm.$ds.idPre + 'container_form_main_wrap'
                  )
                  if (table_detail.$ds.isFlowFormView && table_detail.$ds.isApproval) {
                    container_form_main_wrap = document.getElementById(
                      vm.$ds.idPre + 'approval_process_detail'
                    )
                  }
                  // 如果是树表单结构节点id不一样
                  const treeView = vm.$ds.treeViewRes?.data
                  if (treeView && !treeView.tree?.body?.props?.subModel) {
                    container_form_main_wrap = document.getElementById(
                      vm.$ds.idPre + 'tree_main_wrap_right_form_wrap'
                    )
                  }
                  const container_table_main_wrapdiv = document.getElementById(
                    vm.$ds.idPre + 'container_table_main_wrap'
                  )
                  // tabs组件的位置信息
                  let tabsRect = vm.instance.$el.getBoundingClientRect()
                  // 上半部表单的位置信息
                  let formRect = container_form_main_wrap.getBoundingClientRect()
                  // 整个表单区域的高度
                  let formMainH = document.getElementById(
                    vm.$ds.idPre + 'form_main_detail_top_items_1'
                  ).scrollHeight // 整体滚动高度
                  // 记录点击时，tabs组件顶点和表单上半部分的顶点间的距离（表单的上半部分div高度不能代表tabs组件的顶点位置）
                  let oldH = tabsRect.y - formRect.y
                  function move(eMove, e) {
                    container_form_main_wrap1.data.style.overflow = 'auto'
                    let distance = eMove.clientY - e.clientY
                    let newHei = oldH + distance
                    if (distance > -10 && distance < 10) {
                      return
                    }
                    // 限制拖拽的最大高度
                    if (newHei < formMainH - 100) {
                      // 改变表单上半部分的div高度
                      container_form_main_wrap.style.height = newHei + 'px'
                      container_form_main_wrap.style.maxHeight = newHei + 'px'
                      // 改变表单下半部分的div高度
                      container_table_main_wrapdiv.style.height = formMainH - newHei + 'px'
                    }
                  }
                  document.body.onmousemove = (eMove) => {
                    move(eMove, e)
                    // 子表上下拖动关闭子表搜索展开项
                    vm.data.items?.forEach((item) => {
                      const dropdownObj = vm.$select(
                        item.dataSource?.idPreTab + 'dropdown_pop_form'
                      )
                      if (dropdownObj?.$ds?.isOpen && dropdownObj?.instance?.setOpen) {
                        dropdownObj.$ds.isOpen = false
                        dropdownObj.instance.setOpen(false)
                      }
                    })
                  }
                  document.body.addEventListener('mouseup', (e) => {
                    document.body.onmousemove = null
                  })
                } catch (e) {}
              })
            })
            // console.log(' === in form tabs created == ', vm);
            vm.data.items = []
            // 获取的loadView接口数据
            let node = vm.$select(vm.$ds.idPre + 'table_main_wrap')
            if (vm.$ds.fromOpenview || vm.$ds.urlFormViewId) {
              node = vm.$select(vm.$ds.idPre + 'table_main')
            }
            // 如果是树表单结构，不存在主表，需要获取树节点
            const tableView = vm.$ds.tableView?.data?.views
            if (tableView?.tree && !tableView?.tree?.body?.props.subModel) {
              node = vm.$select(vm.$ds.idPre + 'tree_main_wrap_left')
            }
            let loadViewData = node.$ds.tableView
            if (loadViewData?.data) {
              loadViewData = loadViewData.data
            }
            // 传进tabs-utils里面的方法转换

            if (table_detail.$ds.isFlowFormView) {
              loadViewData = node.$ds.loadFlowView
            }
            // tabsActiveWork：激活所有子表tab
            if (loadViewData?.views?.form?.body?.tabsActiveWork === false) {
              vm.data.activeWork = false
            }
            let tabs = await vm.$cmd.meta.formatTabs(vm, {
              view: window.Tech._cloneDeep(loadViewData?.views?.form),
              fields: loadViewData?.fields,
              permissions: loadViewData?.permissions
            })
            for (let i = 0; i < tabs.length; i++) {
              vm.app.updatePageNode(tabs[i], vm, () => {
                if (tabs[i].display !== false && tabs[i].body?.authInfo?.isDisplay !== false) {
                  vm.data.items.push(tabs[i])
                }
              })
            }
            let notShowTabs = vm.data.items.length === 0
            // 新增情况 进去只显示主表单 不显示 子tab情况
            if (loadViewData?.views?.form?.body?.addSaveFormFirst) {
              // 同步进table_detail节点的$ds.addSaveFormFirst
              table_detail.$ds.addSaveFormFirst = true
              // if (vm?.$ds?.clickType === 'add') {
              //   notShowTabs = true
              // }
            }
            // && !table_detail.$ds.isFlowFormView
            if (notShowTabs) {
              // 不存在子表时不显示子表父级的容器
              vm.$select(vm.$ds.idPre + 'container_table_main_wrap').data.display = false
            }
            // console.log(' === = tabs === ', tabs.length, JSON.parse(JSON.stringify(tabs[0])));
            try {
              let formTabsObj = vm.$select(vm.$ds.idPre + 'form-tabs')
              if (vm.data.items.length > 0) {
                formTabsObj.data.style.display = 'block'
              } else {
                formTabsObj.data.style.display = 'none'
              }
            } catch (e) {
              console.log('==== formTabsObj === error ==', e)
            }

            // 获取点击编辑前当前选择的tab，如果有就选中，如果没有就选择第一个
            const form = vm.$select(vm.$ds.idPre + 'container_form_main_wrap')
            const visibleTabIds = tabs.filter((item) => item.display).map((item) => item.id)
            vm.data.activeId = visibleTabIds.includes(form?.$ds?.activeTab)
              ? form.$ds.activeTab
              : visibleTabIds?.[0]
              ? visibleTabIds?.[0]
              : ''
            if (form) {
              form.$ds.activeTab = vm.data.activeId
            }

            vm?.instance?.$nextTick(() => {
              vm.$cmd.syncFormSaveStatus(vm)
            })
          },
          ds_config: {
            list: [
              {
                name: 'lookup',
                type: 'meta',
                method: 'service',
                autoRequest: false,
                options: {}
              }
            ]
          },
          items: [],
          bind_on_goto: (vm) => {
            // tabs切换的时候将当前选中的tab的id存到表单的$ds中
            const form = vm.self.$select(vm.self.$ds.idPre + 'container_form_main_wrap')
            if (form && vm.self.data?.activeId !== undefined) {
              form.$ds.activeTab = vm.self.data.activeId
            }
            // 如果是树表单结构表单id不一样
            const treeForm = vm.self.$select(vm.self.$ds.idPre + 'tree_table_detail')
            if (treeForm && vm.self.data?.activeId !== undefined) {
              treeForm.$ds.activeTab = vm.self.data.activeId
            }
          }
        }
      ]
    }
  ]
}
