import FormRender from './from-fields/form/form-render'
import toLowerCase from './from-fields/common/utils/toLowerCase'
import initEndView from './end-view-utils'
import moment from 'moment'
function initForm(vm = {}, view = {}, fields = {}, options = {}) {
  // 拷贝一份出来避免引用地址被后面修改
  let newView = view
  if (view?.body?.authInfo?.hasOwnProperty('isDisplay') && !view?.body?.authInfo?.isDisplay) {
    console.warn('iidp警告 === 权限 == ', view.view_id, ' === 没有配置权限 == ')
    return
  }
  try {
    if (!view?._customParams?._notFirst) {
      // 第一次处理断开引用地址 不使用 _cloneDeep 有奇怪的问题
      if (!view?._customParams) {
        view._customParams = {}
      }
      view._customParams._notFirst = true
      newView = window.Tech._cloneDeep(view)
    } else {
      newView = {
        // 防止二次扩展丢失了 扩展的自定义方法
        ...view
      }
    }
  } catch (e) {
    newView = window.Tech._cloneDeep(view)
  }
  let newFields = window.Tech._cloneDeep(fields)
  let newItem = new FormRender({ view: newView, fields: newFields, vm })
  // 去掉items里面的后端的随机id方便扩展
  // if (newItem?.items) {
  //   for (let i = 0; i < newItem.items.length; i++) {
  //     newItem.items[i] = removeEndId(newItem.items[i]);
  //   }
  // }
  // 根据权限控制表单的字段的显示隐藏，是否可编辑
  if (newItem?.items && newItem?.items.length > 0) {
    for (let i = 0; i < newItem.items.length; i++) {
      if (newItem.items[i].hidden) {
        newItem.items[i].layoutStyle = {
          display: 'none'
        }
      }
      if (newItem.items[i].authInfo) {
        newItem.items[i].dataSource = {
          tech_authId: newItem.items[i].authInfo.authId
        }
        // 多租户权限控制-如果权限配置了隐藏就设置display：false，如果配置的显示则不需要修改display的值
        if (newItem.items[i].authInfo.hasOwnProperty('isDisplay')) {
          if (!newItem.items[i].authInfo.isDisplay) {
            newItem.items[i].display = false
          } else {
            switch (newItem.items[i].authInfo.isDisplay) {
              case 'update':
                if (vm.$ds.clickType !== 'edit') {
                  newItem.items[i].display = false
                }
                break
              case 'create':
                if (vm.$ds.clickType !== 'add') {
                  newItem.items[i].display = false
                }
                break
            }
          }
          if (newItem.items[i].display && newItem.items[i].authInfo.isHidden) {
            newItem.items[i].layoutStyle = {
              display: 'none'
            }
          }
        }
        // 租户权限控制-如果权限配置了禁用就设置disabled：true，如果配置的不禁用则不需要修改disabled
        if (newItem.items[i].authInfo.hasOwnProperty('isEdit')) {
          if (!newItem.items[i].authInfo.isEdit) {
            newItem.items[i].disabled = true
          } else {
            switch (newItem.items[i].authInfo.isEdit) {
              case 'update':
                if (vm.$ds.clickType !== 'edit' && vm.$ds.clickType !== 'preview') {
                  newItem.items[i].disabled = true
                }
                break
              case 'create':
                if (vm.$ds.clickType !== 'add' && vm.$ds.clickType !== 'preview') {
                  newItem.items[i].disabled = true
                }
                break
            }
          }
        }
      }
    }
  }
  // console.log(vm)
  // console.log(newItem?.items)
  // defaultValue处理
  if (!options?.fromResize) {
    newItem = dealDefaultValue(newItem, newView, newFields, vm)
  } else {
    // 从resize操作触发的
    const dealDefaultValueFn = (obj, view, fields, vm) => {
      obj.defaultValue !== undefined && delete obj.defaultValue
      if (obj?.name && view?.body?.columns) {
        view.body.columns.forEach((item) => {
          if (item.name === obj.name) {
            if (item.defaultValue !== undefined) {
              obj.defaultValue = item.defaultValue
            }
            if (item.defaultValueFn) {
              let defaultValueFn = new Function(item.defaultValueFn)
              if (window?.Tech?.isFunctionStringNew(item.defaultValueFn)) {
                defaultValueFn = new Function('return ' + item.defaultValueFn)()
              }
              if (defaultValueFn.constructor.name === 'AsyncFunction') {
                vm.data?.defaultValueFnArrs?.push({
                  fn: defaultValueFn(vm),
                  name: obj.name
                })
              } else {
                obj.defaultValue = defaultValueFn(vm)
              }
            }
          }
        })
      }
      if (obj?.items) {
        for (let i = 0; i < obj.items.length; i++) {
          obj.items[i] = dealDefaultValueFn(obj.items[i], view, fields, vm)
        }
      }
      return obj
    }
    newItem = dealDefaultValueFn(newItem, newView, newFields, vm)
  }

  // 配置了innerLabel=true则label内嵌进表单项
  if (window.$tech?.innerLabel || newView?.body?.innerLabel) {
    function recursionArr(arr) {
      if (arr?.length) {
        arr.forEach((i) => {
          if (i.innerLabel === undefined) i.innerLabel = true
          if (i.items?.length) recursionArr(i.items)
        })
      }
    }
    recursionArr(newItem?.items)
  }

  // newItem.items[0].colWidth = '400px'
  // 判断添加多一层row
  newItem = addRowWrap(newItem)
  // 初始化表单的append
  // newItem = initEndView(vm, newItem, newFields)

  // 因为是拷贝出来的view要 补充会改变的参数
  addViewParams(view, newView)
  return newItem
}

function formatFlowViewBtns(vm, { view, permissions } = {}) {
  let btnsConfig = []
  let btnsData = view?.body?.buttons || []

  if (!permissions) {
    permissions = ['all']
  }

  // 校验权限
  // btnsData = tableUtils.checkButtonAuth(btnsData, permissions)

  // 组装新格式
  btnsConfig = btnsData.map((item) => {
    const btnConfig = {
      type: 'button',
      value: item.name,
      action: item.action,
      service: item.service,
      style: {
        background: 'var(--button-primary-bg, #677177)',
        border: 'none',
        fontSize: '0.14rem',
        lineHeight: '0.13rem'
      },
      options: {
        size: 'mini',
        ...(item.options || {})
      },
      btnConfig: item,
      loading: false,
      showPopLoading: item.showPopLoading
    }

    // 朴素按钮
    if (item.plain) {
      btnConfig.style.background = '#fff'
      btnConfig.style.border = '.01rem solid var(--button-primary-bg, #677177)'
      btnConfig.style.color = 'var(--button-primary-bg, #677177)'
    }

    return btnConfig
  })
  return btnsConfig
}

// 补充会改变的参数
function addViewParams(srcView, newView) {
  if (newView?.body?.columns) {
    if (!srcView.body) {
      srcView.body = {}
    }
    srcView.body.columns = window.Tech._cloneDeep(newView.body.columns)
  }
  // 如果是customView也需克隆一下  断开引用
  if (newView?.body?.customView) {
    if (!srcView.body) {
      srcView.body = {}
    }
    srcView.body.customView = window.Tech._cloneDeep(newView.body.customView)
  }
}

// 去掉后端id
function removeEndId(obj) {
  if (obj?.id?.length === 13 && /^[0-9a-z]*$/.test(obj.id)) {
    delete obj.id
  }
  // if (obj?.id?.indexOf('@Property') !== -1) {
  //   delete obj.id;
  // }
  if (obj?.items) {
    for (let i = 0; i < obj.items.length; i++) {
      obj.items[i] = removeEndId(obj.items[i])
    }
  }
  return obj
}

// 加defaultValue
function dealDefaultValue(obj, view, fields, vm) {
  let isSearch = view?.body?.type === 'search'
  // console.log(' ==== isSearch === ', isSearch);
  if (obj?.name) {
    let viewCols = view?.body?.columns || []

    if (isSearch) {
      // 搜索情况则删除 defaultValue
      obj.readonly = false // 搜索情况 readonly 都是false

      // 清空默认值，columns给默认值
      obj.defaultValue !== undefined && delete obj.defaultValue

      const searchCacheData = sessionStorage.getItem(vm.$cmd.getIdPre(vm) + 'SEARCH_FORM_DATA')

      viewCols.map((item) => {
        // columns中给出默认值
        if (!Object.prototype.toString.call(item) === '[object Object]') return
        if (item.name === obj.name && item.defaultValue !== undefined) {
          // obj.defaultValue = item.defaultValue
          if (item?.key) {
            if (obj.key === item.key) {
              if (!searchCacheData) {
                obj.defaultValue = item.defaultValue
              } else {
                obj.defaultValueTemp = item.defaultValue
              }
            }
          } else {
            if (!searchCacheData) {
              obj.defaultValue = item.defaultValue
            } else {
              obj.defaultValueTemp = item.defaultValue
            }
          }
        }
        if (item.name === obj.name && item.defaultValueFn) {
          let defaultValueFn = new Function(item.defaultValueFn)
          if (window?.Tech?.isFunctionStringNew(item.defaultValueFn)) {
            defaultValueFn = new Function('return ' + item.defaultValueFn)()
          }
          if (defaultValueFn.constructor.name === 'AsyncFunction') {
            vm.data?.defaultValueFnArrs?.push({
              fn: defaultValueFn(vm),
              name: obj.name
            })
            // 配置异步默认值时，阻止默认查询，默认值全部赋值完后统一查询
            if (vm.$ds.tableView?.data?.views?.grid?.body) {
              vm.$ds.tableView.data.views.grid.body.disabledInitAutoSearch = true
            }
          } else {
            if (!searchCacheData) {
              obj.defaultValue = defaultValueFn(vm)
            } else {
              obj.defaultValueTemp = defaultValueFn(vm)
            }
          }
          // 根据默认值设置默认时间
          if (obj?.widget == 'datetimerange') {
            const defaultTime = []
            obj?.defaultValue?.forEach((item) => {
              defaultTime.push(item.toLocaleTimeString())
            })
            obj.defaultTime = defaultTime
          }
        }
      })
    } else {
      let getDefaultValue = undefined
      // 自动填充remoteData
      if (view.body?.remoteDefaultData?.columns[obj.name]) {
        getDefaultValue = `${view.body.remoteDefaultData.columns[obj.name]}_${Tech.moment().format(
          'YY_MM_DD_HHmmSSS'
        )}`
      }

      // columns中给出默认值
      if (getDefaultValue === undefined) {
        viewCols.map((item) => {
          if (!Object.prototype.toString.call(item) === '[object Object]') return
          if (item.name === obj.name && item.defaultValue !== undefined) {
            // getDefaultValue = item.defaultValue
            if (item?.key) {
              if (obj.key === item.key) {
                getDefaultValue = item.defaultValue
              }
            } else {
              getDefaultValue = item.defaultValue
            }
          }
          if (item.name === obj.name && item.defaultValueFn) {
            let defaultValueFn = new Function(item.defaultValueFn)
            if (window?.Tech?.isFunctionStringNew(item.defaultValueFn)) {
              defaultValueFn = new Function('return ' + item.defaultValueFn)()
            }
            getDefaultValue = defaultValueFn(vm)
            if (obj.type === 'datepicker' && getDefaultValue instanceof Date) {
              const formatStr = obj.valueFormat.split(/\W+/)
              const splitList = obj.valueFormat.split(/\w+/)
              splitList.shift()
              splitList.pop()
              let format = ''
              if (obj.valueFormat === 'timestamp') {
                getDefaultValue = Tech.moment(getDefaultValue).valueOf()
              }
              formatStr.map((item, index) => {
                const momentFormatValue = {
                  yyyy: 'YYYY',
                  W: 'w',
                  WW: 'ww',
                  d: 'D',
                  dd: 'DD'
                }
                format += (momentFormatValue[item] || item) + (splitList[index] || '')
              })
              getDefaultValue = Tech.moment(getDefaultValue).format(format)
            }
          }
        })
      }

      if (getDefaultValue === undefined) {
        // colums里面找不到情况下 在fields里面找
        if (fields[obj.name]?.defaultValue !== undefined) {
          getDefaultValue = fields[obj.name].defaultValue
        }
      }
      if (getDefaultValue !== undefined) {
        // if (obj.__defaultValue !== undefined) {
        //   obj.defaultValue = window.Tech._cloneDeep(obj.__defaultValue)
        // } else {
        //   obj.__defaultValue = window.Tech._cloneDeep(getDefaultValue)
        // }
        obj.defaultValue = window.Tech._cloneDeep(getDefaultValue)
      }
      // else {
      //   obj.__defaultValue = null
      // }
    }

    // cache配置，获取缓存默认值，默认值中权限最高
    if (obj?.cache) {
      const storage = sessionStorage.getItem(obj.cache)
      // 有缓存
      if (storage) {
        const curCache = JSON.parse(storage)
        obj.defaultValue = curCache[obj.name]
        obj[`${obj.name}__values`] = curCache[obj.name]
      }
      // 改变值的时候存起来
      obj.bind_on_changeHandler = (params) => {
        const { self: vm, value } = params
        const storage = sessionStorage.getItem(vm.data.cache)
        let cacheValue = !!storage ? JSON.parse(storage) : {}
        if (!value) {
          delete cacheValue[vm.data.name]
        } else {
          cacheValue[vm.data.name] = value
        }
        sessionStorage.setItem(vm.data.cache, JSON.stringify(cacheValue))
      }
    }
  }
  if (obj?.items) {
    for (let i = 0; i < obj.items.length; i++) {
      obj.items[i] = dealDefaultValue(obj.items[i], view, fields, vm)
    }
  }
  return obj
}

// 判断添加多一层row
function addRowWrap(obj) {
  if (obj?.items) {
    const rowItems = []
    const noRowItems = []
    const rowArray = []
    obj.items.forEach((item) => {
      if (item.type === 'row' || item.items) {
        rowItems.push(item)
      } else {
        // 配置了列宽
        if (item.row) {
          if (rowArray.indexOf(item.row) === -1) {
            rowItems.push({
              type: 'row',
              items: [item],
              selfAdaptionW: false,
              row: item.row
            })
            rowArray.push(item.row)
          } else {
            rowItems.forEach(function (dom, k) {
              if (rowItems[k].row == item.row) {
                rowItems[k].items.push(item)
              }
            })
          }
        } else {
          noRowItems.push(item)
        }
      }
    })
    if (noRowItems.length > 0) {
      rowItems.push({
        type: 'row',
        items: noRowItems
      })
    }
    obj.items = rowItems
  }
  return obj
}

// 拼接查询格式
// 入参 data 搜索对象 例如 { name: '11', name2: '22' }
// columns 为列对象数据 例如 [{name:'col1',dataType:'String'}]
// 返回拼接后的查询格式 例如： ["name","like","%test%"]
// isSearch 是否在搜索框上面用
// 表单项处理 拼接到搜索接口的参数上
function handleSearchData(data, columns, vm) {
  // 如果有设置搜索条件，拿存储的默认运算符
  if (vm) {
    const { advancedComponent } = vm.$ds.tableView.data
    let columnsData
    if (advancedComponent) {
      const seniorTable = vm.$cmd.getUiSchemeData(vm)
      columnsData = seniorTable?.search
    }
    const idPre = vm.$cmd.getIdPre(vm)
    const cacheColumns = sessionStorage.getItem(idPre + 'SEARCH_CONFIG')
    if (cacheColumns && cacheColumns !== 'undefined') columnsData = JSON.parse(cacheColumns)
    if (columnsData) {
      const cacheList = columnsData.body.columns
      columns.forEach((item) => {
        for (let i = 0; i < cacheList.length; i++) {
          if (item.name === cacheList[i].name) {
            item.operator = cacheList[i].operator
            item.isPrecise = cacheList[i].operator
          }
        }
      })
    }
  }

  if (data == null) {
    return null
  }
  let values = []
  let spliceTypes = []
  const addPreciseFilter = (p, k, v) => {
    switch (p) {
      case 'all':
        values.push([k, '=', v])
        break
      case 'left':
        values.push([k, 'like', '%' + v])
        break
      case 'right':
        values.push([k, 'like', v + '%'])
        break
    }
  }

  const getSplitData = (column, v) => {
    if (
      'splitSymbol' in column
      //  || 'splitSymbol' in window.tech
    ) {
      const split = column.splitSymbol // || window.tech.splitSymbol
      // 是否禁用拆分
      const disabledSplit = 'splitSymbol' in column && column.splitSymbol === false
      // 'splitSymbol' in column ? column.splitSymbol === false : window.tech.splitSymbol === false
      // 获取拆分符号
      const splitStr = split || ','
      // 判断是否禁用拆分 并得到对应的数据
      return disabledSplit ? [splitStr] : v.split(splitStr)
    }
    return []
  }

  for (const [k, v] of Object.entries(data)) {
    if (v == null || v === '' || (Array.isArray(v) && v.length === 0)) continue
    const column = columns.find((c) => c.name === k)
    // if (column == null) continue;
    if (column == null) {
      if (spliceTypes.length > 0) {
        spliceTypes.push('&')
      }
      values.push([k, '=', v])
      continue
    }
    const datatype = column.dataType.toLowerCase()
    // 添加多行输入框输入搜索按照input输入框搜索条件规则一样
    if (datatype === 'string' || datatype === 'text') {
      // 如果设置了搜索默认运算符按照设置的传参
      // 兼容多选的lookup
      if (Object.prototype.toString.call(v) === '[object Array]') {
        values.push([k, 'in', v])
      } else if (typeof v === 'string' || typeof v === 'number') {
        // 添加配置，搜索项是否精确搜索
        if (column.isPrecise) {
          addPreciseFilter(column.isPrecise, k, v)
        } else {
          values.push([k, 'like', '%' + v + '%'])
        }
      }
    } else if (datatype === 'date' || datatype === 'datetime') {
      const dateRange = ['daterange', 'datetimerange', 'monthrange'].includes(column.widget)
      const yearFilter = (year) => {
        let value1 = moment(year).startOf('year').format('YYYY-MM-DD')
        let value2 = moment(year).endOf('year').format('YYYY-MM-DD')
        values.push([k, '>=', value1])
        values.push([k, '<=', value2])
        values.unshift('&')
      }
      let [value1, value2] = v
      // 处理timepicker的search中filter接口请求参数
      if (column.type === 'timepicker') {
        if (column.isRange) {
          values.push([k, '>=', value1])
          values.push([k, '<=', value2])
          values.unshift('&')
        } else {
          values.push([k, '=', v])
        }
      } else if (dateRange) {
        if (datatype === 'datetime') {
          const fmt = 'YYYY-MM-DD HH:mm:ss'
          if (column.widget === 'monthrange') {
            value1 = moment(value1).startOf('month').format(fmt)
            value2 = moment(value2).endOf('month').format(fmt)
          } else if (column.widget === 'daterange') {
            value1 = moment(value1).startOf('date').format(fmt)
            value2 = moment(value2).endOf('date').format(fmt)
          } else {
            value1 = moment(value1).format(fmt)
            value2 = moment(value2).format(fmt)
          }
        } else {
          const fmt = 'YYYY-MM-DD'
          if (column.widget === 'monthrange') {
            value1 = moment(value1).startOf('month').format(fmt)
            value2 = moment(value2).endOf('month').format(fmt)
          } else {
            value1 = moment(value1).startOf('date').format(fmt)
            value2 = moment(value2).endOf('date').format(fmt)
          }
        }
        values.push([k, '>=', value1])
        values.push([k, '<=', value2])
        values.unshift('&')
      }

      // 单选年
      else if (column.widget == 'year') {
        yearFilter(v)
      }
      // 多选年
      else if (column.widget == 'years') {
        v.map((year, index) => {
          yearFilter(year)
          if (index < v.length - 1) {
            values.unshift('&')
          }
        })
      } else {
        let value = v
        if (column.operator) {
          values.push([k, column.operator, moment(value).format(fmt)])
        } else {
          if (datatype === 'datetime') {
            const fmt = 'YYYY-MM-DD HH:mm:ss'
            values.push([k, '=', moment(value).format(fmt)])
          } else {
            const fmt = 'YYYY-MM-DD'
            values.push([k, '=', moment(value).format(fmt)])
          }
        }
      }
    } else if (datatype === 'enummodel') {
      values.push([k, 'in', v])
    } else if (datatype === 'enum') {
      values.push([k, '=', v])
    } else if (datatype === 'boolean') {
      values.push([k, '=', v])
    } else if (
      (datatype === 'selection' ||
        // datatype === 'manytomany' ||
        datatype === 'dict' ||
        datatype === 'manytoone') &&
      column?.multiple
    ) {
      // selection 多选 常量 情况 与 manytomany 多选  与dict 字典 情况  && column?.selectionType === 'constant'
      values.push([k, 'in', v || []])
    } else if (datatype === 'manytomany') {
      // manytomany的情况下 字段需要拼接.id
      if (column?.multiple) {
        values.push([k, 'in', v || []])
      } else {
        values.push([k, '=', v])
      }
    } else {
      // values.push([k, '=', Number(v)]);
      values.push([k, '=', v])
    }
    // 获取异或方式
    const spliceType = getSplice(column)
    // 这里相当于字段之间的 & 或者 |
    spliceTypes.push(spliceType)
    const splitList = getSplitData(column, v)
    if (splitList.length > 1) {
      // 超过了1个条件，就进行剔除原有的条件信息，在继续执行下面的逻辑重新添加
      values.pop()
      splitList.forEach((vc, i) => {
        // 由于字段之间以及有的逻辑符，所以就从第二个开始添加逻辑符
        i > 0 && spliceTypes.push('|')
        // 需求要是是拆分的条件默认是 =
        column.isPrecise
          ? addPreciseFilter(column.isPrecise, k, vc)
          : vc && values.push([k, 'like', '%' + vc + '%'])
      })
    }
  }
  // console.log(spliceTypes)
  // 将前面选择的值塞入字段的第二个值
  // values.forEach((ele) => {
  //   if (ele[0].indexOf('prev') > -1) {
  //     const prev = ele[0].replace('prev', '').toLowerCase()
  //     values.forEach((item) => {
  //       if (item[0] === prev) {
  //         item[1] = ele[2]
  //       }
  //     })
  //   }
  // })
  // // 清除prev字段
  // for (let i = 0; i < values.length; i++) {
  //   if (values[i][0].indexOf('prev') > -1) {
  //     values.splice(i, 1)
  //   }
  // }
  // console.log(values)
  // 拼接&,｜
  if (values.length == 0) {
    return null
  } else if (values.length == 1) {
    return values
  } else {
    if (spliceTypes[0] === '|') {
      spliceTypes.splice(1, 1)
    } else {
      spliceTypes.splice(0, 1)
    }
    const result = spliceTypes.reverse()
    result.push(...values)
    return result
  }
}
// 获取查询字段的拼接方式
function getSplice(column) {
  if (column.dataType !== 'condition') {
    if (column?.splice == '&' || column?.splice == '|') {
      return column.splice
    } else {
      return '&'
    }
  }
}
