// 合并表单的form列配置到fields上  viewConfig是loadView接口返回的data里面的东西
function mergeFormColumns(vm = {}, viewConfig = {}) {
  let reObj = {}
  if (viewConfig?.fields) {
    reObj = window.Tech._cloneDeep(viewConfig.fields)
  } else if (vm?.$ds?.tableView?.data?.fields) {
    reObj = window.Tech._cloneDeep(vm.$ds.tableView.data.fields)
  } else {
    let commonform = vm.$select(vm.$ds.idPre + 'form_main_table_search_common')
    if (commonform?.$ds?.tableView?.data?.fields) {
      reObj = window.Tech._cloneDeep(commonform.$ds.tableView.data.fields)
    }
  }
  if (viewConfig?.views?.form?.body?.columns) {
    let formColumns = viewConfig.views.form.body.columns || []
    formColumns.map((item) => {
      if (Object.prototype.toString.call(item) === '[object Object]') {
        if (item?.name && reObj[item.name]) {
          reObj[item.name] = {
            ...reObj[item.name],
            ...item
          }
        }
      }
      // return item;
    })
  }
  for (let k in reObj) {
    // 赋值转小写的datatype
    if (reObj[k].dataType && !reObj[k].datatype) {
      reObj[k].datatype = String.prototype.toLowerCase.call(String(reObj[k].dataType))
    }
  }
  return reObj
}

// 处理各数据类型空值转换
function handleEmptyData(vm = {}, data = {}, fields = {}) {
  for (let k in data) {
    if (fields[k]?.dataType) {
      // && data[k] === ''
      let dataType = fields[k].dataType
      switch (toLowerCase(dataType)) {
        case 'auto':
        case 'string':
        case 'text':
          break
        default:
          if (data[k] === '') {
            data[k] = null
          }
          break
      }
    }
  }
  // console.log(' === fields === ', fields);
  // console.log(' === data === ', data);
  return data
}

// 去掉__values的入参
function filterValues(vm, data) {
  let newData = {}
  for (let k in data) {
    if (k && k.indexOf('__values') === -1) {
      newData[k] = data[k]
    }
  }
  return newData
}

// 判断body里面的transformRes转换
function transformRes(vm, data, viewConfig = null) {
  let getViewConfig = null
  // console.log('tableView', vm.$ds.tableView.data)
  let commonform = vm.$select(vm.$ds.idPre + 'form_main_table_search_common')
  if (!commonform) {
    // 如果不存在取form 的配置
    commonform = vm.$select(vm.$ds.idPre + 'form_main_detail_top_common')
  }
  if (commonform?.$ds?.tableView?.data) {
    getViewConfig = commonform.$ds.tableView.data
  }
  if (viewConfig) {
    getViewConfig = viewConfig
  }
  if (getViewConfig?.views?.form?.body?.transformRes) {
    let transformRes = getViewConfig.views.form.body.transformRes
    if (transformRes) {
      if (Object.prototype.toString.call(transformRes) === '[object String]') {
        try {
          transformRes = new Function('return ' + transformRes)()
        } catch (e) {
          console.log(' === transformRes error == ', transformRes, e)
        }
      }
      try {
        data = transformRes(data)
      } catch (e) {
        console.log(' === transformRes use row error == ', e)
      }
    }
  }
  // console.log(' ==== main form transformRes row === ', row);
  return data
}

// 过滤掉不需要传的参数
function delFormRes(vm, data, viewConfig = null) {
  const commonformNode = vm.$select(vm.$ds.idPre + 'form_main_table_search_common')
  let viewData =
    commonformNode && commonformNode.$ds.tableView.data ? commonformNode.$ds.tableView.data : {}
  //添加表单视图参数传递
  if (viewConfig) {
    viewData = viewConfig
  }
  if (viewData.views?.form) {
    const itemsConfig = viewData.views.form.body.columns
    itemsConfig.map((item) => {
      if (item.disable_update === 'edit' && vm.$ds.clickType === 'edit') {
        delete data[item.name]
      }
      // 对upload组件的数据[]进行转换
      if (viewData.fields[item.name]?.dataType == 'File') {
        if (Array.isArray(data[item.name]) && data[item.name].length === 0) {
          data[item.name] = null
        }
      }
    })
  }
  return data
}

