// 转换搜索栏标签过滤项
// 表单项处理 拼接到搜索栏标签列表上
function getSearchTagsFilter(vm, data, fields) {
  let cacheName = 'techTagsFilter' + vm?.$ds?.idPre + vm?.$ds?.preId + '_' + vm?.$ds?.idPreTab
  // console.log(' ==== window[cacheName] === ', cacheName, window[cacheName])
  if (!window?.[cacheName]) {
    window[cacheName] = new Map()
  }
  let temp = []
  let totalRes = data
  let totalItem = fields
  for (const key in totalRes) {
    if (Object.hasOwnProperty.call(totalRes, key)) {
      let hasKey = key + '___values'
      let val = totalRes[key]
      if (totalRes[hasKey]) {
        if (totalRes[hasKey].label !== undefined) {
          if (val !== null && val !== undefined && val !== '') {
            val = totalRes[hasKey].label
          }
        }
        // 兼容多选数组情况
        if (
          Object.prototype.toString.call(totalRes[hasKey]) === '[object Array]' &&
          totalRes[hasKey]?.[0]?.label !== undefined
        ) {
          let tmpArr = []
          totalRes[hasKey].map((it) => {
            if (it.label !== undefined) {
              tmpArr.push(it.label)
            }
          })
          val = tmpArr.join(',')
        }
        window[cacheName]?.set(key, totalRes[hasKey]) // 先用全局缓存存起 ___values
        // console.log(' ==== window[cacheName]0 === ', window[cacheName])
      } else if (window[cacheName]?.get(key)) {
        let __values = window[cacheName]?.get(key)
        if (__values?.label !== undefined) {
          if (val !== null && val !== undefined && val !== '') {
            val = __values.label
          }
        }
      }
      if (val === null || val === undefined || val === '' || val.length === 0) continue
      for (let f of totalItem) {
        let curDataType = String.prototype.toLowerCase.call(String(f.dataType))
        if (key == f.name) {
          if (
            (curDataType == 'selection' ||
              curDataType == 'manytomany' ||
              curDataType == 'dict' ||
              curDataType == 'manytoone') &&
            f.multiple
          ) {
            // selection 多选 常量 情况 与 manytomany 多选 情况  && f.selectionType === 'constant'
            let setValue = (totalRes[key] || [])
              .map((item) => {
                let findItem = {}
                if (f.options?.length) {
                  findItem = f.options.find((itemF) => itemF.value === item)
                } else if (f.useCustomClick) {
                  // 处理弹框选择器多选数据回填搜索条件
                  const optionsArr = totalRes[f.name + '___values']
                  if (optionsArr) {
                    findItem = optionsArr.find((itemF) => itemF.value === item)
                  }
                } else {
                  const optionsArr = JSON.parse(sessionStorage.getItem(f.id + '__values'))
                  if (optionsArr) {
                    findItem = optionsArr.find((itemF) => itemF.value === item)
                  }
                }
                if (curDataType == 'manytoone' || curDataType == 'manytomany')
                  return findItem?.label
                return findItem?.text || ''
              })
              .join(',')
            if (setValue) {
              temp.push({ text: f.displayName, value: setValue, name: key })
            }
          } else if (curDataType == 'dict') {
            let searchVal = ''
            if (f.showSearchValue) {
              // 判断是否有 showSearchValue 转换方法
              searchVal = f.showSearchValue(val)
            }
            temp.push({
              text: f.displayName,
              value: searchVal || val,
              name: key
            })
          } else if (f.values) {
            val = totalRes[key]
            for (let v of f.values) {
              if (val == v.value) {
                temp.push({ text: f.displayName, value: v.label, name: key })
              }
            }
          } else if (curDataType == 'enum') {
            if (f.attrs) {
              temp.push({
                text: f.displayName,
                value: f.attrs.Values[totalRes[key]],
                name: key
              })
            } else {
              temp.push({
                text: f.displayName,
                value: f.options[totalRes[key]].text,
                name: key
              })
            }
          } else if (['date', 'datetime'].includes(curDataType)) {
            const date = f.valueFormat.split(' ')
            date[0] = date[0].replace(/y/g, 'Y').replace(/d/g, 'D')
            // 处理timepicker的search中filter tags显示
            if (f.type === 'timepicker') {
              temp.push({ text: f.displayName, value: val, name: key })
              return temp
            }
            if (Array.isArray(val)) {
              val = val.map((valItem) => {
                return Tech.moment(valItem).format(date.join(' '))
              })
            } else {
              val = Tech.moment(val).format(date.join(' '))
            }

            temp.push({ text: f.displayName, value: val, name: key })
          } else {
            let searchVal = ''
            if (f.showSearchValue) {
              // 判断是否有 showSearchValue 转换方法
              searchVal = f.showSearchValue(val, f.options, f.type)
            }
            temp.push({
              text: f.displayName,
              value: searchVal || val,
              name: key
            })
          }
        }
      }
    }
  }
  return temp
}

// 处理获取到的审批流表单视图
function dealworkFlowView(vm, data = {}) {
  const table_detail = vm.$select(`${vm.$ds.idPre}table_detail`)
  const table_main = vm.$select(`${vm.$ds.idPre}table_main`)
  const deleteId = (fields) => {
    // 需要删除fields属性里的id 否则后端id会影响前端id
    for (const key in fields) {
      if (Object.hasOwnProperty.call(fields, key)) {
        const element = fields[key]
        element.id && delete element.id
      }
    }
  }
  data?.form?.fields && deleteId(data.form.fields)
  table_detail.$ds.approvalPageTitle = data?.form?.views?.form?.body?.title
  table_detail.$ds.serviceName = data?.service
  table_detail.$ds.isFlowFormView = table_detail.$ds.isApproval = true
  table_detail.$ds.processinstanceId = data.id
  // 解決审批节点Collapse折叠面板id重复问题
  if (data?.approvalNodes?.length > 1) {
    data.approvalNodes.forEach((node, nodeIndex) => {
      node?.processForm?.views?.form?.body?.columns.forEach((col, colIndex) => {
        if (col?.groupConf) {
          col.id =
            'tab_' +
            node.processForm?.model +
            node.processForm?.service +
            node.processForm?.app +
            node?.id +
            col?.name +
            nodeIndex +
            colIndex
        }
      })
    })
  }
  table_detail.$ds.processDatas = vm.app.utils._cloneDeep(data)
  table_main.$ds.loadFlowView = data?.form || {}
  if (!table_main.$ds.tableView?.data?.views) table_main.$ds.tableView.data.views = {}
  table_main.$ds.tableView.data.views.form = table_main.$ds.loadFlowView?.views?.form
}

function formatToolbarBtns(vm, { view, permissions } = {}, options = {}) {
  let toolbarBtnsConfig = []
  let btnsData = view?.body?.tbar || view?.edit?.tbar || []
  let btnsNew = []
  btnsData.map((item) => {
    // 转对象
    if (item !== '@defaults') {
      if (Object.prototype.toString.call(item) === '[object String]') {
        let srcItem = item
        item = { action: srcItem }
      }
      btnsNew.push(item)
    }
  })
  btnsData = btnsNew

  // 校验删除权限
  btnsData = formCheckButtonAuth(btnsData, permissions, vm)
  const idPre = vm.$ds.idPreTab || vm.$ds.idPre
  // rbac_role_app_menu_form_main_detail_top_common  主表单
  // rbac_role_app_menu_tab_user_ids_table_drawer_form 抽屉表单

  let formId = vm.$select(`${idPre}form_main_detail_top_common`)
  if (vm.$ds.idPreTab) {
    formId = vm.$select(`${idPre}table_drawer_form`)
  }

  let actionBeforeFn = (vm, btn) => {
    if (btn?.actionBeforeFn) {
      let actionBeforeFn = btn?.actionBeforeFn
      if (typeof actionBeforeFn === 'string') {
        actionBeforeFn = new Function('return ' + actionBeforeFn)()
      }
      const actionBeforeFnResult = actionBeforeFn(vm)
      // if (!actionBeforeFnResult) return
      return actionBeforeFnResult ? true : false
    }
    return true
  }
  const btnType = {}
  let getTbarBtnClick = (inItem, btnVm) => {
    if (btnType[inItem.action]?.click) {
      const btnObj = window.Tech._cloneDeep(btnType[inItem.action])
      return btnObj.click
    } else if (!btnType[inItem.action] && btnType[inItem.copyAction]) {
      // 针对不同的action需要调同一个类型的方法，判断如果配置copyAction，就cope一份方法给配置了copyAction的按钮
      const copyAction = window.Tech._cloneDeep(btnType[inItem.copyAction])
      return copyAction.click
    } else {
      if (!inItem.views && inItem.service) {
        // tbar btns 调用other service情况
        return (res) => {
          const { self: vm } = res
          let btn = res.self?.data?.btnConfig
          const continueClick = actionBeforeFn(vm, btn)
          if (!continueClick) return
          vm.$cmd.btnReqOtherServer(vm, btn, '', vm.$ds, vm.instance, {
            reg: /\$ds(\.?[a-zA-Z\w]*)*/g
          })
        }
      } else if (inItem.link?.url) {
        return (res) => {
          const { self: vm } = res
          let btn = res.self?.data?.btnConfig
          const continueClick = actionBeforeFn(vm, btn)
          if (!continueClick) return
          window.open(inItem.link.url, inItem.link.target || '_blank')
        }
      }
    }
    return inItem.click ? inItem.click : (params) => {}
  }

  // 组装新格式
  toolbarBtnsConfig = btnsData.map((item) => {
    const btnType = {
      import: {
        //导入按钮
        name: Tech.$t('toolbar.import'),
        icon: 'iconfont icon-daoru',
        className: 'toolbar-import',
        click: (res) => {
          const { self: vm } = res
          let btn = res.self?.data?.btnConfig
          const continueClick = actionBeforeFn(vm, btn)
          if (!continueClick) return
          importFn(vm)
        }
      },
      staticDownload: {
        //下载静态模板
        name: Tech.$t('toolbar.exportStatic'),
        icon: 'iconfont icon-daochu',
        className: 'toolbar-export',
        click: async (res) => {
          const { self: vm } = res
          const btnConfig = vm.data.btnConfig
          const continueClick = actionBeforeFn(vm, btnConfig)
          if (!continueClick) return
          const link = document.createElement('a')
          link.style.display = 'none'
          link.href = '/fileSystem/' + btnConfig.filename
          const list = btnConfig.filename.split('/')
          link.setAttribute('download', list[list.length - 1])
          document.body.appendChild(link)
          link.click()
          document.body.removeChild(link)
        }
      },
      methodDownload: {
        //下载动态模板
        name: Tech.$t('toolbar.exportMethod'),
        icon: 'iconfont icon-daochu',
        className: 'toolbar-export',
        click: async (res) => {
          const { self: vm } = res
          let btn = res.self?.data?.btnConfig
          const continueClick = actionBeforeFn(vm, btn)
          if (!continueClick) return
          vm.$cmd.meta.exportFn(vm, {})
        }
      }
    }

    let addPlusObj = {} // 追加的属性配置
    if (
      item.disabled === undefined &&
      item.bind_disabled === undefined &&
      item.enableCondition === undefined
    ) {
      addPlusObj['bind_disabled'] = '$ds.clickType === "preview"'
    }
    // 按钮上若配置了disabled，则用配置的
    if (item.disabled !== undefined) {
      addPlusObj['disabled'] = item.disabled
    }
    if (item.bind_disabled !== undefined) {
      addPlusObj['bind_disabled'] = item.bind_disabled
    }
    if (item.options?.bind_disabled !== undefined || item.bind_disabled !== undefined) {
      item['_fromLoadView'] = true
    }
    let appendStyle = {
      background: 'var(--button-primary-bg, #677177)',
      border: 'none',
      fontSize: '0.14rem',
      lineHeight: '0.13rem',
      marginTop: 5,
      marginBottom: 5
    }
    if (options.enterType === 'drawer_form') {
      appendStyle = {
        background: 'var(--button-primary-bg, #677177)',
        fontSize: '0.14rem',
        padding: '0.06rem 0.1rem',
        border: 'none',
        // background: '#677177',
        color: '#fff',
        marginTop: 5,
        marginBottom: 5
      }
    }
    const btnConfig = {
      ...item,
      type: 'button',
      value: item.name
        ? item.name
        : item.action && btnType[item.action]?.name
        ? btnType[item.action].name
        : item.name,
      style: {
        ...appendStyle,
        ...(item?.style || {})
      },
      className: item.copyAction
        ? btnType[item.copyAction]?.className
        : btnType[item.action]?.className || null,
      action: item.action,
      code: item.code,
      service: item.service,
      options: {
        disabled: false,
        // type: 'text',
        icon: item.icon
          ? item.icon
          : item.copyAction
          ? btnType[item.copyAction]?.icon
          : btnType[item.action]?.icon,
        size: 'mini',
        ...addPlusObj,
        ...(item.options || {})
      },
      btnConfig: item,
      loading: false,
      showPopLoading: item.showPopLoading,
      bind_on_click: getTbarBtnClick(item, vm),
      getFormNode: () => {
        return tech_app.page.getNode(formId)
      },
      getFormData: () => {
        return tech_app.page.getNode(formId)?.$ds?.form || {}
      }
    }
    if (item.authInfo) {
      if (!item.authInfo.isDisplay) {
        btnConfig.display = false
      }
      btnConfig.dataSource = {
        tech_authId: item.authInfo?.authId
      }
    }
    return btnConfig
  })
  toolbarBtnsConfig = formCheckGroup(toolbarBtnsConfig, options)

  return toolbarBtnsConfig
}

function addFormTbar(vm, enterType) {
  let sendView = {}
  let sendPermission = 'all'
  const { permissions, views } = vm.$select(
    vm.$ds.idPre + (vm.$ds.fromOpenview || vm.$ds.urlFormViewId ? 'table_main' : 'table_main_table')
  )?.$ds.tableView?.data
  if (enterType === 'main_form') {
    sendView = views.form
    sendPermission = permissions
  } else if (enterType === 'drawer_form') {
    sendView = vm.$ds.tabConfig
    sendPermission = vm.$ds.tabConfig?.edit?.permissions || permissions
  }

  let toolbarBtns = vm.$cmd.meta.formFormat.formatToolbarBtns(
    vm,
    {
      view: window.Tech._cloneDeep(sendView),
      permissions: window.Tech._cloneDeep(sendPermission)
    },
    { enterType }
  )
  let curPre = vm.$ds.idPreTab || vm.$ds.idPre
  toolbarBtns.map((item, index) => {
    // 按钮组id拼接，action > service > undefined
    if (Array.isArray(item)) {
      item = item.map((e, index) => {
        if (e.action) {
          e.id = `${curPre}${enterType}_toolbar_${e.action}`
        } else if (e.service) {
          e.id = `${curPre}${enterType}_toolbar_${e.service}`
        } else {
          // 兼容之前action为undefine的情况
          const itemId = `${curPre}${enterType}_toolbar_${e.action}`
          e.id = `${itemId}_${index}`
        }
      })
    } else {
      // 按钮组id拼接，action > undefined
      if (item.action) {
        item.id = `${curPre}${enterType}_toolbar_${item.action}`
      } else {
        const itemId = `${curPre}${enterType}_toolbar_${item.action}`
        item.id = `${itemId}_${index}`
      }
    }
    return item
  })

  // 去掉在toolbarBtns里面的节点
  vm.data.items = []

  setTimeout(() => {
    // 重新加
    toolbarBtns.map((item) => {
      if (!item[0]?.btnConfig?.group) {
        if (Array.isArray(item)) {
          item.map((e) => {
            vm.app.updatePageNode(e, vm, (node) => {
              vm.data.items.push(e)
            })
          })
        } else {
          vm.app.updatePageNode(item, vm, (node) => {
            vm.data.items.push(item)
          })
        }
      } else {
        let dropdownConfig = {
          type: 'meta-dropdown',
          id: curPre + 'tool_dropdown',
          created: (vm) => {
            if (enterType === 'drawer_form') {
              tech_app.utils.addClass(
                curPre + 'tool_dropdown_css',
                `
                .tech-dropdown-pop.meta-dropdown-css-${curPre}tool_dropdown {
                  z-index: 3110!important;
                }
                `
              )
            }
          },
          dropdownStyle: {
            maxWidth: '2rem',
            minWidth: '1.5rem',
            padding: '0'
          },
          style: {
            marginLeft: '0.1rem'
          },
          placement: 'bottom',
          css: `
            #toolbarBtnsgroup .el-button{
            color:#666;
            padding:0;
            }
            #toolbarBtnsgroup .el-button + .el-button, .el-checkbox.is-bordered + .el-checkbox.is-bordered {
            margin-left: 0
          }
          .table_main_toolbar_dropDown_btn:hover{
            background: #ddd
          }
            `,
          items: [
            {
              name: 'defaultBtn', // 'customBtn',自定义的按钮，可以是任意的组件
              id: 'header_user_name_btn',
              size: 'medium',
              buttonClose: {
                text: Tech.$t('gridView.openToolbar'),
                icon: 'el-icon-arrow-down'
              },
              buttonOpen: {
                text: Tech.$t('gridView.closeToolbar'),
                icon: 'el-icon-arrow-up'
              }
            },
            {
              type: 'container',
              // id: 'toolbarBtnsgroup',
              //id: 'container_meta_header_user_top',
              items: []
            }
          ]
        }

        let groupBtns = []
        item.map((e, btnIndex) => {
          if (e.groupConfig) {
            Object.assign(dropdownConfig, e.groupConfig)

            dropdownConfig.id = vm.$ds.idPre + e.group + '_form_main_toolbar_dropDown_btns'
          }
          if (e.groupName) {
            dropdownConfig.items[0].buttonClose.text = dropdownConfig.items[0].buttonOpen.text =
              e.groupName
          }
          if (e.icon) {
            dropdownConfig.items[0].buttonClose.icon = dropdownConfig.items[0].buttonOpen.icon =
              e.icon
          }
          // e.id =
          //   vm.$ds.idPre + e.group + '_form_main_toolbar_dropDown_btns_' + e.action + '_' + btnIndex
          e.id = vm.$ds.idPre + e.group + '_form_main_toolbar_dropDown_btns_' + e.action
          // 兼容之前id拼接下标错误
          let oldId =
            vm.$ds.idPre + e.group + '_form_main_toolbar_dropDown_btns_' + e.action + '_' + btnIndex
          let newId = vm.$ds.idPre + e.group + '_form_main_toolbar_dropDown_btns_' + e.action
          if (!window.techOldIdMap) {
            window.techOldIdMap = new Map()
          }
          window.techOldIdMap.set(oldId, newId)

          e.style = {
            display: 'block',
            color: '#666',
            margin: 0,
            width: '100%',
            textAlign: 'left'
          }
          e.className = 'form_main_toolbar_dropDown_btn'
          groupBtns.push(e)
        })
        // 插入dropdown节点
        // if (!vm.$select(dropdownConfig.id)) {
        vm.app.updatePageNode(dropdownConfig, vm, (node) => {
          vm.data.items.push(dropdownConfig)
        })
        // }

        // 插入dropdown的按钮
        const dropdownNode = vm.$select(dropdownConfig.id)
        groupBtns.map((btn) => {
          vm.app.updatePageNode(btn, dropdownNode, () => {
            let srcStyle = btn?.style || {}
            btn.style = {
              ...srcStyle,
              background: 'none',
              color: 'var(--button-primary-bg, #409eff)',
              border: 0
            }
            dropdownNode.data.items[1].items.push(btn)
          })
        })
      }
    })
  })
}

function formCheckGroup(arr, options = {}) {
  const isGroup = arr.filter((item) => item.group)
  if (isGroup.length < 2) {
    return arr
  } else {
    let map = {}
    let myArr = []
    let Arr = []
    isGroup.map((item) => {
      if (Object.prototype.toString.call(item.group) == '[object Object]') {
        // 解析工具栏配置
        item.groupName = item.group.groupName || ''
        item.icon = item.group.icon || ''
        item.groupConfig = window.Tech._cloneDeep(item.group)
        delete item.groupConfig.id
        delete item.groupConfig.icon
        delete item.groupConfig.groupName
        item.group = item.group.id || ''
      }
    })
    for (var i = 0; i < arr.length; i++) {
      if (!map[arr[i].group]) {
        myArr.push({
          group: arr[i].group,
          btnsGroup: [arr[i]]
        })
        map[arr[i].group] = arr[i]
      } else {
        for (var j = 0; j < myArr.length; j++) {
          if (arr[i].group === myArr[j].group) {
            myArr[j].btnsGroup.push(arr[i])
            break
          }
        }
      }
    }
    myArr.map((item) => {
      Arr.push(item.btnsGroup)
    })
    return Arr
  }
}

function formCheckButtonAuth(btnList, authList, vm = null) {
  // 空或者‘all’
  if (!authList || authList.indexOf('all') !== -1) {
    btnList = btnList.map((item) => {
      item.auth = true
      return item
    })
    return btnList
  }
  // 校验每一项的权限
  btnList = btnList.filter((item) => {
    // if (Object.prototype.toString.call(item.auth) === '[object Boolean]') {
    //   return item
    // }
    let hasAuth = authList.indexOf(item.auth) !== -1 || authList.indexOf(item.service) !== -1
    // item.auth = hasAuth
    // console.log(' === hasAuth == ', hasAuth)
    try {
      // 子表情况判断父级是否有权限 带inheritPermission 继承上级权限标识
      if (item.inheritPermission && vm?.$ds?.idPre && vm?.$ds?.idPreTab) {
        // 当前tab容器节点
        let curTabNode = vm.$select(vm?.$ds.idPreTab + 'container_main_content')
        let parent = curTabNode?.parent // 在父级节点取上一层的loadView数据
        let topAuList =
          parent?.$ds?.tableView?.data?.permissions ||
          parent?.$ds?.treeViewRes?.data?.permissions ||
          []
        let topTbar = []
        if (curTabNode?.$ds?.tabConfig?.tbar) {
          curTabNode.$ds.tabConfig.tbar.map((itemBtn) => {
            if (Object.prototype.toString.call(itemBtn) === '[object String]') {
              topTbar.push(itemBtn)
            } else if (itemBtn?.action) {
              topTbar.push(itemBtn.action)
            }
          })
        }
        // 判断是否在上一层的tbar按钮中
        if (topTbar.includes(item.action)) {
          // 根据上一层的loadView permission判断权限
          hasAuth = topAuList.indexOf(item.auth) !== -1 || topAuList.indexOf(item.service) !== -1
        }
      }
    } catch (e) {
      // console.log(' checkButtonAuth judge er tab btn premission error ', e)
    }
    return hasAuth
  })

  return btnList
}

// 表单预览状态数据转换
function previewChange(config, formModel) {
  let result = formModel[config.name]
  if (Object.prototype.toString.call(result) === '[object Object]') {
    if (toLowerCase(config.dataType) == 'file') {
      if (!formModel[config.name + '___values']) {
        formModel[config.name + '___values'] = result
      }
      let href = window.Tech.metaApi.metaDownload(window.tech.apiHost, result?.id)
      return `<a href=${href}>${result?.name}</a>`
    }
    return result?.label
  } else if (Object.prototype.toString.call(result) === '[object Array]') {
    result = result
      .map((item) => {
        if (Object.prototype.toString.call(item) === '[object Object]') {
          return item?.label || item?.text
        } else {
          if (Object.prototype.toString.call(item) === '[object String]') {
            if (formModel[config.name + '___values']) {
              item = formModel[config.name + '___values'].find((ite) => item == ite.value)
            } else if (config.options) {
              item = config.options.find((ite) => item == ite.value)
            }
            return item?.label || item?.text
          }
        }
      })
      .join()
    return result
  } else {
    if (toLowerCase(config.dataType) == 'selection') {
      // 优先从 ___values 取值
      if (
        Object.prototype.toString.call(result) === '[object String]' &&
        formModel?.[config.name + '___values']
      ) {
        let res = formModel[config.name + '___values']
        return res?.label || res?.text
      }
      const obj = config.options.find((item) => {
        return item.value == result
      })
      return obj?.label || obj?.text
    }
    if (toLowerCase(config.dataType) == 'boolean') {
      const obj = config.options.find((item) => {
        return item.value == result
      })
      return obj?.label || obj?.text
    }
    // 表单预览回显处理id
    let ___values = formModel[config.name + '___values']
    if (___values) {
      if (Object.prototype.toString.call(___values) === '[object Array]') {
        let fObj = ___values.filter((it) => it.value === result)
        if (fObj) {
          result = fObj?.label || fObj?.text
        }
      } else {
        if (toLowerCase(config.dataType) == 'file') {
          let href = window.Tech.metaApi.metaDownload(window.tech.apiHost, result)
          result = `<a href=${href}>${___values?.name}</a>`
        } else {
          result = ___values?.label || ___values?.text
        }
      }
    }
  }
  return result
}

