// 参数组件名不能删除
export const name = 'tech-base'

export const getParams = () => {
  // 本地公共扩展 与 本地个性化扩展 合并
  let distOptions = mergeExtend(commonConfig, extendConfig) // test mock
  distOptions.global = config?.global || undefined // 赋值应用配置
  return distOptions
}

