export default {
  // 保存个人界面方案弹窗
  type: 'dialog',
  id: 'dialog_meta_table_save_scheme',
  width: '25%',
  title: Tech.$t('seniorTable.saveThePersonalInterfaceScheme'),
  display: false,
  hasFooter: true,
  timer: false,
  _clickTimer: false,
  confirmText: Tech.$t('toolbar.dialogConfirm'),
  cancelText: Tech.$t('toolbar.dialogCancle'),
  bind_on_opreates: async (params) => {
    const { self: vm, value } = params
    // 防止重点击
    vm.data._clickTime = setTimeout(() => {
      vm.data.timer = false
    }, 500)
    if (vm.data.timer) return
    if (!vm.data.timer) {
      vm.data.timer = true
      clearTimeout(vm.data._clickTimer)
    }

    if (value.type === 'cancel') {
      value.close()
    } else {
      const idPre = vm.$ds.idPreTab ? vm.$ds.idPreTab : vm.$ds.idPre
      const tableWrap = vm.$select(idPre + 'table_main_wrap')
      const tableSearch = vm.$select(idPre + 'form_main_table_search_common')
      const saveForm = vm.$select(idPre + 'save_scheme_dialog_form')
      const formVal = await saveForm.instance.submit()
      // 获取表单数据、表格数据、查询数据
      const tableMain = vm.$select(idPre + 'table_main')
      // 获取常规配置数据
      const config = vm.$select(idPre + 'grid_dynamic_config')
      // 表单数据从缓存中取
      const formCache = sessionStorage.getItem(idPre + 'FORM_VIEW')
      const formView = formCache ? JSON.parse(formCache) : null
      // 获取设置的列宽
      const operationWidth = vm.$select(idPre + 'form_meta_set_operation_width')
      let saveData = {
        search: tableMain.$ds.seniorTable.search,
        grid: tableMain.$ds.seniorTable.grid,
        form: formView,
        gridConfig: config.$ds.initValue,
        operationWidth: operationWidth.$ds.form.width
      }
      let signId = tableWrap.$ds.seniorTableSignId
      // console.log('---- formVal.isOpen', formVal.isOpen)
      const param = {
        model: 'rbac_user_prefer',
        service: 'saveScheme',
        args: {
          values: {
            name: formVal.name,
            signId: signId,
            signType: 'uiScheme',
            signContent: JSON.stringify(saveData),
            description: formVal.desc,
            isOpen: false, // 跟建微和明哲确认，万和项目要求默认值是false
            isDefault: false  // 跟建微和明哲确认，万和项目要求默认值是false
          },
          useDisplayForModel: true
        }
      }
      const res = await tableSearch.request('saveScheme', param)
      if (res.error) {
        window.ELEMENT.Message.error(res.error.message)
      } else {
        window.ELEMENT.Message.success(Tech.$t('common.saveSuccess'))
      }
      Object.keys(saveForm.$ds.form).forEach((key) => {
        // 清空表单数据
        saveForm.$ds.form[key] = null
      })
      value.close()
    }
  },
  items: [
    {
      type: 'form',
      id: 'save_scheme_dialog_form',
      formConfig: {
        inline: false,
        labelPosition: 'left',
        labelWidth: '80px'
      },
      dataSource: {
        form: { name: '', desc: '', isOpen: true, isDefault: true },
        isAdmin: false
      },
      created: (vm) => {
        const idPre = vm.$cmd.getIdPre(vm)
        const pageVm = vm.$select(idPre + 'container_main_content')
        vm.$ds.isAdmin = pageVm.$ds.isAdmin
      },
      items: [
        {
          type: 'input',
          text: Tech.$t('seniorTable.schemeName'),
          require: true,
          name: 'name',
          rules: [
            {
              required: true,
              trigger: 'blur',
              message: Tech.$t('seniorTable.pleaseEnterSchemeName')
            }
          ]
        },
        {
          type: 'input',
          text: Tech.$t('seniorTable.schemeDescription'),
          name: 'desc'
        }
      ]
    }
  ]
}
