import firstResetPasswordView from '../../../apps/base/views/rbacUser/resetPasswordOne'
import passwordExpireRemindView from '../../../apps/base/views/rbacUser/passwordExpireRemind'
import passwordInitRemind from '../../../apps/base/views/rbacUser/passwordInitRemind'
export default {
  type: 'container',
  id: 'container_meta_main_content_wrap',
  style: {
    height: '100%',
    flex: 1,
    display: 'flex',
    flexDirection: 'column',
    background: '#e1e7ec',
    width: '100%',
    overflow: 'auto'
  },
  name: '主内容外层容器',
  events: [],
  created: '',
  items: [
    passwordExpireRemindView,
    passwordInitRemind,
    {
      type: 'container',
      id: 'container_first_reset_password',
      items: [firstResetPasswordView]
    },
    {
      type: 'tabs',
      id: 'tabs_meta_main_content_labels',
      name: '主内容顶部标签列表',
      className: 'fill-full gloable-top',
      activeId: '',
      keepAlive: true,
      async: true, // 异步加载tab
      events: [],
      created: async (vm) => {
        if (tech?.TABIFRAME) {
          vm.data.alwayMount = true
        }
        // 非iframe内嵌模式时才执行重置密码提醒
        if (!tech?.TABIFRAME?.inner && !window?.$wujie?.microApp) {
          window.Tech.tBus.$on('getProfileUserInfo', vm.$cmd.getProfileUserInfo)
        }
      },
      mounted: async (vm) => {
        // 重置实例里面的 tabRemove 方法
        if (vm?.instance?.tabRemove) {
          Tech.$set(
            vm.instance,
            'tabRemove',
            (removeId) => {
              try {
                Scope.removeMenuTabConfirm(Scope.vm, {
                  tabName: removeId,
                  cb: () => {
                    Super.tabRemove(removeId) // 调回原来的关闭
                  }
                })
              } catch (e) {
                // console.log(' === tabRemove reset err = ', e)
                Super.tabRemove(removeId) // 调回原来的关闭
              }
            },
            { vm, removeMenuTabConfirm: vm.$cmd.removeMenuTabConfirm }
          )
        }
      },
      beforeDestroy: (vm) => {
        if (!tech?.TABIFRAME?.inner) {
          window.Tech.tBus.$off('getProfileUserInfo', vm.$cmd.getProfileUserInfo)
        }
        if (vm?.data?._allowRunRouteTImer) {
          clearTimeout(vm.data._allowRunRouteTImer)
          vm.data._allowRunRouteTImer = null
          vm._gotoing = false
        }
      },
      commands: {
        getProfileUserInfo: async (dataObj) => {
          const vm = tech_app.page.getNode('tabs_meta_main_content_labels')
          if (dataObj?.resetPassword) {
            window.ELEMENT.Message.info(dataObj.resetPasswordHint)
            const resetPassword = vm.$select('dialog_meta_rest_pwd_first')
            resetPassword.data.display = true
          }
        },
        session(vm) {
          setTimeout(() => {
            sessionStorage.setItem(
              vm.data.id,
              JSON.stringify({
                menus: vm.data.items.map((item) => {
                  // 菜单配置的wujie不需要执行
                  if (
                    tech?.TABINSERT &&
                    tech.TABINSERT.insert === 'self' &&
                    item.menu.isRebuildView
                  ) {
                    // wujie自身嵌套，清除自身嵌套的url参数
                    item.url = tech.microApp.clearLinkSearch(item.url)
                  }
                  return { ...item, isCache: true, lazy: true, items: [] }
                }),
                activeId: vm.instance.curActive
              })
            )
          })
        },
        // 该页签下页面为表单状态的，且配置控制的，则关闭前解除控制
        unlockForm(vm) {
          const tabs_meta_main_content_labels = JSON.parse(sessionStorage.getItem(vm.data.id))
          const removedTabs = []
          // 寻找删除了的tabs
          for (let key in tabs_meta_main_content_labels.menus) {
            //用来遍历的数组使用两个数组长度比较长的，不然可能没有效果
            let stra = tabs_meta_main_content_labels.menus[key]
            let count = 0
            for (let j = 0; j < vm.data.items.length; j++) {
              let strb = vm.data.items[j]
              if (stra.id == strb.id) {
                count++
              }
            }
            if (count === 0) {
              removedTabs.push(stra)
            }
          }
          removedTabs.forEach((item) => {
            let table_main = vm.$select(`${item.menu.name}_table_main`)
            let table_detail = vm.$select(`${item.menu.name}_table_detail`)
            if (table_main?.data.afterEdit && table_detail.$ds.clickType == 'edit') {
              // 解除编辑锁定状态
              const row = table_detail?.$ds?.mainTableRowData || {}
              const afterEditFn = new Function('return ' + table_main?.data?.afterEdit)
              const afterEdit = afterEditFn()
              afterEdit(vm, row)
            }
          })
        }
      },
      // 统计过滤items方法
      statisticFilter: (items) => {
        if (items) {
          return items.filter((item) => item?.isCacheShowTab !== false)
        } else {
          return items
        }
      },
      onTabRemove: async (tabId) => {
        let curPre = tech_app.page.getNode(tabId)?.$ds?.idPre
        // 清理表格数据源防止内存溢出
        try {
          let tb = tech_app.page.getNode(curPre + 'table_main_table')
          if (tb?.data?.tableData) {
            tb.data.tableData = null
          }
          if (tb?.instance?.$props?.tableData) {
            tb.instance.$props.tableData = null
          }
          if (tb?.data?.tableDataOrigin) {
            tb.data.tableDataOrigin = null
          }
          // 回收主表格的上一次实例对象避免内存溢出
          if (tb?.data?._lastInstance) {
            Tech.forceGCInstance(tb.data._lastInstance)
            tb.data._lastInstance = null
          }
          tb = null
          let tbWrap = tech_app.page.getNode(curPre + 'table_main')
          let tbDs = tbWrap?.data?.ds_config?.list?.find((it) => it.name === 'tableData')
          if (tbDs?.res?.data) {
            tbDs.res.data = null
          }
          tbDs = null
          tbWrap = null
        } catch (e) {
          // console.log(' == onTabRemove error == ', e)
        }
        await new Promise((resolve) => setTimeout(resolve, 0))
      },
      // bind_t: {
      //   path: '$self.items',
      //   transform: (params) => {
      //     console.log(11111, params.value)
      //     return ''
      //   }
      // },
      bind_on_tabRemove: (params) => {
        if (params?.self?.app?.page?.nodes && params?.value !== undefined) {
          // params.self.app.page.nodes.delete(params.value)
          let curPre = tech_app.page.getNode(params?.value)?.$ds?.idPre
          window.setTimeout(() => {
            params.self.app.page.removeNodeNest(params.value)
            try {
              if (curPre) {
                let keyArr = []
                let nodes = tech_app.page.nodes
                for (let [key, value] of nodes) {
                  keyArr.push(key)
                }
                keyArr.map((kItem) => {
                  // if (kItem.startsWith(curPre)) {
                  let kNode = tech_app.page.getNode(kItem)
                  if (kNode?.$ds?.idPre === curPre || kNode?.$ds?.__fromIdPre === curPre) {
                    params.self.app.page.removeNodeNest(kItem)
                  }
                  // }
                })
              }
            } catch (e) {
              // console.log(' == error == ', e)
            }
          }, 0)
        }
        params.self.$cmd.unlockForm(params.self)
        params.self.$cmd.session(params.self)
      },
      beforeGoto: async (tab) => {
        try {
          if (tab?.name !== undefined) {
            let vm = tech_app.page.getNode('tabs_meta_main_content_labels')
            let active = vm?.data?.items?.find((item) => item.id === tab.name)
            if (active?.menu?.activeUrl !== undefined) {
              window.tech_tmp_pathname = active.menu.activeUrl
              // 判断按需加载路由对应的app扩展资源
              if (window?.tech_app?.updateOptions) {
                await window.tech_app.updateOptions({ updateSchema: false }) // 以不更新原来的视图方法更新资源参数
              }
              window.tech_tmp_pathname = null
            }
          }
        } catch (e) {
          console.log(' === beforeGoto error == ', e)
        }
        return
      },
      bind_on_goto: (params) => {
        params.self.$cmd.session(params.self)
      },
      bind_on_closeRight: (params) => {
        params.self.$cmd.unlockForm(params.self)
        params.self.$cmd.session(params.self)
      },
      bind_on_closeOther: (params) => {
        params.self.$cmd.unlockForm(params.self)
        params.self.$cmd.session(params.self)
      },
      items: []
    },
    {
      type: 'container',
      id: 'container_meta_footer_content',
      name: '脚部容器',
      className: 'container-meta-footer-content',
      name: '容器',
      events: [],
      style: {},
      created: (vm) => {
        if (tech?.TABIFRAME?.inner) {
          // tabiframe内部情况先隐藏
          // vm.data.style.display = 'none'
          vm.data.items = []
          vm.data.style.padding = 0
          vm.data.style.border = 0
          vm.data.style.width = 0
          vm.data.style.height = 0
          vm.data.style.margin = 0
        }
      },
      items: [
        {
          type: 'container',
          id: 'container_meta_footer_content_bread',
          name: '脚部面包线容器',
          events: [],
          created: '',
          items: [
            {
              type: 'breadcrumb',
              id: 'breadcrumb_meta_footer_breadcrumb',
              appName: '',
              name: '面包线',
              events: [],
              created: '',
              style: {
                background: '#fff'
              }
            }
          ]
        },
        {
          type: 'container',
          id: 'container_meta_footer_copyright_wrap',
          name: '底部版权容器',
          events: [],
          created: '',
          style: {
            height: '100%',
            display: 'flex',
            'align-items': 'center',
            'margin-right': '.04rem'
          },
          items: [
            {
              type: 'text',
              id: 'container_meta_footer_copyright',
              name: '底部版权文本',
              // value: Tech.$t('common.reserved'),
              value: Tech.$t('basicPlatformInformation.copyrightInfo'),
              style: {
                fontSize: 14,
                color: '#999',
                fontWeight: 500
              },
              events: [],
              created: ''
            }
          ]
        }
      ]
    }
  ]
}
