import getOnlyLookRequired from '../../../../snest/from-fields/form/onlyLookRequired'
import meta_set_drawer_form from '../../seniorTable/meta_set_drawer_form'
export default {
  type: 'drawer',
  crossEvent: true, // mark的事件穿透
  visible: true, //显示或隐藏抽屉
  hasTitle: false,
  wrapperClosable: false,
  drawerDrag: false,
  bind_showModal: '${$ds.isShowModal}', // 是否显示遮罩
  id: 'table_drawer',
  bind_showEditBtn: '${!$ds.isEditDrawerForm}', //显示编辑按钮
  bind_showSaveBtn: '$ds.isEditDrawerForm', //显示保存按钮
  $improve: {
    'drawerForm.created': 'created',
    'drawerForm.mounted': 'mounted',
    'drawerForm.destroy': 'destroy'
  },
  className: 'pop_drawer_from',
  dataSource: {
    layoutType: '', // 布局类型
    editId: '',
    showDrawerBtn: true,
    isEditDrawerForm: false,
    canEditForm: true, // 编辑按钮是否可用
    isDrawerFormNotSave: false,
    isDrawerNotSave: false,
    createIds: [],
    activeTab: ''
  },
  css: '.pop_drawer_from .drawer-body{height: 100%}',
  commands: {
    // 在表单里面移出 mainTableColumns
    removeMainTableColumns: (vm, formValus) => {
      let reObj = {}
      if (vm.$ds?.tabConfig?.mainTableColumns && formValus && !vm.$ds.isDetail) {
        let mainTableColumns = vm.$ds.tabConfig.mainTableColumns
        let cols = []
        mainTableColumns.map((item) => {
          if (Object.prototype.toString.call(item) === '[object Object]') {
            cols.push(item.name)
          } else {
            cols.push(item)
          }
        })
        for (let k in formValus) {
          if (cols.includes(k)) {
            reObj[k] = formValus[k]
            delete formValus[k]
          }
        }
      }
      return reObj
    },
    // 根据子表操作列编辑按钮状态设置编辑按钮是否展示
    editBtnEnableCondition: (vm) => {
      let selectedTableData = vm.$select(`${vm.$ds.idPreTab}table_main_table`).$ds.selectedTableData
      let tool_btns = vm.$select(`${vm.$ds.idPreTab}table_main_table_column_operation`)
      // 获取子表格中编辑按钮是否禁用，如果禁用，抽屉表单不展示编辑按钮
      const editBtn = tool_btns?.data?.btns.find((item) => item.action == 'updateEr')
      let mainTableObj = vm.$select(vm.$ds.idPre + 'table_main')
      let formTabView = mainTableObj?.$ds?.tableView?.data?.views?.form?.body?.tabs?.find(
        (item) => vm?.$ds?.tabConfig?.field === item?.body?.field
      )
      const btns = formTabView?.body?.buttons
      const haveEdit = btns?.find((i) => i.action === 'updateEr')
      let authDisplay = true
      if (haveEdit) {
        // 如果有权限信息取权限配置，如果没有不影响原来的判断
        authDisplay = haveEdit?.authInfo ? haveEdit?.authInfo?.isDisplay : true
      }
      if (editBtn?.enableCondition) {
        let showEditBtnFun = new Function('return ' + editBtn?.enableCondition)()
        return showEditBtnFun(selectedTableData)
      } else {
        return authDisplay
      }
    },
    // 判断表单是否未保存
    syncFormSaveStatus: (vm) => {
      try {
        let tabHasNotSave = false
        const idPre = vm.$cmd.getIdPre(vm)
        // 获取tabs节点
        let tabs = vm.$select(idPre + 'drawer_form_tabs_node')
        // console.log(' ==== tabs === ', tabs);
        if (tabs?.data?.items) {
          tabs.data.items.map((item) => {
            let tabNode = vm.$select(item.id)
            if (tabNode) {
              if (tabNode.$ds.isTabNotSave) {
                tabHasNotSave = tabNode.$ds.isTabNotSave
              }
            }
          })
        }
        vm.$ds.isDrawerNotSave = vm.$ds.isDrawerFormNotSave || tabHasNotSave
      } catch (e) {
        // console.log(' ==== syncFormSaveStatus == error == ', e)
      }
    },
    // 加载抽屉孙表
    drawerSubTable: async (vm) => {
      const tabTable = vm.$select(vm.$ds.idPreTab + 'table_main_table')
      let rowId = tabTable.$ds.mainTableRowData.id
      if (!vm.$ds.editId) {
        let res = await vm.request('generateIds', {
          args: {
            num: 1
          }
        })
        vm.$ds.createIds = res?.data
        rowId = res?.data[0]
      }
      let loadViewData = tabTable.$ds.tableView
      if (loadViewData?.data) {
        loadViewData = loadViewData.data
      }
      let tabs = await vm.$cmd.meta.formatTabs(vm, {
        view: window.Tech._cloneDeep(loadViewData?.views?.form),
        fields: loadViewData?.fields,
        permissions: loadViewData?.permissions
      })
      for (let i = 0; i < tabs.length; i++) {
        tabs[i].items = []
        const rowKey =
          tabTable.$ds.tableView?.data?.fields[tabs[i].dataSource._field]?.attrs?.InverseName
        let paramsData = rowId ? [rowKey, '=', rowId] : []
        const openTab = {
          type: 'container',
          view: {
            created: {
              __parentId: tabs[i].id,
              _noCache: true,
              _reInit: true,
              inheritData: false,
              css: `#${tabs[i].id}_items_0_view_created{height:100%}`,
              openView: {
                preId: tabs[i].id + '_', // 全局业务唯一标识前缀 不能重复
                layoutType: vm.$ds.layoutType,
                parentMainPre: vm.$ds.idPre,
                parentSubPre: vm.$ds.idPreTab,
                followPre: vm.$ds.idPreTab,
                app: tabTable?.$ds?._metaParamsApp || 'base',
                model: tabs[i].dataSource.tabConfig.model, // 后端模型名
                type: loadViewData?.views?.form?.body?.tabs?.[i]?.body?.type || 'form,grid,search', // 后端视图类型 多个类型以,逗号隔开
                api: {
                  grid: {
                    search: {
                      params: {
                        args: {
                          filter: [paramsData]
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
        tabs[i].items.push(openTab)
        vm.app.updatePageNode(tabs[i], vm, () => {
          if (tabs[i].display !== false && tabs[i].body?.authInfo?.isDisplay !== false) {
            vm.data.items.push(tabs[i])
          }
        })
      }
      const visibleTabIds = tabs.filter((item) => item.display).map((item) => item.id)
      vm.data.activeId = visibleTabIds[0]
      vm.$ds.activeTab = visibleTabIds[0]
      vm.instance.$nextTick(() => {
        vm.$cmd.syncFormSaveStatus(vm)
      })
    },
    // 表单翻页替换表单数据 切换子表选中行
    initDrawerForm: async (vm) => {
      const idPre = vm.$cmd.getIdPre(vm)
      const tabTable = vm.$select(idPre + 'table_main_table')
      tabTable.$ds.selectedTableData[0] = tabTable.$ds.mainTableRowData
      tabTable.instance.setBoxSelected(tabTable.$ds.mainTableRowData, 'isReset', null)
      const rowData = tabTable.$ds.mainTableRowData
      let dsForm = {}
      let maintableObjVal = {}
      if (
        vm.$ds?.typeView === 'subTable' &&
        vm.$ds?.tabConfig?.mainTableColumns &&
        !vm.$ds.isDetail
      ) {
        let maintableObj = vm.$select(vm.$ds.idPre + 'table_main_table')
        let rowValue = maintableObj?.instance?.getEditActived()
        if (rowValue?.row) {
          rowValue = rowValue?.row
        }
        if (!rowValue) {
          rowValue = maintableObj?.instance?.boxSelected?.[0]
        }

        let mainTableColumns = vm.$ds?.tabConfig?.mainTableColumns
        let cols = []
        mainTableColumns.map((item) => {
          if (Object.prototype.toString.call(item) === '[object Object]') {
            cols.push(item.name)
          } else {
            cols.push(item)
          }
        })
        if (rowValue) {
          for (let k in rowValue) {
            if (cols.includes(k)) {
              maintableObjVal[k] = rowValue[k]
            }
          }
        }
      }
      let containerMain = vm.$select(idPre + 'container_main_content')
      if (rowData.id) {
        const drawerForm = vm.$select(idPre + 'table_drawer_form')
        let viewConfig = await vm.$cmd.getDrawerFromView(vm)
        let data = vm.$cmd.meta.formFormat.initForm(vm, viewConfig?.views?.form, viewConfig?.fields)
        const filterArr = vm.$cmd.meta.formFormat.handleSearchData({ id: rowData.id }, data.items)
        let queryParams = {
          args: {
            filter: filterArr || [],
            properties: vm.$cmd.meta.toProperty(
              viewConfig.views.form.body.columns,
              viewConfig.fields
            )
          }
        }
        // 查询前钩子
        queryParams = await Tech.callHook(containerMain, 'beforeQuery', queryParams, {
          triggerVm: vm
        })
        if (queryParams === false) {
          return
        }
        // 请求drawer表单的单条数据 查询钩子
        // let res = await vm.request('drawerFormData', queryParams)
        let res = await Tech.callHook(containerMain, 'query', queryParams, {
          triggerVm: vm
        })
        if (res === false) {
          return
        }
        // 查询后钩子
        dsForm = await Tech.callHook(containerMain, 'afterQuery', res, {
          triggerVm: vm,
          maintableObjVal,
          rowData,
          viewData: data
        })
        if (dsForm === false) {
          return
        }
        for (var key in drawerForm.$ds.form) {
          drawerForm.$ds.form[key] = dsForm[key]
        }
      }
    },
    // 检查表单是否保存
    checkDrawerFormSave: (vm) => {
      // 有保存按钮判断是否存在已编辑项
      return new Promise((resolve, reject) => {
        // 保存按钮显示 且 表单或子表存在已编辑未保存
        if (
          vm.$ds.isEditDrawerForm &&
          vm.$ds.showDrawerBtn &&
          vm.$ds.canEditForm &&
          vm.$ds.isDrawerNotSave
        ) {
          const delDialog = vm.$select(`${vm.$ds.idPre}table_main_pop_dialog`)
          const delDialogText = vm.$select(`${vm.$ds.idPre}table_main_pop_dialog_text`)
          delDialogText.data.value = Tech.$t('detailView.pageDownHint')
          // 是否关闭当前表单？关闭后，将不会保留当前数据
          const delconfirm = (close) => {
            // 确定-切换行数据 不会保留当前数据s
            close()
            vm.$ds.isDrawerNotSave = false
            vm.$ds.isDrawerFormNotSave = false
            resolve(true)
          }
          const delCancel = (close, options) => {
            // 取消-留在当前项目
            close()
            resolve(false)
          }
          delDialog.data.display = true
          delDialog.data.options.confirm = delconfirm
          delDialog.data.options.cancel = delCancel
          delDialog.data.confirmText = Tech.$t('toolbar.dialogConfirm')
          delDialog.data.cancelText = Tech.$t('toolbar.dialogCancle')
        } else {
          resolve(true)
        }
      })
    }
  },
  created: (vm) => {
    // 抽屉表单孙表
    vm.$ds.layoutType = vm.$ds.tableView.data.views?.form?.body?.layoutType || ''
    // 抽屉表单的孙表是否跟抽屉表单一起保存
    vm.$ds.drawerSaveTabs = vm.$ds.tableView.data.views?.form?.body?.drawerSaveTabs || false
    vm.data.drawerDrag = vm.$ds._drawerDrag
    if (vm.$ds.editId) {
      vm.$ds.canEditForm = vm.$cmd.editBtnEnableCondition(vm)
    }
  },
  items: [
    {
      type: 'container',
      id: 'table_drawer_title',
      style: {
        'margin-bottom': '0.1rem',
        'padding-top': '.05rem',
        display: 'flex',
        'align-items': 'center'
      },
      dataSource: {
        mainTableAllData: { data: [] },
        isTurnPage: false,
        turnPageType: ''
      },
      created: (vm) => {
        const idPre = vm.$cmd.getIdPre(vm)
        let tableMain = vm.$select(idPre + 'table_main')
        if (vm.$ds.isOpenViewTab) {
          tableMain = vm.$select(vm.$ds.orginPreId + 'table_main')
        }
        if (!vm.$ds.mainTableAllData.data) {
          vm.$ds.mainTableAllData.data = []
        }
        vm.$ds.mainTableAllData.data.length = 0
        // 使用Object.assign赋值避免数据量大触发响应式
        Object.assign(
          vm.$ds.mainTableAllData.data,
          tableMain.$ds.tableData?.data?.map((item) => {
            return { ...item }
          }) || []
        )
        const isOnlyLookRequired =
          tableMain?.$ds?.tableView?.data?.views?.form?.body?.onlyLookRequired || false
        if (isOnlyLookRequired) {
          const config = getOnlyLookRequired()
          config.id = vm.$ds.idPre + config.id
          config.bind_display = '${$ds.isEditDrawerForm && $ds.canEditForm}'

          tech_app.updatePageNode(config, vm, () => {
            vm.data.items.push(config)
          })
        }
      },
      beforeDestroy: (vm) => {
        vm.data.dataSource.mainTableAllData = { data: [] } // 重置mainTableAllData
      },
      items: [
        {
          type: 'button',
          value: Tech.$t('detailView.close'),
          style: {
            color: '#606266',
            'font-size': '0.15rem',
            'border-right': '0 none'
          },
          options: {
            type: 'text',
            icon: 'el-icon-close'
          },
          bind_on_click: (res) => {
            const { self: vm } = res
            vm.$select(vm.$ds.idPreTab + 'table_drawer').data.visible = false
            // 还原未保存判断状态
            vm.$ds.isDrawerFormNotSave = false
            vm.$ds.isDrawerNotSave = false
          }
        },
        {
          type: 'pagetopsplit',
          bind_display: '${!$ds.isEditDrawerForm && $ds.showDrawerBtn && $ds.canEditForm}',
          style: {
            height: '.14rem',
            'background-color': '#CCCCCC',
            margin: '0 .07rem'
          }
        },
        {
          type: 'button',
          value: Tech.$t('gridView.editBtn'),
          bind_display: '${!$ds.isEditDrawerForm && $ds.showDrawerBtn && $ds.canEditForm}',
          options: {
            size: 'mini'
          },
          className: 'table_drawer_btn',
          css: `.table_drawer_btn{
              font-size: 0.14rem;
              padding: 0.06rem 0.1rem;
              border: none;
              background: #677177;
              color: #fff;
            }
            .table_drawer_btn:hover,
            .table_drawer_btn:focus {
              color: #fff;
              background: #495053;
            }
          `,
          bind_on_click: async (res) => {
            const { self: vm } = res
            vm.$ds.isCreated = false
            vm.$ds.isEditDrawerForm = true
            const idPre = vm.$cmd.getIdPre(vm)
            const drawerForm = vm.$select(idPre + 'table_drawer_form')
            if (drawerForm.data.formConfig.preview === true) {
              drawerForm.data.formConfig.preview = false

              let formNodeData = vm.$select(idPre + 'table_drawer_form')?.data
              if (formNodeData) {
                formNodeData.display = false
                await new Promise((resolve) => setTimeout(resolve, 0))
                formNodeData.display = true
                await new Promise((resolve) => setTimeout(resolve, 50))
              }

              // let viewConfig = await vm.$cmd.getDrawerFromView(vm)
              // let data = vm.$cmd.meta.formFormat.initForm(
              //   vm,
              //   viewConfig?.views?.form,
              //   viewConfig?.fields
              // )
              // const tabTable = vm.$select(idPre + 'table_main_table')
              // const rowData = tabTable.$ds.mainTableRowData
              // await vm.$cmd.showDrawerForm(drawerForm, rowData, {
              //   btn: { action: 'updateEr' },
              //   viewData: data,
              //   viewConfig: viewConfig
              // })
            }
            if (vm.$ds.layoutType == 'drawerTable') {
              const tabTable = vm.$select(vm.$ds.activeTab + '_table_main_table')
              vm.$ds.clickType = 'edit'
              const btns = vm.$select(tabTable.$ds.menuConfig.preId + 'table_main_toolbar_btns')
              btns.data.items.map((item) => {
                if (item.display) {
                  item.options.disabled = false
                }
              })
              let defaultCancelEdit =
                tabTable.$ds.tableView.data?.views?.grid?.body?.gridEditMode?.defaultCancelEdit
              const editBtnVm = vm.$select(
                tabTable.$ds.menuConfig.preId + 'table_toolbar_rowEdit_edit'
              )
              if (defaultCancelEdit && editBtnVm) {
                setTimeout(() => {
                  editBtnVm?.instance?.click()
                }, 150)
              }
            }
          }
        },
        {
          type: 'button',
          value: Tech.$t('detailView.affirm'),
          bind_display: '$ds.isEditDrawerForm && $ds.showDrawerBtn && $ds.canEditForm',
          options: {
            size: 'mini'
          },
          className: 'table_drawer_btn',
          loading: false,
          _clickTimer: null,
          loadingTime: 1500,
          css: `.table_drawer_btn{
              font-size: 0.14rem;
              margin-left: 0.05rem;
              padding: 0.06rem 0.1rem;
              border: none;
              background: #677177;
              color: #fff;
            }
            .table_drawer_btn:hover,
            .table_drawer_btn:focus {
              color: #fff;
              background: #495053;
            }
          }`,
          bind_on_click: async (res) => {
            const vm = res.self
            vm.data.loading = true
            if (vm.data._clickTimer) {
              clearTimeout(vm.data._clickTimer)
              vm.data._clickTimer = null
            }
            vm.data._clickTimer = setTimeout(() => {
              vm.data.loading = false
            }, 500)

            res = await Tech.callHook(vm, 'validate', res, {})
            if (res === false) {
              return
            }

            res = await Tech.callHook(vm, 'beforeSave', res, {})
            if (res === false) {
              return
            }
            let saveRes = await Tech.callHook(vm, 'save', res, {
              triggerType: vm.$ds.editId ? 'edit' : 'add',
              isAloneSave: vm.$ds._isAloneSave,
              isSubTable: vm.$ds.typeView == 'subTable',
              isSingleGrid: vm.$ds._viewType == 'singleGrid'
            })
            // 还原未保存判断状态
            vm.$ds.isDrawerFormNotSave = false
            vm.$ds.isDrawerNotSave = false
            if (saveRes === false) {
              return
            }
            saveRes = await Tech.callHook(vm, 'afterSave', saveRes, {})
            if (saveRes === false) {
              return
            }
          },
          destroy: (vm) => {
            // 回收定时器
            if (vm.data._editsLoadingTimer) {
              clearTimeout(vm.data._editsLoadingTimer)
              vm.data._editsLoadingTimer = null
            }
            if (vm.data._editLoadingTimer) {
              clearTimeout(vm.data._editLoadingTimer)
              vm.data._editLoadingTimer = null
            }
          }
        },
        {
          type: 'button',
          id: 'drawer_form_main_detail_top_setting',
          className: 'form-toolbar-setting-btn',
          display: true,
          name: 'buttons',
          value: Tech.$t('seniorTable.setField'),
          options: {
            size: 'mini'
          },
          style: {
            background: 'var(--button-primary-bg, #677177)',
            border: 'none',
            marginRight: '0.1rem',
            fontSize: '0.14rem',
            lineHeight: '0.13rem'
          },
          bind_on_click: async (params) => {
            const { self: vm } = params
            const idPre = vm.$cmd.getIdPre(vm)
            const dialog = vm.$select(idPre + 'dialog_meta_set_drawer_form')
            dialog.data.display = true
          },
          created: (vm) => {
            const tableView = vm.$ds.tableView.data
            const { views } = tableView
            // iot部分页面custom配置的表单页面不显示设置按钮
            vm.data.display = window.$tech?.techAdvancedTable && views.form ? true : false

            // 开启了高级表格 并且 设置了“设置字段” 隐藏，则不显示设置按钮
            if (window.$tech?.techAdvancedTable && window.$tech?.techTableHideSetField) {
              vm.data.display = false
            }
          }
        },
        // 抽屉表单tbar
        {
          type: 'container',
          id: 'drawer_form_tbar',
          style: { marginLeft: 10 },
          created: (vm) => {
            vm.$cmd.meta.formFormat.addFormTbar(vm, 'drawer_form')
          },
          items: []
        },
        // 抽屉表单分页
        {
          type: 'paging-form',
          id: 'drawer_form_main_header_paging',
          bind_pageSize: '$ds.paging.pageSize',
          bind_pageStart: '$ds.paging.pageStart',
          // bind_display:
          //   '$ds.isEditDrawerForm && $ds.showDrawerBtn && $ds.canEditForm',
          style: {
            marginLeft: '0.08rem'
          },
          dataSource: {
            loading: false
          },
          created: async (vm) => {
            const tabEditObj =
              typeof vm.$ds.tabConfig?.tabEditObj == 'string'
                ? JSON.parse(vm.$ds.tabConfig?.tabEditObj)
                : vm.$ds.tabConfig?.tabEditObj
            if (tabEditObj?.paging !== undefined) {
              // 取视图配置
              vm.data.display = tabEditObj?.paging
            } else {
              if (window.$tech?.popDrawerFormPaging !== undefined) {
                // 取系统级配置
                vm.data.display = window.$tech?.popDrawerFormPaging
              } else {
                vm.data.display = false
              }
            }
            if (!vm.$ds.editId) {
              vm.data.display = false
            }
            if (vm.$ds.mainTableRowData) {
              vm.data.pageStart = vm.$ds.mainTableRowData.rowIndex
            }
            vm.data.pageSize = vm.$ds.mainTableAllData.data?.length || 0
          },
          bind_on_changePage: async (params) => {
            const { self: vm, value } = params
            const idPre = vm.$cmd.getIdPre(vm)
            if (vm.$ds.loading) return
            if (value.type == 'prev' && value.prev) return false
            if (value.type == 'next' && value.next) return false
            vm.$ds.isTurnPage = true
            vm.$ds.turnPageType = value.type == 'prev' ? 'prev' : 'next'

            vm.$cmd.checkDrawerFormSave(vm).then(async (toNext) => {
              if (toNext) {
                vm.$ds.isTurnPage = false
                vm.$ds.loading = true
                let rowIndex = 0
                if (vm.$ds.mainTableRowData) {
                  rowIndex = vm.$ds.mainTableRowData.rowIndex
                }
                let index = value.type == 'next' ? rowIndex + 1 : rowIndex - 1
                let row = vm.$ds.mainTableAllData.data[index]
                vm.$ds.editId = row.id
                row.rowIndex = index
                vm.$ds.mainTableRowData = row || {}
                vm.data.pageStart = index
                let form_top = vm.$select(idPre + 'drawer_form_tabs_node')
                const table_drawer_form = vm.$select(idPre + 'table_drawer_form')
                table_drawer_form.data.display = false
                setTimeout(() => {
                  table_drawer_form.data.display = true
                }, 200)
                // 表单翻页更新表单及其子表数据
                vm.$cmd.initDrawerForm(form_top).then(() => {
                  form_top.data.items = []
                  if (vm.$ds.layoutType == 'drawerTable') {
                    vm.$cmd.drawerSubTable(form_top) // 更新底部tabs
                  }
                  vm.$ds.loading = false
                  const onlyLookRequiredNode = vm.$select(idPre + 'only_look_required')
                  if (onlyLookRequiredNode?.instance) {
                    onlyLookRequiredNode.instance.setCheck?.(false)
                    onlyLookRequiredNode.instance.change?.(null)
                  }
                })
                vm.$ds.loading = false
              }
            })
          }
        }
      ]
    },
    {
      type: 'form', //可以用用表单工具渲染
      id: 'table_drawer_form',
      className: 'table_drawer_form',
      dataSource: {
        form: {}
      },
      ds_config: {
        list: [
          {
            name: 'formSearch',
            type: 'meta',
            method: 'service',
            autoRequest: false,
            options: {}
          },
          {
            name: 'formUpdate',
            type: 'meta',
            method: 'service',
            autoRequest: false,
            options: {},
            reqAfter: (vm, res, config) => {
              if (res?.data !== undefined) {
                vm.$select(vm.$ds.idPreTab + 'table_drawer').data.visible = false
                vm.$select(vm.$ds.idPreTab + 'table_main_toolbar_refresh').instance.click()
                //     try {
                //       // 清理er表缓存
                //       let objNode = vm.$select(vm.$ds.idPre + 'form_main_detail_top_header')
                //       objNode?.$cmd?.clearErField(vm)
                //     } catch (e) {}
              }
              return res
            }
          }
        ]
      },
      formConfig: {
        bind_disabled: '${!$ds.isEditDrawerForm}',
        labelPosition: 'top'
      },
      items: [],
      created: async (vm) => {
        const idPre = vm.$ds.idPreTab ?? vm.$ds.idPre
        let tableVM = vm.$select(idPre + 'table_main')
        vm.data.formConfig.labelPosition =
          tableVM.$ds.tableView.data.views?.form?.body?.formConfig?.labelPosition ||
          window.$tech?.formLabelPosition ||
          'top'
        // 表单预览状态展示
        if (
          window.$tech?.previewForm &&
          ((vm.$ds.isDetail && vm.$ds.clickType == 'preview') ||
            (!vm.$ds.isDetail && !vm.$ds.isEditDrawerForm))
        ) {
          vm.data.formConfig.preview = true
          vm.data.formConfig.previewChange = vm.$cmd.meta.formFormat.previewChange
        }
        if (vm.$ds.layoutType == 'drawerTable') {
          const tabsNode = vm.$select(vm.$ds.idPreTab + 'drawer_tab_sub_table_wrap')
          tabsNode.data.display = true
          vm.data.style = {
            height: '35%',
            overflowY: 'auto'
          }
        }
      },
      formChange: (vm, type, data) => {
        vm.$ds.isDrawerFormNotSave = true // 标识表单未保存
        vm.$cmd.syncFormSaveStatus(vm.app.page.getNode(vm.data.id))
      }
    },
    meta_set_drawer_form,
    // 孙表tabs
    {
      type: 'container',
      id: 'drawer_tab_sub_table_wrap',
      className: 'drawer_tab_sub_table_wrap_css',
      display: false,
      style: {
        width: '100%',
        height: '60%',
        background: 'rgb(225, 231, 236)'
      },
      css: '.drawer_tab_sub_table_wrap_css .tech-tabs .el-tabs__header{padding: 0.02rem}',
      items: [
        {
          type: 'tabs',
          id: 'drawer_form_tabs_node',
          className: 'drawer_form_tabs_node',
          close: false,
          activeId: '',
          activeWork: true, // 切换到的tab才生效
          style: {
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
            width: '100%',
            height: '100%',
            marginTop: '0.02rem'
          },
          dataSource: {
            data1: {
              /** 接口返回的数据 */
            }
          },
          ds_config: {
            list: [
              {
                name: 'generateIds',
                type: 'meta',
                method: 'service',
                autoRequest: false,
                options: {
                  params: {
                    model: 'meta_app',
                    service: 'generateIds',
                    app: 'sie-iidp-app-store',
                    args: {
                      num: 1
                    }
                  }
                }
              }
            ]
          },
          created: async (vm) => {
            if (vm.$ds.layoutType == 'drawerTable') {
              // 加载抽屉孙表
              vm.$cmd.drawerSubTable(vm)
            }
          },
          items: []
        }
      ]
    }
  ]
}
