import { MicroConfig } from './micro-app-data'
import WujieMicroApp from './micro-wujie'

const createMicroApp = (microConfig: MicroConfig) => {
  switch (microConfig.micro) {
    case 'wujie':
      const wujieProps = window?.$wujie?.props
      return new WujieMicroApp(microConfig, wujieProps)
  }
}

export default createMicroApp
