import dateFormat from './date'
// 验证手机号
const validatePhone = (rule, value) => {
  if (rule.value === '') {
    rule.callback(new Error(Tech.$t('tenant.validatePhone')))
  } else if (!/^1[3|4|5|6|7|8|9][0-9]\d{8}$/.test(rule.value)) {
    rule.callback(new Error(Tech.$t('tenant.validatePhoneEnter')))
  } else {
    rule.callback()
  }
}
// 验证邮箱
const validateEmail = (rule, value) => {
  if (rule.value === '') {
    rule.callback(new Error(Tech.$t('tenant.validateEmail')))
  } else if (
    !/^[a-zA-Z0-9_-]+@[a-zA-Z0-9_-]+(\.[a-zA-Z0-9_-]+)+$/.test(rule.value)
  ) {
    rule.callback(new Error(Tech.$t('tenant.validateEmailEnter')))
  } else {
    rule.callback()
  }
}
// 验证密码
const validatePassword = (rule, value) => {
  if (rule.value === '' || !rule || !rule.value) {
    rule.callback(new Error(Tech.$t('login.pPlaceholder')))
  } else if (rule.value.length < 4 || rule.value.length > 32) {
    rule.callback(new Error(Tech.$t('tenant.passwordHintLen')))
  } else {
    rule.callback()
  }
}

//验证客户ID
