// 验证日期是否过期
const validateDate = (rule, element) => {
  let time = rule.value
  //  console.log(time,new Date())
  let nowtime = dateFormat(new Date()) //将标准时间格式转换为yyyy-MM-dd格式
  // var datetime = new Date(Date.parse(time.replace(/-/g, '/'))).getTime()
  const datetime = Date.parse(time)
  var now = new Date(Date.parse(nowtime.replace(/-/g, '/'))).getTime()
  //console.log(time,now,datas,nows)
  if (!rule.value) {
    rule.callback(new Error(Tech.$t('tenant.pleaseEnter')))
  } else if (now > datetime) {
    rule.callback(new Error(Tech.$t('register.timeExpired')))
  } else {
    // debugger
    rule.callback()
  }
}

// 验证日期是否过期
