// 工作流程管理 - 我的待办 - 审批 - 审批流程 - 驳回弹窗选择节点
export const approvalRejectdialogView = (vm, userTaskId, callback) => {
  return {
    id: vm.$ds.idPre + 'approval_reject_dialog',
    type: 'dialog',
    name: '抽屉弹窗',
    width: '30%',
    title: Tech.$t('workflow.reject'),
    visible: true,
    display: true,
    showModal: true,
    bind_on_operates: async (params) => {
      // 点击按钮
      const { self: vm, value } = params
      if (value.type === 'confirm') {
        // 校验
        const rejectForm = vm.$select('dialog_approval_reject_form')
        const bool = await rejectForm.instance.validate()
        if (!bool) {
          await callback(false)
        } else {
          await callback()
        }
      } else {
        await callback(false)
      }
      value.close() // 关闭弹窗方法
    },
    items: [
      {
        type: 'container',
        items: [
          {
            type: 'form',
            id: 'dialog_approval_reject_form',
            className: 'approval_reject_dialog_form',
            style: {
              display: 'flex',
              alignItems: 'center',
              width: '100%',
              justifyContent: 'space-between'
            },
            dataSource: {
              form: {
                rejectNode: null,
                retrialStatus: null
              }
            },
            css: `
               #dialog_approval_reject_form_items_0_form_item {
                width: 100%
               }
            `,
            items: [
              {
                type: 'row',
                items: [
                  {
                    type: 'select',
                    name: 'rejectNode',
                    display: true,
                    created: (vm) => {
                      let dialog =  vm.$select(vm.$ds.idPre + 'approval_reject_dialog')
                      if (dialog.data.btnConfig?.rejectParentStatus != '3') {
                        vm.data.display = false
                      }
                    },
                    rules: [
                      {
                        required: true,
                        message: Tech.$t('workflow.selectRejectNode')
                      }
                    ],
                    // text: '角色',
                    text: Tech.$t('workflow.rejectNode'),
                    className: 'approval_reject_dialog_select',
                    clearable: true,
                    bind_options: '$ds.rejectNodeList',
                    ds_config: {
                      type: 'meta',
                      name: 'rejectNodeList',
                      autoRequest: true,
                      options: {
                        params: {
                          args: {},
                          app: 'workflow',
                          model: 'wf_process_instance',
                          service: 'getArbitrarilyReject'
                        }
                      },
    
                      reqPrep: (vm, options, config) => {
                        // 修改请求参数
                        options.params.args.id = userTaskId
                        return options
                      },
                      reqAfter: (vm, res, config) => {
                        let newRes = res?.data?.map((item) => {
                          return {
                            // 显示值
                            text: item.name,
                            // 唯一标识
                            value: item.flowCode
                          }
                        })
                        // 返回转换后的数据
                        return newRes
                      }
                    }
                  },
                  {
                    type: 'select',
                    name: 'retrialStatus',
                    display: true,
                    created: (vm) => {
                      let dialog =  vm.$select(vm.$ds.idPre + 'approval_reject_dialog')
                      if (dialog.data.btnConfig?.retrialStatus != '2') {
                        vm.data.display = false
                      }
                    },
                    rules: [
                      {
                        required: true,
                        message: Tech.$t('workflow.selectApprovalMethod'),
                      }
                    ],
                    text: Tech.$t('workflow.approvalMethod'),
                    className: 'approval_retrial_dialog_select',
                    clearable: true,
                    options: [
                     {
                       label: Tech.$t('workflow.stepApproval'),
                       value: 0
                     },
                     {
                      label: Tech.$t('workflow.rejectDirect'),
                      value: 1
                     }
                    ]
                  }
                ]
              }
            ]
          }
        ]
      }
    ]
  }
}
