const initTreeToolbar = (vm, treeView, treeData) => {}

const transformFn = (fn) => {
  if (Object.prototype.toString.call(fn) === '[object String]') {
    try {
      fn = new Function('return ' + fn)()
    } catch (error) {
      console.log(' === showBtnFn error == ', e)
    }
  }
  return fn
}
const addAllNode = (vm, treeView, treeData) => {
  if (!treeView.hasAllNode) return treeData
  if (Object.prototype.toString.call(treeData) != '[object Array]') return treeData
  const allNode = {
    id: '',
    parentId: null,
    children: null,
    name: Tech.$t('toolbar.allTreeNode'),
    isAll: true
  }

  treeData = treeData || []
  // 添加其他字段
  const keys = Array.isArray(treeData) && treeData.length ? Object.keys(treeData[0]) : []
  let mergeKey = {}
  keys.map((key) => {
    mergeKey[key] = ''
  })

  treeData.unshift({
    ...mergeKey,
    ...allNode
  })

  return treeData
}
// 树视图的节点图标按钮
const initTreeButtons = (vm, treeView, treeData) => {
  const buttons = vm.app.utils._cloneDeep(treeView.buttons)
  const viewProps = treeView.props
  const iconListConfig = {
    create: {
      icon: 'el-icon-plus',
      type: 'add'
    },
    edit: {
      icon: 'el-icon-edit',
      type: 'edit'
    },
    delete: {
      icon: 'el-icon-delete',
      type: 'delete'
    }
  }
  // 添加自定义按钮
  if (treeView.customButtons) {
    treeView.customButtons?.forEach((item, index) => {
      iconListConfig[item.action] = {
        icon: item.icon,
        type: item.action
      }
      buttons.push({
        name: item.name,
        action: item.action
      })
    })
  }
  const btnFn = treeView.showBtnFn ? transformFn(treeView.showBtnFn) : null
  treeData.data.map((item) => {
    // 添加‘全部’节点的不需要添加图标按钮
    if (item.isAll) return
    // buttons的配置
    if (buttons?.length && buttons.indexOf('@defaults') === -1) {
      let iconList = []
      const hasBtn = btnFn ? btnFn(item) : null
      for (let i = 0; i < buttons.length; i++) {
        if (!hasBtn || (hasBtn && hasBtn[buttons[i].action])) {
          iconListConfig[buttons[i].action].message = buttons[i].message
          iconListConfig[buttons[i].action].parentDisabled = buttons[i].parentDisabled
          iconList.push(iconListConfig[buttons[i].action])
        }
      }

      item.icons = iconList
    } else if (viewProps.hasIcon) {
      // 判断后端 tree节点的按钮
      item.icons = [
        {
          icon: 'el-icon-plus',
          type: 'add'
        },
        {
          icon: 'el-icon-edit',
          type: 'edit'
        },
        {
          icon: 'el-icon-delete',
          type: 'delete'
        }
      ]
    }
  })
  return treeData
}

const initTreeBtnHook = async (vm, treeData) => {
  for (const item of treeData?.data || []) {
    for (const icon of item.icons || []) {
      if (icon.type === 'add') {
        const canCreateRes = await Tech.callHook(vm, 'canCreate', item, {
          triggerType: 'treeNodeCreate'
        })
        icon.disabled = !canCreateRes
      } else if (icon.type === 'edit') {
        const canEditRes = await Tech.callHook(vm, 'canEdit', item, {
          triggerType: 'treeNodeEdit'
        })
        icon.disabled = !canEditRes
      } else if (icon.type === 'delete') {
        const canDeleteRes = await Tech.callHook(vm, 'canDelete', item, {
          triggerType: 'treeNodeDelete'
        })
        icon.disabled = !canDeleteRes
      }
    }
  }
  return treeData
}

export default { initTreeButtons, addAllNode, initTreeBtnHook }
