export default {
  type: 'dialog',
  id: 'dialog_meta_rest_pwd',
  width: '30%',
  title: Tech.$t('tenant.reset'),
  display: false,
  bind_on_opreates: (params) => {
    const { self: vm, value } = params
    if (value.type === 'cancel') {
      value.close()
    } else {
      vm.$select(`${vm.$ds.idPre}form_meta_rest_pwd`)
        .instance.submit()
        .then(async (d) => {
          if (d.password !== d.passwordA) {
            return window.ELEMENT.Message.error(
              Tech.$t('tenant.passwordInconformity')
            )
          }
          const dataParams = {
            // model: vm.$ds.rowData.model || userInfo.model,
            model: 'rbac_user',
            args: {
              ids: [vm.$ds.rowData.id],
              newPassword: window.Tech.utils.md5(d.password),
              useDisplayForModel: true
              // tenant: userInfo.tenant,
              // userType: userInfo.userType,
            },
            context: {
              lang: window.Tech?.LANG?.locale || 'zh_CN',
              uid: ''
            }
          }
          // console.log(JSON.stringify(dataParams),'params')
          let res = await params.self.request('form', dataParams)
          // console.log(' === 返回 res === ', res);
          // 重置不成功，没有data
          if (!res.data) return
          window.ELEMENT.Message.success(Tech.$t('tenant.success'))
          vm.data.display = false
        })
        .catch((err) => {
          window.ELEMENT.Message.error(Tech.$t('tenant.passwordReenter'))
        })
    }
  },
  dataSource: {
    form: {
      password: '',
      passwordA: ''
    }
  },
  items: [
    {
      type: 'form', // 使用表单
      id: 'form_meta_rest_pwd',
      formConfig: {
        inline: true,
        labelPosition: 'right'
      },
      created: async (vm) => {
        // 根据用户信息里是否包含pwd_expire_day，才调用获取密码规则接口以及相关交互
        const userInfo = window.tech.userInfo
        if (userInfo && userInfo.hasOwnProperty('pwd_expire_day')) {
          const dataParams = {
            // model: vm.$ds.rowData.model || userInfo.model,
            model: 'rbac_password_policy',
            service: 'getPasswordPolicy',
            args: {}
          }
          vm.request('passwordRule', dataParams).then((res) => {
            const dataObj = res.data
            vm.data.items[0].items[0].rules = [
              {
                required: true,
                message: Tech.$t('tenant.newPasswordEnter'),
                trigger: 'blur'
              },
              {
                pattern: dataObj.regex,
                message: Tech.$t('tenant.correctPasswordEnter'),
                trigger: 'blur'
              },
              {
                min: dataObj.min_length,
                max: 20,
                message: `${Tech.$t('tenant.length')} ${
                  dataObj.min_length
                } ${Tech.$t('tenant.up')}`,
                trigger: 'blur'
              }
            ]
            vm.data.items[1].items[0].rules = [
              {
                required: true,
                message: Tech.$t('tenant.newPasswordAgain'),
                trigger: 'blur'
              },
              {
                pattern: dataObj.regex,
                message: Tech.$t('tenant.correctPasswordEnter'),
                trigger: 'blur'
              },
              {
                min: dataObj.min_length,
                max: 20,
                message: `${Tech.$t('tenant.length')} ${
                  dataObj.min_length
                } ${Tech.$t('tenant.up')}`,
                trigger: 'blur'
              }
            ]
            vm.data.items[2].items[0].value = dataObj.description
          })
        }
      },
      items: [
        {
          type: 'row',
          id: 'row_meta_rest_pwd_np',
          className: 'rest_pwd_form_row',
          css: `.rest_pwd_form_row .el-form-item{display: flex;align-items: center;}
            .rest_pwd_form_row .el-form-item__content{flex: 1}`,
          items: [
            {
              type: 'input',
              id: 'input_meta_rest_pwd_np',
              text: Tech.$t('tenant.new'),
              name: 'password',
              showPassword: true,
              placeholder: Tech.$t('tenant.newPasswordEnter'),
              rules: [
                {
                  required: true,
                  message: Tech.$t('tenant.newPasswordEnter'),
                  trigger: 'blur'
                },
                {
                  min: 6,
                  max: 16,
                  message: Tech.$t('tenant.correctPasswordEnter'),
                  trigger: 'blur'
                }
              ]
            }
          ]
        },
        {
          type: 'row',
          id: 'row_meta_rest_pwd_npa',
          className: 'rest_pwd_form_row',
          items: [
            {
              type: 'input',
              id: 'input_meta_rest_pwd_npa',
              text: Tech.$t('tenant.comfirm'),
              name: 'passwordA',
              showPassword: true,
              placeholder: Tech.$t('tenant.newPasswordAgain'),
              rules: [
                {
                  required: true,
                  message: Tech.$t('tenant.newPasswordAgain'),
                  trigger: 'blur'
                },
                {
                  min: 6,
                  max: 16,
                  message: Tech.$t('tenant.passwordLenHint'),
                  trigger: 'blur'
                }
              ]
            }
          ]
        },
        {
          type: 'row',
          id: 'row_meta_rest_pwd_hint',
          className: 'rest_pwd_form_row',
          items: [
            {
              type: 'text',
              id: 'input_meta_rest_pwd_first_text',
              text: '',
              name: '',
              style: {
                fontSize: '12px',
                lineHeight: '16px',
                display: 'inline-block'
              },
              value: Tech.$t('tenant.passwordRule')
            }
          ]
        }
      ]
    }
  ],
  ds_config: {
    list: [
      {
        name: 'passwordRule', // 数据源标识，获取数据后将根据此名称存入dataSource.data1中
        type: 'meta',
        method: 'service',
        autoRequest: false,
        options: {}
      },
      {
        name: 'form', // 数据源标识，获取数据后将根据此名称存入dataSource.data1中
        type: 'meta', // 调用元模型引擎API获取数据
        autoRequest: false, // 在节点渲染后，是否自动触发请求，默认false
        // method: 'save',
        options: {
          params: {
            // 参考元模型api传参规范
            action: 'update',
            app: 'sie-iidp-iam',
            args: {
              ids: [],
              newPassword: '',
              useDisplayForModel: true
              // userType: JSON.parse(window.Tech.cookies ? (window.Tech.cookies.get('userInfo') || '{}') : '{}').userType,
            },
            context: {
              lang: 'zh_CN',
              uid: ''
            },
            // model: JSON.parse(window.Tech.cookies ? (window.Tech.cookies.get('userInfo') || '{}') : '{}').model,
            model: 'rbac_user',
            service: 'resetPassword',
            tag: 'master'
          }
        }
      }
    ]
  }
}
