// 依赖包引入
import { loadApps } from '../../importCommon/core.js'

import TechMetaPage from './index.vue'

TechMetaPage.install = (app) => {
  app.component(TechMetaPage.name, TechMetaPage)
}
TechMetaPage.loadApps = async (apps, useVue, localOptions = null) => {
  return await loadApps(apps, useVue, localOptions, TechMetaPage.methods.getParams())
}

// 从接口获取apps （弃用）
TechMetaPage.getApiApps = (useVue) => {
  let apps = {
    self: {},
    apps: {},
    appsDetail: {} // 存放apps的详细信息
  }
  // console.log(' === useVue === ', useVue.prototype);
  let hostApi = window.tech?.apiHost
  if (window.sessionStorage) {
    let tempApi = window.sessionStorage.getItem('appsTempApi')
    if (tempApi) {
      hostApi = tempApi
    } else {
      try {
        // 如果是开发启动 并且是 start:base 则次优先获取 tempApi
        // console.log(' == customProcess?.env == ', customProcess?.env)
        if (process?.env === 'development' && customProcess?.env === 'base') {
          let tempApi2 = window.sessionStorage.getItem('tempApi')
          if (tempApi2) {
            // console.log(' === tempApi2 == ', tempApi2)
            hostApi = tempApi2
          }
        }
      } catch (e) {}
    }
  }

  try {
    // 如果是开发启动 并且是 start:base 则配置默认frontHost
    if (process?.env === 'development' && customProcess?.env === 'base') {
      if (hostApi !== window.tech?.apiHost) {
        let curUrl = new URL(location.href)
        let topParams = new URLSearchParams(curUrl.search)
        let srcFrontHost = topParams.get('frontHost')
        if (!srcFrontHost) {
          let hostApiUrl = new URL(hostApi)
          let hostname = hostApiUrl.hostname
          let port = hostApiUrl.port
            ? hostApiUrl.port
            : hostApiUrl.protocol === 'https:'
            ? '443'
            : '80'
          let frontHostUrl = hostname + ':' + port + window?.tech?.routerBase
          if (frontHostUrl.lastIndexOf('/') === frontHostUrl.length - 1) {
            frontHostUrl = frontHostUrl.substring(0, frontHostUrl.length - 1)
          }
          // console.log(' === frontHostUrl == ', frontHostUrl)
          topParams.set('frontHost', frontHostUrl)
          curUrl.search = '?' + topParams.toString()
          history.pushState(null, null, curUrl.href)
        }
      }
    }
  } catch (e) {}

  // console.log(' ==== window.jianke.microData.routerBase == ', window.jianke.microData.routerBase);
  let host = window.tech?.routerBase || '/' // location.host; // useVue.prototype.$apiSevice.base;
  // if (location.pathname) {
  //   let arr = location.pathname.split('/');
  //   if (arr.length === 2 || arr.length >= 5) {
  //     host = host + '/' + arr[1];
  //   }
  // }

  let search = window.location.search.substr(1) || window.location.hash.split('?')[1]
  let name = 'frontHost' // 若有配置 frontHost url参数则优先去这个参数
  let reg = new RegExp('(^|&)' + name + '=([^&]*)(&|$)')
  if (search) {
    let r = search.match(reg)
    let frontHost = ''
    if (r != null) {
      frontHost = decodeURIComponent(r[2])
    }
    if (frontHost) {
      host = frontHost
      host = '//' + host + '/'
    }
  }
  // console.log(' ==== host === ', host);

  return new Promise((resolve, reject) => {
    fetch(hostApi + '/rpc/open/service', {
      method: 'POST',
      headers: {
        'Content-type': 'application/json; charset=UTF-8'
      },
      body: JSON.stringify({
        id: 'guid',
        jsonrpc: '2.0',
        method: 'service',
        params: {
          args: {},
          service: 'prepareListApps',
          context: {
            uid: '',
            lang: window.Tech?.LANG?.locale || 'zh_CN'
          },
          model: 'meta_app',
          app: 'sie-iidp-app-store',
          tag: 'master'
        }
      })
    })
      .then((response) => {
        return response.json()
      })
      .then((json) => {
        let env = window?.tech?.env || 'master' // TODO 获取环境变量默认master

        if (window.sessionStorage) {
          let mockApps = window.sessionStorage.getItem('mockApps') // 可手动配置 sessionStorage mock数据方便调试
          if (mockApps) {
            json.result.data = JSON.parse(mockApps)
          }
        }

        // test mock
        /*
      json.result.data = [
        {
            "view_file": "/umdComps/tech-iiot/config/app.json?ts=1686190064000",
            "dependency": "iiot_project",
            "comp_name": "tech-iiot",
            "name": "iiot_thing",
            "id": "02vad5xvvn11c",
            "tag": "master",
            "display_name": "建模管理",
            "update_date": "2023-06-08T02:07:44.000+00:00",
            "view_file_json": {
              "name": "main",
              "assets": {
                "js": [
                  "iiot.umd.min.js?t=1686043438965"
                ],
                "css": [
                  "style.css?t=1686043438965"
                ]
              },
              "global": {
                "ws": "/ws"
              },
              "effectPageIds": {
                "include": ['page_meta_index'], // 包含的页面id page_meta_login page_meta_index
                // "exclude": ['page_meta_index', 'page_meta_login'] // 不包含的页面id 同名以exclue优先
              },
              "effectPaths": {
                "include": ['/iiot/iiot_thing_menu/iiot_thing_model_menu'], // 包含的path路径
                // "exclude": ['iiot/iiot_thing_menu/iiot_thing_model_menu'] // 不包含的path路径
              }
            }
        },
        // {
        //     "view_file": "/umdComps/tech-iiotPolice/config/app.json?ts=1686043512000",
        //     "dependency": "iiot_access",
        //     "comp_name": "tech-iiotPolice",
        //     "name": "iiot_alarm",
        //     "id": "02vad6szimkn4",
        //     "tag": "master",
        //     "display_name": "报警管理",
        //     "update_date": "2023-06-06T09:25:12.000+00:00"
        // },
      ];
      console.log(' === json ==== ', json);
      */

        // resolve(json);
        if (json?.result?.data) {
          let list = json.result.data
          list.map((item) => {
            apps.apps[item.name] = {}
            apps.apps[item.name][env] = {}
            if (item.view_file.indexOf('http') !== 0 && item.view_file.indexOf('//') !== 0) {
              if (item.view_file.indexOf('/') === 0) {
                item.view_file = item.view_file.substring(1, item.view_file.length)
              }
              // console.log(' ==== host === ', host);
              // host = '/snest/';
              item.view_file = host + item.view_file
            }

            // 若有本扩展工程apps.json里面取到的 tech.appsDetail.[app].[env].[comp].view_file_json
            // 则进行浅度合并 view_file_json
            try {
              let gloDetail =
                window?.tech?.appsDetail?.[item.name]?.[env]?.[item.comp_name]?.view_file_json
              if (gloDetail && item?.view_file_json) {
                item.view_file_json = {
                  ...item.view_file_json,
                  ...gloDetail,
                  endApp: item.name
                }
              }
            } catch (e) {
              console.log(' appsApi res merge apps.json error ', item, e)
            }

            apps.apps[item.name][env][item.comp_name] = item.view_file

            // 存放apps详细信息
            apps.appsDetail[item.name] = {}
            apps.appsDetail[item.name][env] = {}
            apps.appsDetail[item.name][env][item.comp_name] = item
          })
        }
        // console.log(' ==== apps === ', JSON.stringify(apps));
        resolve(apps)
      })
      .catch((err) => {
        reject(err)
      })
  })
}

export default TechMetaPage
