// 租户/用户角色——数据权限——行权限，生成规则权限
const generateId = (() => {
  let id = 1
  return (preName) => {
    const _id = preName + id
    id = id + 1
    return _id
  }
})()
export const generateRuleForm = (preName) => {
  const id = generateId(preName)
  const data_permission_id = preName + 'data_permission'
  const rules_box_id = preName + 'rules_box'
  return {
    type: 'container',
    style: {
      padding: '16px',
      paddingBottom: '0px',
      borderBottom: '2px dotted #cccccc'
    },
    id: `rules_box_items2_${id}`,
    dataSource: {
      selectPermissRules: null,
      conditional: null,
      conditionalData: [],
      isExpend: true
    },
    items: [
      {
        type: 'container',
        style: {
          display: 'flex',
          alignItems: 'center'
        },
        css: `
        #rules_box_items2_del_btn_${id} .el-icon-delete {
          font-weight: bold;
        }
        
        `,
        items: [
          // 展开按钮
          {
            type: 'button',
            value: '',
            style: {
              margin: '4px',
              color: 'var(--button-primary-bg, #C4C4C4)',
              fontSize: '15px'
            },
            options: {
              type: 'text',
              size: 'small',
              bind_icon: "${$ds.isExpend ? 'el-icon-caret-bottom' : 'el-icon-caret-right'}"
            },
            // 绑定按钮的点击事件
            bind_on_click: (params) => {
              params.self.$ds.isExpend = !params.self.$ds.isExpend
            }
          },
          {
            type: 'text',
            style: {
              width: '120px'
            },
            value: Tech.$t('tenant.rule')
          },
          {
            type: 'select',
            name: 'selectPermissRules',
            // bind_disabled: "${$ds.clickType === 'preview'}",
            text: '',
            style: {
              width: '400px'
            },
            placeholder: Tech.$t('tenant.sePlaceholder'),
            bind_options: '$ds.permissRules',
            model: {
              bind_selectPermissRules: '$ds.selectPermissRules'
            },
            multiple: true,
            clearable: true,
            // 绑定change事件
            bind_on_changeHandler: (data) => {
              data.self.$ds.selectPermissRules = data.value
            }
          },
          {
            type: 'button',
            id: `rules_box_items2_del_btn_${id}`,

            value: '',
            style: {
              color: 'var(--sidebar-bg, #ad053d)',
              fontSize: '20px',
              fontWeight: 'bold',
              marginLeft: '10px'
              // bind_display: "${($ds.clickType === 'preview') ? 'none' : 'block'}"
            },
            options: {
              type: 'text',
              size: 'small',
              icon: 'el-icon-delete'
            },
            // 绑定按钮的点击事件
            bind_on_click: (params) => {
              console.log(' === params == ', params)
              const box = params.self.$select(rules_box_id)
              const delIndex = box.data.items.findIndex(
                (item) => item.id === params.self.data.id.replace('del_btn_', '')
              )
              box.data.items.splice(delIndex, 1)
              // 拿到更新前的conditionData
              // 拿到ids
              const updateData = box.data.items.map((item) => {
                const id = item.id.replace('del_btn', 'form')
                const vm = params.self.$select(id)
                return {
                  id: item.id.replace('del_btn', 'form'),
                  conditionalData: vm.$ds.conditional
                }
              })
              // 拿到$ds
              // 更新后赋值
              setTimeout(() => {
                updateData?.forEach((data) => {
                  const vm = params.self.$select(data.id)
                  vm.$ds.conditionalData = data.conditionalData
                })
              }, 100)
            }
          }
        ]
      },
      {
        type: 'form',
        id: `rules_box_items2_form_${id}`,
        style: {
          minWidth: '600px',
          padding: '0 20px',
          bind_display: "${$ds.isExpend ? 'block' : 'none'}"
        },
        formConfig: {
          minWidth: 350,
          labelPosition: 'right',
          labelWidth: '0px'
        },
        commands: {
          querySelection: async (field, model, filterOp) => {
            let res = await window.Tech.httpMeta({
              data: {
                // 参考元模型后端的传参规范
                params: {
                  args: {
                    // 'property' : dataObj.field,
                    // 'authId' : treeNode.$ds.authId
                    field,
                    model,
                    filterOp,
                    filter: [],
                    useDisplayForModel: true,
                    limit: 21,
                    offset: 0,
                    keyword: ''
                  },
                  app: 'sie-iidp-iam',
                  service: 'querySelection',
                  context: {
                    uid: '',
                    lang: window.Tech?.LANG?.locale || 'zh_CN'
                  },
                  model: 'tenant_data_auth',
                  tag: 'master'
                }
              }
            })
            return res?.data
          }
        },
        items: [
          {
            type: 'conditional-tree',
            name: 'conditional',
            bind_conditionalData: '$ds.conditionalData',
            id: `row_conditional_${id}`,
            bind_on_onChangeVal: ({ self, value } = data) => {
              self.$ds.conditional = self.instance.getResult().resultArr
            },
            items: [
              {
                type: 'lookup',
                span: 6,
                text: '',
                name: 'display_name1',
                placeholder: Tech.$t('tenant.pleaseSelect'),
                // bind_disabled: "${$ds.clickType === 'preview'}",
                multiple: false,
                rules: [{ required: false }],
                lookupConfig: {
                  getData: async (dataSource = {}, params, customFilter = [], f, config, scope) => {
                    let dataObj = f.values
                    const path = config.dataPath.split('.')
                    path.pop()
                    path.map((item) => {
                      dataObj = Array.isArray(dataObj) ? dataObj[parseInt(item)] : dataObj[item]
                    })

                    // 数据域中保存列表
                    let res = await window.Tech.httpMeta({
                      data: {
                        // 参考元模型后端的传参规范
                        params: {
                          app: 'sie-iidp-iam',
                          model: 'tenant_data_auth',
                          tag: 'master',
                          service: 'getPropertiesByModel',
                          args: {
                            app: 'sie-iidp-iam',
                            tag: 'master',
                            modelName: f.vm.$ds.model,
                            limit: params.paging.end - params.paging.start + 2, // 21
                            offset: params.paging.start - 1,
                            keyword: params?.search || '' // 添加搜索参数
                          }
                        }
                      }
                    })

                    const tmpOptions = res.data.map((item) => {
                      // 拼接下拉数据，需要加上value，label属性
                      return {
                        ...item,
                        value: item.name,
                        label: item.displayName
                      }
                    })

                    dataObj.display_name1_options = tmpOptions
                    if (scope.model[scope.name]) {
                      scope.$emit('change', scope.model[scope.name])
                    }
                    return { items: tmpOptions }
                  },
                  paging: {}
                },
                onChange: (form, curVal, config) => {
                  const treeNode = tech_app.page.getNode(`row_conditional_${id}`)
                  const nodeConfigs = treeNode.instance.findConfig(config.config.dataPath)
                  // 获取上一级的数据路径
                  const parentDataPath = config.config.dataPath.replace(/(\.\w+)$/, '')
                  // 第三个输入框
                  const inputConfig3 = nodeConfigs[parentDataPath + '.display_name3']
                  // 第二个输入框
                  const inputConfig2 = nodeConfigs[parentDataPath + '.display_name2']
                  let dataObj = form.values
                  const path = parentDataPath.split('.')
                  path.map((item) => {
                    dataObj = Array.isArray(dataObj) ? dataObj[parseInt(item)] : dataObj[item]
                  })

                  // 数据域中拿到列表
                  // 匹配dataType
                  if (curVal) {
                    const options =
                      JSON.parse(sessionStorage.getItem('display_name1__values')) ||
                      dataObj.display_name1_options ||
                      []
                    dataObj.display_name1_options = options
                    const dataType = options.find((item) => item.name === curVal)?.dataType
                    // 清除2 和 3
                    inputConfig2.display = true
                    inputConfig3.display = true
                    const map = {
                      ManyToOne: 'lookup',
                      Selection: 'lookup',
                      String: 'lookup',
                      Text: 'lookup',
                      Integer: 'lookup',
                      Long: 'lookup',
                      Date: 'datepicker',
                      DateTime: 'datepicker'
                    }
                    if (map[dataType]) {
                      inputConfig3.type = map[dataType]
                      if (map[dataType] === 'input') {
                        inputConfig3.placeholder = Tech.$t('tenant.pleaseEnter')
                      } else {
                        inputConfig3.placeholder = Tech.$t('tenant.pleaseSelect')
                      }
                      if (dataType === 'Date') {
                        inputConfig3.pickerType = 'date'
                        inputConfig3.format = 'yyyy-MM-dd'
                      } else if (dataType === 'DateTime') {
                        inputConfig3.pickerType = 'datetime'
                        inputConfig3.format = 'yyyy-MM-dd HH:mm:ss'
                      }
                    } else {
                      inputConfig3.placeholder = Tech.$t('tenant.pleaseEnter')
                      inputConfig3.type = 'lookup'
                    }
                  } else {
                    inputConfig2.display = false
                    inputConfig3.display = false
                    dataObj.display_name2 = null
                    dataObj.display_name3 = null
                  }
                }
              },
              {
                span: 6,
                type: 'lookup',
                // bind_disabled: "${$ds.clickType === 'preview'}",
                text: '',
                display: false,
                name: 'display_name2',
                placeholder: Tech.$t('tenant.sPlaceholder'),
                rules: [{ required: false }],
                lookupConfig: {
                  getData: async (dataSource = {}, params, customFilter = [], f, config, scope) => {
                    const data_permission_node = tech_app.page.getNode(data_permission_id)
                    let dataObj = f.values
                    const path = config.dataPath.split('.')
                    path.pop()
                    path.map((item) => {
                      dataObj = Array.isArray(dataObj) ? dataObj[parseInt(item)] : dataObj[item]
                    })
                    const dataType = dataObj.display_name1_options.find(
                      (item) => item.name === dataObj.display_name1
                    )?.dataType
                    let res = await window.Tech.httpMeta({
                      data: {
                        params: {
                          service: 'listDataAuthDict',
                          model: 'tenant_data_auth',
                          args: {
                            app: 'sie-iidp-iam',
                            property: dataObj.display_name1,
                            modelName: f.vm.$ds.model,
                            dataType: dataType,
                            limit: params.paging.end - params.paging.start + 2, // 21
                            offset: params.paging.start - 1,
                            keyword: params?.search || '' // 添加搜索参数
                          }
                        }
                      }
                    })

                    const tmpOptions = res.data.map((item) => {
                      return {
                        ...item
                      }
                    })
                    if (scope.model[scope.name]) {
                      scope.$emit('change', scope.model[scope.name])
                    }
                    return { items: tmpOptions }
                  },
                  paging: {}
                },
                onChange: async (form, curVal, config) => {
                  if (curVal === config.model.pre_display_name2) {
                    return
                  }
                  const modelName = config.model.display_name1_options.find(
                    (item) => item.name === config.model.display_name1
                  )?.modelName
                  const { display_name3_options } = config.model
                  const data = await form.vm.$cmd.querySelection(
                    config.model.display_name1,
                    modelName,
                    curVal
                  )
                  if (
                    display_name3_options?.length &&
                    !data?.find((i) => i.value === config.model.display_name3)
                  ) {
                    config.model.display_name3 = null
                  }
                  config.model.pre_display_name2 = curVal
                }
              },
              {
                span: 10,
                type: 'lookup',
                // bind_disabled: "${$ds.clickType === 'preview'}",
                text: '',
                name: 'display_name3',
                display: false,
                placeholder: Tech.$t('tenant.pleaseSelect'),
                allowCreate: true,
                rules: [{ required: false }],
                lookupConfig: {
                  getData: async (dataSource = {}, params, customFilter = [], f, config) => {
                    let dataObj = f.values
                    const path = config.dataPath.split('.')
                    path.pop()
                    path.map((item) => {
                      dataObj = Array.isArray(dataObj) ? dataObj[parseInt(item)] : dataObj[item]
                    })
                    const modelName = dataObj.display_name1_options.find(
                      (item) => item.name === dataObj.display_name1
                    )?.modelName
                    let res = await window.Tech.httpMeta({
                      data: {
                        // 参考元模型后端的传参规范
                        params: {
                          args: {
                            filter: [],
                            useDisplayForModel: true,
                            limit: 21,
                            offset: 0,
                            field: dataObj.display_name1,
                            filterOp: dataObj.display_name2,
                            model: modelName,
                            keyword: ''
                          },
                          app: 'sie-iidp-iam',
                          service: 'querySelection',
                          model: 'tenant_data_auth',
                          tag: 'master'
                        }
                      }
                    })

                    const tmpOptions = res.data.map((item) => {
                      return {
                        ...item
                      }
                    })
                    // 不设置定时器，偶尔会导致手动创建的节点数据没有回显
                    setTimeout(() => {
                      dataObj.display_name3_options = tmpOptions
                    }, 200)
                    return { items: tmpOptions }
                  },
                  paging: {}
                }
              }
            ]
          }
        ]
      }
    ]
  }
}
