// 构造view方法
export const makeMainView = async (vm, label, view, idPre) => {
  let page = [window.Tech._cloneDeep(view)]

  // 点击菜单切换中间views的钩子
  // console.log(' **** idPre + vm.data.id === ', idPre + vm.data.id);
  let dealedObj = await vm.app.useHook(vm, 'changeViews', idPre + vm.data.id, {
    views: page
  })
  page = dealedObj.options.views

  window.Tech.utils.recursive(page, {
    props: { children: 'items' },
    chengItem: (item, parent) => {
      item.idPre = idPre
      if (item.id) {
        item.id = item.idPre + item.id
      }
      if (!parent) {
        item.name = label
      }
    }
  })
  return page[0]
}

// 为视图添加idPre
export const addIdPre = async (view, idPre) => {
  if (Object.prototype.toString.call(view) === '[object Array]') {
    window.Tech.utils.recursive(view, {
      props: { children: 'items' },
      chengItem: (item, parent) => {
        if (item.id) {
          item.id = idPre + item.id
        }
      }
    })
  } else {
    if (view.id) {
      view.id = idPre + view.id
    }
    if (view.items) {
      window.Tech.utils.recursive(view.items, {
        props: { children: 'items' },
        chengItem: (item, parent) => {
          if (item.id) {
            item.id = idPre + item.id
          }
        }
      })
    }
  }
}

// 获取元模型模板应用视图
export const getView = (vm, type, idPre = '') => {
  let view = null
  if (vm) {
    if (vm?.$cmd?.meta?.views?.[type]) {
      view = window.Tech._cloneDeep(vm.$cmd.meta.views[type])
      if (idPre && vm?.$cmd?.meta?.addIdPre) {
        vm.$cmd.meta.addIdPre(view, idPre)
      }
      // 在视图中添加权限id,处理loadview接口返回的权限
      addAuthId({ vm, view, type, idPre })
    }
  }
  return view
}

// 在视图中添加权限id,处理loadview接口返回的权限
