// 页面跳转，可携带参数
export const goTo = async (vm, jumpObj, otherArgs = { removeSelf: false, removeTarget: true }) => {
  // iframe模型外层情况 且 需要跳详情页 清理缓存tab
  if (tech?.TABIFRAME && !tech?.TABIFRAME?.inner && jumpObj?.query?.clickType) {
    try {
      let tabsNode = vm.$select('tabs_meta_main_content_labels')
      if (tabsNode) {
        let lastPos = tabsNode.data.items.length - 1
        let last = tabsNode.data.items[lastPos]
        if (last && last?.data?.isCacheShowTab === false) {
          tabsNode.data.items.splice(lastPos, 1)
        }
      }
    } catch (e) {
      console.log(' == clear iframe detail tab error == ', e)
    }
  }

  // iframe模式 内部情况 通过协议 传递回父级
  if (tech?.TABIFRAME?.inner) {
    setTimeout(() => {
      window.parent.postMessage(
        {
          type: 'TABIFRAME_FN',
          fn:
            '()=>{ let v = tech_app.page.getNode(tech_app.page.data.id); v.$cmd.meta.goTo(v, ' +
            JSON.stringify(jumpObj) +
            ' , ' +
            JSON.stringify(otherArgs) +
            '); }'
        },
        window.tech.TABIFRAME.host
      )
    })
  } else if (window?.$wujie?.microApp) {
    // 微应用自身嵌套情况
    $wujie.microApp.goto(jumpObj, otherArgs)
  } else {
    let tabsVm = vm.$select('tabs_meta_main_content_labels')
    if (tabsVm._gotoing) {
      return
    }
    tabsVm._gotoing = true
    // 设置默认值
    const { removeSelf = false, removeTarget = true } = otherArgs || {}
    let { path, appName, query } = jumpObj
    const menu = vm.$select('menu_meta_siderbar')
    await new Promise((resolve) => setTimeout(resolve, 50))
    // setTimeout(() => {
    const selfPath = window.location.pathname // 当前页面path
    const menuList = menu.$ds.appsMenus //所有菜单列表
    let pathArr = path.split('/')
    if (pathArr.length == 1) {
      let pathName = pathArr[0]
      // 只配置了菜单名，没有具体路径，匹配拼接当前菜单的完整路径
      // appName可不配置，若配置了需和当前菜单的app一致
      // params = {
      //   path: 'mbm_aps_mrp_item_replace_menu',
      //   appName: "mbm-center-aps-mrp"
      // }
      let menuObj = null
      let result = []
      for (let i = 0; i < menuList.length; i++) {
        if (pathName === menuList[i].name) {
          if ((appName && appName == menuList[i].app) || !appName) {
            menuObj = menuList[i]
            result.push(menuList[i])
            break
          }
        }
      }
      function findParent(parent_ids) {
        for (let i = 0; i < menuList.length; i++) {
          if (menuList[i].id === parent_ids) {
            result.push(menuList[i])
            findParent(menuList[i].parent_ids)
            break
          }
        }
        return result
      }
      const menuPathArr = findParent(menuObj?.parent_ids)
      path = menuPathArr
        .reverse()
        .map((item) => {
          return item.name
        })
        .join('/')
      if (path) {
        path = '/' + path
      }
      console.log(' ==== path === ', path)
    }
    const app = menuList?.find((item) => {
      return item.name == pathArr[pathArr.length - 1]
      // return path.endsWith(item.name)
    })
    const selfApp = menuList.find((item) => {
      return selfPath.endsWith(item.name)
    })
    removeSelf &&
      vm
        .$select('tabs_meta_main_content_labels')
        .instance.tabRemove(selfApp.name + '_container_main')
    // const jumpVm = vm.$select(app.name + '_container_main')
    const jumpVm = vm.$select('tabs_meta_main_content_labels').data.items.find((item) => {
      if (item?.idPre) {
        // 若有前缀字段优先匹配前缀
        return item?.idPre === app?.name + '_'
      } else {
        return item.id.indexOf(app?.name) > -1
      }
    })
    // 从其他页面跳转主表单页（主表单页已存在）
    if (jumpVm && removeTarget) {
      vm.$select('tabs_meta_main_content_labels').instance.tabRemove(jumpVm.id)
      await new Promise((resolve) => setTimeout(resolve, 300))
    }
    // 表格搜索参数处理
    if (query?.searchParams) {
      query.searchParams = JSON.stringify(query.searchParams)
    }

    // 工作流参数处理
    if (query?.options) {
      query.options = JSON.stringify(query.options)
    }

    await new Promise((resolve) => setTimeout(resolve, 100))
    // setTimeout(() => {
    tabsVm.data.allowRunRoute = true
    menu.instance.$router
      .push({
        path,
        query
      })
      .catch((e) => {
        // console.log(' === goto router error ', e)
      })
    if (tabsVm.data._allowRunRouteTImer) {
      clearTimeout(tabsVm.data._allowRunRouteTImer)
      tabsVm.data._allowRunRouteTImer = null
    }
    tabsVm.data._allowRunRouteTImer = setTimeout(() => {
      tabsVm.data.allowRunRoute = undefined
      tabsVm._gotoing = false
    }, 2000)
    await new Promise((resolve) => setTimeout(resolve, 100))
    tabsVm._gotoing = false
    // })
    // }, 200)
  }
}

// 导出
export const exportFn = async (vm, args) => {
  // console.log(vm.data);
  let loadingInstance
  if (vm.data.showPopLoading) {
    loadingInstance = window.ELEMENT.Loading.service()
  }
  // 获取_metaParamsApp参数
  let appendAppParams = { app: 'base' }
  if (vm?.$ds?._metaParamsApp) {
    appendAppParams = { app: vm.$ds._metaParamsApp }
  }
  const params = {
    args: args,
    service: vm.data.btnConfig.service,
    model: vm.data.btnConfig.model,
    ...appendAppParams
  }

  // 追加拼接菜单filter 和 app参数
  window.Tech.apiAddNeedParams(vm, params)

  await window.Tech.metaApi
    .metaServe(params, { base: vm.tech.apiHost }, 'service', true, true, '', {
      responseType: 'arraybuffer',
      returnHeaders: true
    })
    .then((data) => {
      const fileName = data.headers['download-filename'] || vm.data?.btnConfig?.fileName
      // let curTime = window.Tech.utils.dateFormat('YYYY-MM-DD', new Date());
      const link = document.createElement('a')
      let blob = new Blob([data.data], { type: 'application/vnd.ms-excel' }) // 类型excel
      link.style.display = 'none'
      link.href = URL.createObjectURL(blob)
      link.setAttribute('download', decodeURI(fileName))
      document.body.appendChild(link)
      link.click()
      document.body.removeChild(link)
      // 导出后的回调
      // reqAfterFn: 视图中导出按钮配置的导出后的回调函数
      if (vm.data?.btnConfig.reqAfterFn) {
        let fn = null
        if (Object.prototype.toString.call(vm.data.btnConfig.reqAfterFn) === '[object String]') {
          try {
            fn = new Function('return ' + vm.data.btnConfig.reqAfterFn)()
          } catch (error) {
            console.log(' === error == ', error)
          }
        }
        fn(vm)
      }
      if (vm.data.showPopLoading) {
        setTimeout(() => {
          loadingInstance.close()
        }, 300)
      }
    })
    .catch((err) => {
      window.ELEMENT.Message.error(Tech.$t('gridView.exportFail'))
      if (vm.data.showPopLoading) {
        setTimeout(() => {
          loadingInstance.close()
        }, 300)
      }
    })
}

// 追加拼接菜单filter 和 app参数
export const apiAddNeedParams = (vm, params) => {
  let node = vm

  if (params.app === undefined) {
    if (params.service === 'loadview' || params.service === 'loadView') {
      let appParams = 'base'
      let curVm = node
      // eslint-disable-next-line @typescript-eslint/prefer-optional-chain
      if (curVm && curVm.$ds && curVm.$ds._metaParamsApp) {
        appParams = curVm.$ds._metaParamsApp
      }
      if (!params.args) {
        params.args = {}
      }
      params.args.app = appParams
      params.app = 'base'
    } else {
      let appendAppParams = { app: 'base' }
      let curVm = node
      // eslint-disable-next-line @typescript-eslint/prefer-optional-chain
      if (curVm && curVm.$ds && curVm.$ds._metaParamsApp) {
        appendAppParams = { app: curVm.$ds._metaParamsApp }
      }
      params = {
        ...params,
        ...appendAppParams
      }
    }
  }

  try {
    let useMenuFilter = false // 是否使用菜单过滤条件 匹配菜单json配置字段 filter: "[[\"name\",\"=\",\"aaa\"],[\"name1\",\"=\",\"aaa1\"]]"
    let isMenuSameModel = false // 是否跟菜单同一个模型名
    if (
      node?.$ds?.menuConfig?.model === params?.model &&
      params?.model &&
      node?.$ds?.menuConfig?.filter
    ) {
      if (Object.prototype.toString.call(node.$ds.menuConfig.filter) === '[object String]') {
        try {
          let changedFilter = JSON.parse(node.$ds.menuConfig.filter)
          if (Object.prototype.toString.call(changedFilter) === '[object Array]') {
            node.$ds.menuConfig.filter = changedFilter
          } else if (Object.prototype.toString.call(changedFilter) === '[object Object]') {
            node.$ds.menuConfig.filter = changedFilter.filter || []
            node.$ds.menuConfig.useFilter = changedFilter.config
          }
        } catch (e) {}
      }
      isMenuSameModel = true
      useMenuFilter = true
      if (params?.service === 'lookup') {
        useMenuFilter = false
      }
    }

    // 匹配特定菜单过滤条件 useFilter: {"filedA":{"lookup":[["a","=","1"]]}} 或 useFilter: {"filedA":{"lookup":false}} _self为全局的配置
    let useFilterArr = null
    let useFilterObj =
      node?.$ds?.menuConfig?.useFilter?.[params?.args?.field || '_self']?.[params?.service]
    // console.log(' === useFilterObj == ', useFilterObj);
    if (isMenuSameModel && useFilterObj !== undefined) {
      if (Object.prototype.toString.call(useFilterObj) === '[object String]') {
        try {
          useFilterObj = JSON.parse(useFilterObj)
        } catch (e) {}
      }
      if (Object.prototype.toString.call(useFilterObj) === '[object Array]') {
        useFilterArr = useFilterObj
        useMenuFilter = true
      } else {
        useMenuFilter = useFilterObj // 方便布尔值直接控制是否处理
      }
    }

    if (useMenuFilter) {
      // 判断入参model跟菜单配置同一个model 才走菜单过滤条件逻辑
      // console.log(' === to add filter ');
      let toAddFilter = useFilterArr || node?.$ds?.menuConfig?.filter
      if (toAddFilter && node?.$cmd?.meta?.addSearch) {
        if (Object.prototype.toString.call(toAddFilter) === '[object Array]') {
          if (!params.args) {
            params.args = {}
          }
          if (!params.args.filter) {
            params.args.filter = []
          }
          params.args.filter = node.$cmd.meta.addSearch(params.args.filter, toAddFilter)
        }
      }
    }
  } catch (e) {
    console.log('=== tbase ultis menuFilter error ==', e)
  }
}
// 只有在openview可以使用
export const formatApipParams = ({ formatData, vm }) => {
  return new Promise((resolve, reject) => {
    const tableDetailNode = vm.$select(vm.$ds.idPre + 'table_detail') // 主表单
    const tableNode = vm.$select(vm.$ds.idPre + 'table_main_wrap') // 当前table
    const subTableNode = vm.$select(vm.$ds.idPreTab + 'table_main_wrap') // 子表table
    const mainTableNode = vm.$select(vm.$ds.originIdPre + 'table_main_table') // 主表table
    const mainTabTableNode = vm.$select(vm.$ds.originIdPreTab + 'table_main_table')

    // $table的原始匹配数据
    const transformTableData = {
      mainRow: mainTableNode?.$ds?.mainTableRowData || {},
      mainCheckIdList: mainTableNode?.$ds?.checkedDataIds || [],
      mainSubRow: mainTabTableNode?.$ds?.mainTableRowData || {},
      mainSubCheckIdList: mainTabTableNode?.$ds?.checkedDataIds || [],
      row: tableDetailNode?.$ds?.mainTableRowData || {},
      checkIdList: tableNode?.$ds?.checkedDataIds || [],
      subRow: subTableNode?.$ds?.mainTableRowData || {},
      subCheckIdList: subTableNode?.$ds?.checkedDataIds || []
    }
    // $tree的原始匹配数据
    const treeNode = vm.$select(`${vm.$ds.idPre}tree_main_wrap`)
    const mainTreeNode = vm.$select(vm.$ds.originIdPre + 'tree_main_wrap')
    const transformTreeData = {
      tree: treeNode?.$ds?.currentData || {},
      mainTree: mainTreeNode?.$ds?.currentData || {}
    }

    // $form的原始匹配数据
    const formNode = vm.$select(vm.$ds.idPre + 'form_main_detail_top_common') // 当前form
    const mainFormNode = vm.$select(vm.$ds.originIdPre + 'form_main_detail_top_common') // 主表form
    const transformFormData = {
      curForm: formNode?.$ds.form || {},
      mainForm: mainFormNode?.$ds.form || {}
    }
    // $search的
    const searchNode = vm.$select(vm.$ds.idPre + 'form_main_table_search_common') // 当前search
    const mainSearchNode = vm.$select(vm.$ds.originIdPre + 'form_main_table_search_common') // 主表search
    const subSearchNode = vm.$select(vm.$ds.originIdPreTab + 'form_main_table_search_common') // 子表search
    const transformSearchData = {
      curSearch: searchNode?.$ds.form || {},
      mainSearch: mainSearchNode?.$ds.form || {},
      subSearch: subSearchNode?.$ds.form || {}
    }

    let str = JSON.stringify(formatData)
    // 替换$table
    str = vm.$cmd.matchStr(str, transformTableData, /\$table(\.?[a-zA-Z\w]*)*/g)
    // 替换$tree
    str = vm.$cmd.matchStr(str, transformTreeData, /\$tree(\.?[a-zA-Z\w]*)*/g)
    // 替换$form
    str = vm.$cmd.matchStr(str, transformFormData, /\$form(\.?[a-zA-Z\w]*)*/g)
    // 替换$search
    str = vm.$cmd.matchStr(str, transformSearchData, /\$search(\.?[a-zA-Z\w]*)*/g)
    // 转换当前datasource
    // if (formNode) {
    //   str = vm.$cmd.matchStr(str, formNode.$ds.form, /\$form(\.?[a-zA-Z\w]*)*/g)
    // }
    resolve(JSON.parse(str))
  })
}

// openview的api配置处理
export const openViewApi = async (
  { apiConfig, vm, dsConfigName, originParams = {} } = data,
  options = {}
) => {
  let res = {}
  if (apiConfig) {
    // 处理请求前后的方法字段
    const reqFn = async (fnConfig, vm, mergeData) => {
      let tempData = {}
      if (Object.prototype.toString.call(fnConfig) === '[object String]') {
        try {
          fnConfig = new Function('return ' + fnConfig)()
        } catch (error) {
          console.log(' === openView Api reqPrep error == ', error)
        }
      }
      let copyData = window.tech_app.utils._cloneDeep(mergeData)
      if (vm.$cmd.isAsync(fnConfig)) {
        tempData = await fnConfig(vm, copyData)
      } else {
        tempData = fnConfig(vm, copyData)
      }
      return tempData
    }
    const tableSearch = vm.$select(vm.$cmd.getIdPre(vm) + 'form_main_table_search')
    let otherArgs = {}
    if (tableSearch) {
      const commonForm = vm.$select(vm.$cmd.getIdPre(vm) + 'form_main_table_search_common')
      const dropdownForm = vm.$select(vm.$cmd.getIdPre(vm) + 'form_main_table_search_dropdown')
      let commonFormItems = tableSearch.$cmd.getFormItems(commonForm)
      let dropdownFormItems = tableSearch.$cmd.getFormItems(dropdownForm)
      let totalItem = [...commonFormItems, ...dropdownFormItems]
      // 搜索字段分割时，是多个重复字段名的，需增加配置，addSearch时不做去重
      totalItem.forEach((item) => {
        if (item.splitSymbol) {
          otherArgs['splitSymbol'] = item.splitSymbol
        }
      })
    }

    let searchParam = window.tech_app.utils._cloneDeep(apiConfig?.params) || {}
    let table_detail = vm.$select(vm.$ds.idPre + 'table_detail')
    let isSingleFormView = table_detail?.$ds?.isSingleFormView ?? false // 单独表单情况 不拼接filter
    if (searchParam?.args?.filter && originParams?.args?.filter && !isSingleFormView) {
      searchParam.args.filter = vm.$cmd.meta.addSearch(
        originParams.args.filter,
        searchParam.args.filter
      )
    }
    searchParam = window.tech_app.utils.deepMerge(originParams, searchParam) // 深度合并 api.form.search.params的优先级最高
    // reqPrep 请求前
    if (apiConfig?.reqPrep) {
      const reqParams = await reqFn(apiConfig.reqPrep, vm, searchParam)
      if (reqParams?.args?.filter && searchParam?.args?.filter && !isSingleFormView) {
        reqParams.args.filter = vm.$cmd.meta.addSearch(
          searchParam.args.filter,
          reqParams.args.filter,
          '&',
          otherArgs
        )
      }
      searchParam = window.tech_app.utils.deepMerge(searchParam, reqParams) // 深度合并
    }
    //正常请求
    // 解析params
    searchParam = await formatApipParams({ formatData: searchParam, vm })
    if (options?.paramsCb) {
      options.paramsCb(searchParam)
    }
    if (searchParam?.args?.limit) {
      searchParam.args.limit = vm.$ds.paging.pageSize + 1
    }
    res = await vm.request(dsConfigName, searchParam)
    // 如果配置了初始数据转换，将表格数据进行转换后再展示
    // const tableView = vm.$ds.tableView
    // const gridGroupConfig = tableView?.data?.views?.grid?.body?.gridGroupConfig
    // if (
    //   dsConfigName === 'tableData' &&
    //   res?.data?.length > 0 &&
    //   vm.$cmd.transformTableData &&
    //   gridGroupConfig
    // ) {
    //   res.data = vm.$cmd.transformTableData(vm, res.data)
    // }
    if (dsConfigName === 'tableData' && res?.data?.length > 0) {
      res.data = vm.$cmd.transformTableData(vm, res.data)
    }

    try {
      if (res?.error) {
        const saveBtn = vm.$select(`${vm.$ds.idPre}form_main_detail_top_save`)
        if (saveBtn?.$ds?.isFormSucc !== undefined) {
          saveBtn.$ds.isFormSucc = false
        }
        const saveAddBtn = vm.$select(`${vm.$ds.idPre}form_main_detail_top_save_add`)
        if (saveAddBtn?.$ds?.isFormSucc !== undefined) {
          saveAddBtn.$ds.isFormSucc = false
        }
      }
    } catch (e) {}
    // reqAfter 请求后
    if (apiConfig?.reqAfter) {
      res = await reqFn(apiConfig.reqAfter, vm, res)
      if (vm?.$ds?.[dsConfigName]) {
        vm.$ds[dsConfigName] = res
      }
    }
  }
  return res
}

