// 转换对象
export const flattenObject = (obj) => {
  let result = {}
  let stack = [{ obj, parentKey: '' }]
  while (stack.length > 0) {
    const { obj, parentKey } = stack.pop()
    for (let key in obj) {
      if (obj.hasOwnProperty(key)) {
        let newKey = parentKey ? `${parentKey}.${key}` : key
        if (typeof obj[key] === 'object' && !Array.isArray(obj[key])) {
          stack.push({ obj: obj[key], parentKey: newKey })
        } else {
          result[newKey] = obj[key]
        }
      }
    }
  }
  return result
}
// 转换url参数
export const changeURLArg = (url, arg, arg_val) => {
  var pattern = arg + '=([^&]*)'
  var replaceText = arg + '=' + arg_val
  if (url.match(pattern)) {
    var tmp = '/(' + arg + '=)([^&]*)/gi'
    tmp = url.replace(eval(tmp), replaceText)
    return tmp
  } else {
    if (url.match('[?]')) {
      return url + '&' + replaceText
    } else {
      return url + '?' + replaceText
    }
  }
}
// 判断是否有某后端视图 例如 xx_tree,xx_grid 调用 Tech.hasView('xx_tree,xx_grid', 'tree')
export const hasView = (typeStr, type) => {
  let has = false
  let judge = (str, type) => {
    if (str === type) {
      return true
    } else if (str.lastIndexOf(type) == str.length - type.length) {
      return true
    }
    return false
  }
  if (typeof typeStr === 'string' && typeStr) {
    if (typeStr.indexOf(',') !== -1) {
      let arr = typeStr.split(',')
      arr.map((item) => {
        if (judge(item, type)) {
          has = true
        }
      })
      for (let i = 0; i < arr.length; i++) {}
    } else {
      if (judge(typeStr, type)) {
        has = true
      }
    }
  }
  judge = null
  return has
}
