import { bizTabsHandler } from './formHandler'

export const handlerBizGrid = (nodeId, options = {}) => {
  let curNodeId = nodeId
  let handlers = {
    // 表格相关数据
    dataHandler: {
      // get 处理程序用于捕获对象属性的读取操作
      get: (target, property, receiver) => {
        let val = null
        let curNode = tech_app.page.getNode(curNodeId)
        if (curNode) {
          let pre = curNode.$ds.idPreTab || curNode.$ds.idPre
          let tableMainVm = curNode.$select(pre + 'table_main')
          let tableVm = curNode.$select(pre + 'table_main_table')
          if (property === 'tableData') {
            return tableVm?.data?.tableData || []
          } else if (property === 'currentRow') {
            return tableVm?.$ds?.mainTableRowData || {}
          } else if (property === 'checkedRows') {
            return tableVm?.$ds?.checkedDataList || []
          } else if (property === 'tbar') {
            return curNode.$select(pre + 'table_main_toolbar_btns')?.data?.items || []
          } else if (property === 'page') {
            return tableVm?.$ds?.paging || {}
          } else if (property === 'tableConfig') {
            val = new Proxy(tableVm?.data || {}, {
              get: (target, property, receiver) => {
                return target[property]
              }
            })
          } else if (property === 'isEdit') {
            return tableVm?.data?.isEdit
          } else if (property === 'erCacheData') {
            let tableCatch = tableVm.$ds.getRequest('tableData').cache
            return tableCatch?.__erInstance?.get()
          } else if (property === 'model') {
            return tableMainVm?.$ds?._metaParamsModel
          } else if (property === 'app') {
            return tableMainVm?.$ds?._metaParamsApp
          }
        }
        return val
      },
      // set 处理程序用于捕获对象属性的写入操作
      set: (target, property, value, receiver) => {
        let setSucc = true // 设置状态 true表示成功
        console.log(`Setting ${property} to ${value}`, target)
        let curNode = tech_app.page.getNode(curNodeId)
        if (curNode) {
          let pre = curNode.$ds.idPreTab || curNode.$ds.idPre
          let tableVm = curNode.$select(pre + 'table_main_table')
          if (property === 'tableData') {
            tableVm.data.tableData = value
          }
        }
        // target[property] = value
        return setSucc
      }
    },
    // 存储调用接口相关的请求
    reqHandler: {
      get: (target, property, receiver) => {
        let val = null
        let curNode = tech_app.page.getNode(curNodeId)
        if (curNode && ['tableData', 'tableDataCount', 'delTableData'].includes(property)) {
          let pre = curNode.$ds.idPreTab || curNode.$ds.idPre
          let tableMainVm = curNode.$select(pre + 'table_main')
          val = tableMainVm?.data?.ds_config?.list?.find((i) => i.name === property)
        }
        return val
      }
    },
    // 用来存起最原始的方法 扩展钩子前的原方法
    baseMethodsHandler: {
      get: (target, property, receiver) => {
        let val = null
        let curNode = tech_app.page.getNode(curNodeId)
        if (curNode) {
          let pre = curNode.$ds.idPreTab || curNode.$ds.idPre
          let tableMainWrapVm = curNode.$select(pre + 'table_main_wrap')
          let tableVm = curNode.$select(pre + 'table_main_table')
          let __srcHookFn = { ...tableMainWrapVm?.data?.__srcHookFn, ...tableVm?.data?.__srcHookFn }
          const hookArr = [
            'canCreate',
            'queryCount',
            'canDelete',
            'beforeDelete',
            'delete',
            'afterDelete',
            'canEdit',
            'beforeQuery',
            'query',
            'afterQuery',
            'select',
            'cancelSelect',
            'created',
            'mounted',
            'destroy'
          ]
          if (
            typeof property === 'string' &&
            hookArr.includes(property) &&
            __srcHookFn?.['commands.' + property]
          ) {
            val = __srcHookFn?.['commands.' + property]
          }
          return val
        }
      }
    },
    methodsHandler: {
      get: (target, property, receiver) => {
        let curNode = tech_app.page.getNode(curNodeId)
        if (curNode) {
          let pre = curNode.$ds.idPreTab || curNode.$ds.idPre
          let tableMainWrapVm = curNode.$select(pre + 'table_main_wrap')
          let tableVm = curNode.$select(pre + 'table_main_table')
          let distHookFn = {
            ...tableMainWrapVm?.data?.commands,
            ...tableVm?.data?.commands
          }
          const hookArr = [
            'canCreate',
            'queryCount',
            'canDelete',
            'beforeDelete',
            'delete',
            'afterDelete',
            'canEdit',
            'beforeQuery',
            'query',
            'afterQuery',
            'select',
            'cancelSelect',
            'created',
            'mounted',
            'destroy'
          ]
          if (
            typeof property === 'string' &&
            hookArr.includes(property) &&
            distHookFn?.[property]
          ) {
            return distHookFn[property]
          } else if (property === 'runRefresh') {
            // 刷新方法
            return function () {
              let runRefreshVm = curNode.$select(pre + 'table_main_toolbar_refresh')
              runRefreshVm?.instance?.click()
            }
          } else if (property === 'toPage') {
            // 跳转到表格某页
            return function (val) {
              let pagingVm = curNode.$select(pre + 'table_main_paging')
              if (pagingVm?.instance) {
                pagingVm.instance.pageVal = val
                pagingVm.instance.pageChange(val)
              }
            }
          } else if (property === 'addErData') {
            return function (data, tableVm) {
              tableVm.$cmd.dealTableErCatch('add', data, tableVm, 'tableData')
            }
          }
        }
      }
    },
    nodesHandler: {
      get: (target, property, receiver) => {
        let curNode = tech_app.page.getNode(curNodeId)
        if (curNode) {
          let pre = curNode.$ds.idPreTab || curNode.$ds.idPre
          let tableVm = curNode.$select(pre + 'table_main_table')
          if (property === 'self') {
            return tableVm
          } else if (property === 'tbarNodes') {
            let toolbarBtn = curNode.$select(pre + 'table_main_toolbar_btns')
            return new Proxy(
              {},
              {
                get: (target, property, receiver) => {
                  let id = toolbarBtn?.data?.items?.[property]?.id
                  if (id) return curNode.$select(id)
                }
              }
            )
          } else if (property === 'buttonNodes') {
            let operation = curNode.$select(pre + 'table_main_table_column_operation')
            return new Proxy(
              {},
              {
                get: (target, property, receiver) => {
                  let id = operation?.data?.items?.[property]?.id
                  if (id) return curNode.$select(id)
                }
              }
            )
          } else if (property === 'refreshNode') {
            return curNode.$select(pre + 'table_main_toolbar_refresh')
          }
        }
      }
    },
    editHandler: {
      get: (target, property, receiver) => {
        let curNode = tech_app.page.getNode(curNodeId)
        let pre = curNode.$ds.idPreTab || curNode.$ds.idPre
        let val = null
        let hookArr = [
          'canCreateRow',
          'canDeleteRow',
          'deleteConfirm',
          'beforeSingleRowDelete',
          'singleRowDelete',
          'afterSingleRowDelete',
          'canRowEditSave',
          'beforeRowEditSave',
          'rowEditSave',
          'afterRowEditSave'
        ]
        if (curNode) {
          let tableMainWrapVm = curNode.$select(pre + 'table_main_wrap')
          if (property === 'baseMethods') {
            let __srcHookFn = {
              ...tableMainWrapVm?.data?.__srcHookFn
            }
            val = new Proxy(__srcHookFn || {}, {
              get: (target, property, receiver) => {
                if (
                  typeof property === 'string' &&
                  hookArr.includes(property) &&
                  target?.['commands.' + property]
                ) {
                  return target?.['commands.' + property]
                }
              }
            })
          } else if (property === 'req') {
            val = new Proxy(
              {},
              {
                get: (target, property, receiver) => {
                  if (property === 'singleRowEditDelete') {
                    let tableMainVm = curNode.$select(pre + 'table_main')
                    return tableMainVm?.data?.ds_config?.list?.find(
                      (i) => i.name === 'delTableData'
                    )
                  } else if (property === 'singleRowEditSave') {
                    let tableMainWrapVm = curNode.$select(pre + 'table_main_wrap')
                    return tableMainWrapVm?.data?.ds_config?.list?.find(
                      (i) => i.name === 'formUpdate'
                    )
                  }
                }
              }
            )
          } else if (property === 'methods') {
            let distHookFn = {
              ...tableMainWrapVm?.data?.commands
            }
            val = new Proxy(distHookFn || {}, {
              get: (target, property, receiver) => {
                if (
                  typeof property === 'string' &&
                  hookArr.includes(property) &&
                  target?.[property]
                ) {
                  return target[property]
                }
              }
            })
          }
        }
        return val
      }
    },
    tabsHandler: bizTabsHandler(curNodeId)
  }
  return handlers
}
