        initTreeFormDefaultValue: (vm, formItems) => {
          const treeNode = vm.$select(vm.$ds.idPre + 'tree_main_wrap')
          if (treeNode?.$ds?.currentData) {
            const treeCurSelect = treeNode.$ds.currentData
            const treeProps = treeNode.$ds.tableView.data.views.tree.body.props
            let subViewFormInitValues = [] //表单默认值key数组
            let treekeys = [] //树对应的key数组
            if (treeProps.subViewFormInitValues && treeProps.subViewFormInitValues.length > 0) {
              //回填多个默认值
              treeProps.subViewFormInitValues.map((item) => {
                subViewFormInitValues.push(item.subformName)
                treekeys.push(item.treeName)
              })
            } else if (treeProps.subViewFilter) {
              //回填单个默认值
              subViewFormInitValues.push(treeProps.subViewFilter)
              treekeys.push(treeProps.subViewFilter)
            }

            const _formatValue = (items) => {
              items.map((item) => {
                let keyIndex = subViewFormInitValues.indexOf(item.name)
                if (keyIndex > -1) {
                  let defalutValueItemName = item.name
                  if (!treeCurSelect[treekeys[keyIndex]]) return
                  //根据树对应的key取对应的默认值
                  if (treekeys && treekeys.length > 0) defalutValueItemName = treekeys[keyIndex]
                  //表单默认值
                  item.defaultValue = treeCurSelect[defalutValueItemName]

                  if (['lookup', 'select'].includes(item.type)) {
                    if (
                      Object.prototype.toString.call(treeCurSelect[defalutValueItemName]) ===
                      '[object Object]'
                    )
                      return
                    // 添加默认值转换指定label的功能
                    const treePropConfig = (treeProps.subViewFormInitValues || []).find(
                      (item) => item.subformName == defalutValueItemName
                    )
                    const label = treePropConfig?.label
                      ? treePropConfig.label
                      : treePropConfig?.labelInValue
                      ? treeCurSelect[defalutValueItemName]
                      : treeCurSelect.name

                    const selectOption = {
                      label,
                      value: treeCurSelect[defalutValueItemName]
                    }

                    item.defaultValue = selectOption
                  }
                }
              })
            }

            formItems.forEach((item) => {
              if (item.type == 'row') {
                _formatValue(item.items)
              } else if (item.type == 'collapse') {
                // 适配表单分组
                item.items.map((ite) => {
                  ite.items[0].items.map((el) => {
                    _formatValue(el.items)
                  })
                })
              }
            })
          }
          return formItems
        },
