                  try {
                    // iframe模式内部情况 从hash上删除 view id clickType
                    if (urlParams['clickType'] && urlParams['view'] && urlParams['id']) {
                      delete urlParams['clickType']
                      delete urlParams['view']
                      delete urlParams['id']
                      let distHashStr = ''
                      for (let p in urlParams) {
                        distHashStr += '&' + p + '=' + urlParams[p]
                      }
                      if (distHashStr) {
                        distHashStr = distHashStr.substr(1, distHashStr.length)
                        distHashStr = '#' + distHashStr
                      }
                      location.hash = distHashStr
                    }
                  } catch (e) {
                    console.log(' === iframe inner hash delete view id clickType error == ', e)
                  }
