    changeTheme: (item) => {
      window?.Tech?.changeTheme(item)
    },
    openLoginPage: (app) => {
      if (app?.page?.data?.id && app.page.data.id !== 'page_meta_login' && !app.page.data.noToken) {
        window.Tech.token.remove()
        if (window?.tech?.userInfo) {
          window.tech.userInfo = {}
        }
        // 清空loadview数据缓存
        if (window?.tech?.loadViewCache) {
          window.tech.loadViewCache = null
        }
        // 清空自定义权限数据缓存
        if (window?.tech?.customPermissionCache) {
          window.tech.customPermissionCache = null
        }
        window.ELEMENT.Message.error(Tech.$t('common.systemAbnormal'))
        try {
          // 补充清理缓存解决苹果电脑退出登录问题
          window.Tech.cookies.remove('userInfo')
          window.localStorage.removeItem('userInfo')
          window.localStorage.removeItem('token')
          window.localStorage.removeItem('userInfoMore')
          window.localStorage.removeItem('username')
        } catch (e) {}
        app.openPage('page_meta_login')
      }
    }
