// 处理搜索栏业务代理处理
export const handlerBizSearch = (nodeId, options = {}) => {
  let curNodeId = nodeId
  let handlers = {
    dataHandler: {
      // get 处理程序用于捕获对象属性的读取操作
      get: (target, property, receiver) => {
        let val = null
        let curNode = tech_app.page.getNode(curNodeId)
        if (curNode) {
          let pre = curNode.$ds.idPreTab || curNode.$ds.idPre
          let tableMainVm = curNode.$select(pre + 'table_main')
          if (property === 'form') {
            let topFormData =
              curNode.$select(pre + 'form_main_table_search_common')?.$ds?.form || {}
            let bottomFormData =
              curNode.$select(pre + 'form_main_table_search_dropdown')?.$ds?.form || {}
            val = new Proxy(
              { ...topFormData, ...bottomFormData },
              {
                // 动态设置子属性代理
                get: (target, property, receiver) => {
                  return target[property]
                },
                set: (target, property, value, receiver) => {
                  let setSuccess = true // 设置状态 true表示成功
                  if (topFormData[property] !== undefined) {
                    topFormData[property] = value
                  } else if (bottomFormData[property] !== undefined) {
                    bottomFormData[property] = value
                  }
                  return setSuccess
                }
              }
            )
          } else if (property === 'model') {
            return tableMainVm?.$ds?._metaParamsModel
          } else if (property === 'app') {
            return tableMainVm?.$ds?._metaParamsApp
          }
        }
        return val
      },
      // set 处理程序用于捕获对象属性的写入操作
      set: (target, property, value, receiver) => {
        let setSuccess = true // 设置状态 true表示成功
        let curNode = tech_app.page.getNode(curNodeId)
        if (curNode) {
          let pre = curNode.$ds.idPreTab || curNode.$ds.idPre
          if (property === 'form') {
            let topFormData =
              curNode.$select(pre + 'form_main_table_search_common')?.$ds?.form || {}
            let bottomFormData =
              curNode.$select(pre + 'form_main_table_search_dropdown')?.$ds?.form || {}
            for (let k in value) {
              if (topFormData[k] !== undefined) {
                topFormData[k] = value[k]
              } else if (bottomFormData[k] !== undefined) {
                bottomFormData[k] = value[k]
              }
            }
          }
        }
        return setSuccess
      }
    },
    reqHandler: {
      get: (target, property, receiver) => {
        let val = null
        let curNode = tech_app.page.getNode(curNodeId)
        if (curNode && ['tableData'].includes(property)) {
          let pre = curNode.$ds.idPreTab || curNode.$ds.idPre
          let tableMainVm = curNode.$select(pre + 'table_main')
          val = tableMainVm?.data?.ds_config?.list?.find((i) => i.name === property)
        }
        return val
      }
    },
    baseMethodsHandler: {
      get: (target, property, receiver) => {
        let val = null
        let curNode = tech_app.page.getNode(curNodeId)
        if (curNode) {
          let pre = curNode.$ds.idPreTab || curNode.$ds.idPre
          let searchVm = curNode.$select(pre + 'main_table_search_container')
          let tableSearchVm = curNode.$select(pre + 'container_table_search')
          let __srcHookFn = { ...searchVm?.data?.__srcHookFn, ...tableSearchVm?.data?.__srcHookFn }
          if (['created', 'mounted', 'destroy'].includes(property)) {
            val = __srcHookFn?.[property]
          } else if (['canQuery', 'validateQuery'].includes(property)) {
            val = __srcHookFn?.['commands.' + property]
          }
        }
        return val
      }
    },
    methodsHandler: {
      get: (target, property, receiver) => {
        let val = null
        let curNode = tech_app.page.getNode(curNodeId)
        if (curNode) {
          let pre = curNode.$ds.idPreTab || curNode.$ds.idPre
          let searchVm = curNode.$select(pre + 'main_table_search_container')
          if (['created', 'mounted', 'destroy'].includes(property)) {
            val = searchVm?.data?.[property]
          } else if (property === 'canQuery') {
            val = searchVm?.data?.commands?.[property]
          } else if (property === 'validateQuery') {
            let tableSearchVm = curNode.$select(pre + 'container_table_search')
            val = tableSearchVm?.data?.commands?.[property]
          } else if (property === 'runReset') {
            return function () {
              let resetVm = curNode.$select(pre + 'container_table_search_wrap_items_1') // 重置按钮
              resetVm?.instance?.click()
            }
          } else if (property === 'runSearch') {
            return function () {
              let searchVm = curNode.$select(pre + 'form_main_table_search_btn') // 搜索按钮
              searchVm?.instance?.click()
            }
          }
        }
        return val
      }
    },
    nodesHandler: {
      get: (target, property, receiver) => {
        let curNode = tech_app.page.getNode(curNodeId)
        if (curNode) {
          let pre = curNode.$ds.idPreTab || curNode.$ds.idPre
          if (property === 'self') {
            return curNode.$select(pre + 'main_table_search_container')
          } else if (property === 'formNode') {
            return curNode.$select(pre + 'form_main_table_search_common')
          } else if (property === 'extendFormNode') {
            return curNode.$select(pre + 'form_main_table_search_dropdown')
          } else if (property === 'searchBtnNode') {
            return curNode.$select(pre + 'form_main_table_search_btn')
          } else if (property === 'resetBtnNode') {
            return curNode.$select(pre + 'container_table_search_wrap_items_1')
          } else if (property === 'conditionNode') {
            return curNode.$select(pre + 'form_main_table_search')
          }
        }
      }
    }
  }
  return handlers
}
