import { handlerBizPage } from './bizHandler/pageHandler'
import { handlerBizGridPage } from './bizHandler/gridPageHandler'
import { handlerBizDetailPage } from './bizHandler/detailPageHandler'
import { handlerBizSearch } from './bizHandler/searchHandler'
import { handlerBizGrid } from './bizHandler/gridHandler'
import { handlerBizForm } from './bizHandler/formHandler'
import { handlerBizTree } from './bizHandler/treeHandler'

// 添加super属性到上下文
export const addSuperToVm = (vm, options = {}) => {
  let { collectNodeId } = options
  let useExtendName = options.extendName
  // 创建处理程序对象
  const handler = {
    // get 处理程序用于捕获对象属性的读取操作
    get: (target, property, receiver) => {
      // console.log(' ==== property == ', property)
      let srcFn = null // 存最初始的方法
      let extendLinkFn = null // 存上一次链路上的方法
      let collectNode = tech_app.page.getNode(collectNodeId)
      if (collectNode) {
        // 取出存到__srcHookFn标识里面最初始的方法
        let improveNodeId = collectNode?.$collect?.collectMap?.get(property)?.improveNodeId
        let improveNodeAttrPath =
          collectNode?.$collect?.collectMap?.get(property)?.improveNodeAttrPath
        if (improveNodeId && improveNodeAttrPath) {
          let improveNode = tech_app.page.getNode(improveNodeId)
          if (improveNode?.data?.__srcHookFn?.[improveNodeAttrPath]) {
            let orignFn = improveNode.data.__srcHookFn[improveNodeAttrPath]
            srcFn = async (...args) => {
              if (args?.[0]?.super) {
                // super暂存到 _super
                args[0]._super = args[0].super
              }
              args[0].super = {}
              let res = null
              if (typeof orignFn === 'function') {
                if (orignFn.constructor.name === 'Function') {
                  res = orignFn(...args)
                } else if (orignFn.constructor.name === 'AsyncFunction') {
                  res = await orignFn(...args)
                }
              }
              if (args?.[0]?._super) {
                // _super恢复到 super
                args[0].super = args[0]._super
                delete args[0]._super
              }
              return res
            }
          }
        }

        // 取链路上的方法
        // ** 多层级时候调用改成 vm.super['search.xxxquery']();
        let collectExtentName = ''
        if (!useExtendName && collectNode?.data?.hook) {
          collectExtentName = window.Tech._get(collectNode.data.hook, property) || ''
        }
        let extendName = useExtendName || collectExtentName
        if (extendName) {
          // 获取当前扩展
          let extendItem = tech_app.extendView.get(extendName)
          let linkHas = false // 是否在链路上找到
          let findExtend = null
          let sendExtendName = ''
          // 按继承链路网上寻找
          while (extendItem?.extend && tech_app?.extendView?.get(extendItem.extend)) {
            findExtend = tech_app.extendView.get(extendItem.extend)
            if (findExtend?.hook && window.Tech._get(findExtend.hook, property)) {
              linkHas = true
              sendExtendName = extendItem.extend
              break
            }
            extendItem = findExtend
          }
          if (linkHas) {
            let originExtendLinkFn = window.Tech._get(findExtend.hook, property)
            let useCollectNodeId = collectNodeId
            extendLinkFn = async (...args) => {
              if (args?.[0]?.super) {
                // super暂存到 _super
                args[0]._super = args[0].super
              }
              args[0].super = {}
              if (args?.[0] && window?.Tech?.addSuperToVm && sendExtendName) {
                // 重新拼接vm.super
                window.Tech.addSuperToVm(args[0], {
                  collectNodeId: useCollectNodeId,
                  extendName: sendExtendName
                })
              }
              let res = null
              if (typeof originExtendLinkFn === 'function') {
                if (originExtendLinkFn.constructor.name === 'Function') {
                  res = originExtendLinkFn(...args)
                } else if (originExtendLinkFn.constructor.name === 'AsyncFunction') {
                  res = await originExtendLinkFn(...args)
                }
              }
              if (args?.[0]?._super) {
                // _super恢复到 super
                args[0].super = args[0]._super
                delete args[0]._super
              }
              return res
            }
          }
        }
      }
      return extendLinkFn || srcFn
    }

    // set 处理程序用于捕获对象属性的写入操作
    // set: (target, property, value, receiver) => {
    //   console.log(`Setting ${property} to ${value}`)
    //   target[property] = value
    //   return true // 表示设置操作成功
    // }
  }
  // 创建代理对象
  vm.super = new Proxy({}, handler)
}

// 添加biz业务属性到上下文
export const addBizToVm = (vm, options = {}) => {
  vm.biz = {}
  vm.biz.page = {}
  vm.biz.gridPage = {}
  vm.biz.detailPage = {}
  vm.biz.search = {}
  vm.biz.grid = {}
  vm.biz.form = {}
  vm.biz.tree = {}

  let handlerPage = handlerBizPage(vm?.data?.id)
  let handlerGridPage = handlerBizGridPage(vm?.data?.id)
  let handlerDetailPage = handlerBizDetailPage(vm?.data?.id)
  let handlerSearch = handlerBizSearch(vm?.data?.id)
  let handlerGrid = handlerBizGrid(vm?.data?.id)
  let handlerForm = handlerBizForm(vm?.data?.id)
  let handlerTree = handlerBizTree(vm?.data?.id)

  // -----------page begin------------
  vm.biz.page.data = new Proxy({}, handlerPage.dataHandler)
  vm.biz.page.req = new Proxy({}, handlerPage.reqHandler)
  vm.biz.page.baseMethods = new Proxy({}, handlerPage.baseMethodsHandler)
  vm.biz.page.methods = new Proxy({}, handlerPage.methodsHandler)
  vm.biz.page.nodes = new Proxy({}, handlerPage.nodesHandler)
  // -----------page end------------

  // -----------gridPage begin------------
  vm.biz.gridPage.data = new Proxy({}, handlerGridPage.dataHandler)
  vm.biz.gridPage.req = new Proxy({}, handlerGridPage.reqHandler)
  vm.biz.gridPage.baseMethods = new Proxy({}, handlerGridPage.baseMethodsHandler)
  vm.biz.gridPage.methods = new Proxy({}, handlerGridPage.methodsHandler)
  vm.biz.gridPage.nodes = new Proxy({}, handlerGridPage.nodesHandler)
  // -----------gridPage end------------

  // -----------detailPage begin------------
  vm.biz.detailPage.data = new Proxy({}, handlerDetailPage.dataHandler)
  vm.biz.detailPage.req = new Proxy({}, handlerDetailPage.reqHandler)
  vm.biz.detailPage.baseMethods = new Proxy({}, handlerDetailPage.baseMethodsHandler)
  vm.biz.detailPage.methods = new Proxy({}, handlerDetailPage.methodsHandler)
  vm.biz.detailPage.nodes = new Proxy({}, handlerDetailPage.nodesHandler)
  // -----------detailPage end------------

  // -----------search begin------------
  vm.biz.search.data = new Proxy({}, handlerSearch.dataHandler)
  vm.biz.search.req = new Proxy({}, handlerSearch.reqHandler)
  vm.biz.search.baseMethods = new Proxy({}, handlerSearch.baseMethodsHandler)
  vm.biz.search.methods = new Proxy({}, handlerSearch.methodsHandler)
  vm.biz.search.nodes = new Proxy({}, handlerSearch.nodesHandler)
  // -----------search end------------

  // -----------grid begin------------
  vm.biz.grid.data = new Proxy({}, handlerGrid.dataHandler)
  vm.biz.grid.req = new Proxy({}, handlerGrid.reqHandler)
  vm.biz.grid.baseMethods = new Proxy({}, handlerGrid.baseMethodsHandler)
  vm.biz.grid.methods = new Proxy({}, handlerGrid.methodsHandler)
  vm.biz.grid.nodes = new Proxy({}, handlerGrid.nodesHandler)
  vm.biz.grid.edit = new Proxy({}, handlerGrid.editHandler)
  vm.biz.grid.tabs = new Proxy({}, handlerGrid.tabsHandler)
  // -----------grid end------------

  // -----------form begin------------
  vm.biz.form.data = new Proxy({}, handlerForm.dataHandler)
  vm.biz.form.req = new Proxy({}, handlerForm.reqHandler)
  vm.biz.form.baseMethods = new Proxy({}, handlerForm.baseMethodsHandler)
  vm.biz.form.methods = new Proxy({}, handlerForm.methodsHandler)
  vm.biz.form.nodes = new Proxy({}, handlerForm.nodesHandler)
  vm.biz.form.tabs = new Proxy({}, handlerForm.tabsHandler)
  // -----------form end------------

  // -----------tree begin------------
  vm.biz.tree.data = new Proxy({}, handlerTree.dataHandler)
  vm.biz.tree.req = new Proxy({}, handlerTree.reqHandler)
  vm.biz.tree.baseMethods = new Proxy({}, handlerTree.baseMethodsHandler)
  vm.biz.tree.methods = new Proxy({}, handlerTree.methodsHandler)
  vm.biz.tree.nodes = new Proxy({}, handlerTree.nodesHandler)
  // -----------tree end------------

  return vm.biz
}

// 调用钩子方法
export const callHook = async (vm, hookName, params, options = {}) => {
  let cmdHookName = options?.hookName || hookName // 若有options.hookName 则以选项里面的优先
  if (vm?.$collect?.get(hookName)) {
    return await vm.$collect.get(hookName)(vm, params, options)
  } else if (vm?.$cmd?.[cmdHookName]) {
    return await vm.$cmd[cmdHookName](vm, params, options)
  }
  return null
}

// 递归重置视图提升属性key名
// tablePage 'table_main_table' [{newKey: 'form.tabs.' + vm.$ds.tabUniqueTag + '.grid.created', oldKey: 'grid.created'}]
export const nestResetImproveKey = (view, findId = '', mapArr = []) => {
  if (view && findId) {
    let getV = window.Tech.nestGetItemById(view, findId)
    mapArr.map((item) => {
      let { newKey, oldKey } = item
      if (getV?.$improve?.[oldKey]) {
        getV.$improve[newKey] = getV.$improve[oldKey]
        delete getV.$improve[oldKey]
      }
    })
  }
}
