import { getLinkageParams } from '../common/onchange'
export default class LookupRender {
  constructor(modelMeta, options = {}) {
    this.modelMeta = modelMeta
    this.options = options
    this.baseUrl = this.options.baseUrl
    this.domains = modelMeta.formModelMeta.view.body.domains || []
    this.option = []
    // console.log(' **** modelMeta *** ', modelMeta._metaColumn)
    let name = modelMeta._metaColumn?.name || modelMeta.name
    this.config = {
      paramApp: this.options.paramApp || 'base',
      paramModel: this.options.paramModel || '',
      getCurVm: this.options.getCurVm || null,
      getData: async (
        dataSource = {},
        params,
        customFilter = [],
        f,
        config,
        compInstance = null
      ) => {
        let res = {}
        let sendParams = {}

        let appendAppParams = { app: modelMeta?.formModelMeta?.vm?.$ds?._metaParamsApp || 'base' }

        if (!dataSource.type) {
          const selectionMethod =
            modelMeta._metaColumn?.selectionMethod || modelMeta.selectionMethod

          let lookupFilter = customFilter || []

          let itemConfig = modelMeta?._metaColumn || modelMeta || {}
          let linkageParams = {}
          let getLinkageRes = getLinkageParams(itemConfig, f) // 拼接联动参数
          if (Object.prototype.toString.call(getLinkageRes) === '[object Object]') {
            linkageParams = getLinkageRes
          } else if (Object.prototype.toString.call(getLinkageRes) === '[object Array]') {
            lookupFilter = modelMeta.formModelMeta.vm.$cmd.meta.addSearch(
              lookupFilter,
              getLinkageRes
            )
          }
          // 搜索默认值的选线
          // 多选的情况
          // config.defaultValue第1项和config.dataSource.form[config.name]的第1项都不是对象（对象类型不需要再push筛选项）
          const hasMultiFilter =
            !!config.multiple &&
            (config?.defaultValue?.length || config?.dataSource?.form?.[config.name]?.length) &&
            Object.prototype.toString.call(config?.defaultValue?.[0]) !== '[object Object]' &&
            Object.prototype.toString.call(config?.dataSource?.form?.[config.name]?.[0]) !==
              '[object Object]'

          if (
            (config.defaultValue || config.dataSource?.form?.[config.name]) &&
            Object.prototype.toString.call(config.defaultValue) !== '[object Object]' &&
            hasMultiFilter &&
            !config.hasDefaultSearch
          ) {
            let hasIdFilter = false
            lookupFilter.forEach((item) => {
              if (item[0] == 'id') {
                hasIdFilter = true
              }
            })
            if (!hasIdFilter) {
              // 需要兼容多选的情况
              lookupFilter.push([
                'id',
                config.multiple ? 'in' : '=',
                config.dataSource.form[config.name] || config.defaultValue
              ])
            }
          }

          let getModelName = modelMeta._metaColumn?.modelName || modelMeta.modelName
          sendParams = {
            model: getModelName ? getModelName : modelMeta.formModelMeta.vm.$ds._metaParamsModel,
            service: selectionMethod ? selectionMethod : 'lookup',
            args: {
              filter: lookupFilter,
              useDisplayForModel: true,
              limit: params.paging.end - params.paging.start + 2, // 21
              offset: params.paging.start - 1,
              field: modelMeta._metaColumn?.name || modelMeta.name,
              keyword: params?.search || '', // 添加搜索参数
              ...linkageParams
            }
          }
        } else if (dataSource.type === 'meta') {
          // dataSource就是arguments
          sendParams = dataSource.params
          sendParams = {
            ...appendAppParams,
            ...sendParams
          }
        }

        // // 如果lookup的field attrs里配置了RelateModelApp 则查询时接口app取RelateModelApp的值
        // if (modelMeta._metaColumn?.attrs?.RelateModelApp) {
        //   sendParams.app = modelMeta._metaColumn.attrs.RelateModelApp
        // }

        // modelMeta.formModelMeta.vm.$ds.tech_authId =
        // modelMeta._metaColumn.dataSource.tech_authId
        // 调用lookup的接口变更为从表单的ds_config调用，因需要拿lookup的权限id传递给接口
        const targetNode = tech_app.page.getNode(config.id ?? null) //增加null值兼容，避免getNode()取错节点
        let lookup = targetNode || modelMeta.formModelMeta.vm
        // 拿到当前的appName - targetNode 不存在时，从_metaColumn上取
        const appName = targetNode ? targetNode?.data?.appName : modelMeta?._metaColumn?.appName
        if (appName) {
          sendParams.app = appName
        }
        try {
          // 表格情况 重新赋值 mainTableRowData
          if (f?.values?.__FORMAT_COLUMN_ITEMS__) {
            try {
              let rowId =
                compInstance?.$el?.parentNode?.parentNode?.parentNode?.getAttribute('rowid')
              let findRow = lookup.$ds.tableData.data.find((item) => item.id === rowId)
              if (findRow) {
                let tbVm = vm.$select(lookup.$cmd.getIdPre(lookup) + 'table_main_table')
                if (tbVm) {
                  tbVm.$select(
                    lookup.$cmd.getIdPre(lookup) + 'table_main_table'
                  ).$ds.mainTableRowData = findRow
                }
              }
            } catch (e) {}
          }

          let reqPrepFn = config.reqPrep || modelMeta._metaColumn?.reqPrep || modelMeta.reqPrep
          if (reqPrepFn) {
            if (Object.prototype.toString.call(reqPrepFn) === '[object String]') {
              reqPrepFn = new Function('return ' + reqPrepFn).bind(window)()
            }
            sendParams = reqPrepFn(
              lookup || tech_app.page.getNode(tech_app.page.data.id),
              sendParams,
              config
            )
            config.reqPrep = reqPrepFn
          }
        } catch (e) {}
        res = await lookup.request('lookup', sendParams)

        try {
          let reqAfterFn = config.reqAfter || modelMeta._metaColumn?.reqAfter || modelMeta.reqAfter
          if (reqAfterFn) {
            if (Object.prototype.toString.call(reqAfterFn) === '[object String]') {
              reqAfterFn = new Function('return ' + reqAfterFn).bind(window)()
            }
            res = reqAfterFn(lookup || tech_app.page.getNode(tech_app.page.data.id), res, config)
            config.reqAfter = reqAfterFn
          }
        } catch (e) {}

        // 记录有默认值的情况，是否已经搜索过，用于判断是否添加filter
        if (res.data) {
          config.hasDefaultSearch = true
        }

        let items = []
        if (dataSource.transformRes) {
          if (
            typeof params.transformRes === 'string' ||
            typeof dataSource.transformRes === 'string'
          ) {
            dataSource.transformRes = new Function('return ' + dataSource.transformRes)().bind(
              window
            )
          }
          items = dataSource.transformRes(res)
        } else if (Object.prototype.toString.call(res.data) === '[object Object]') {
          items = res.data.data.map((item) => {
            return {
              label: item[1],
              value: item[0]
            }
          })
        } else if (Object.prototype.toString.call(res.data) === '[object Array]') {
          try {
            res.data = res.data.map((itemI) => {
              if (itemI.name !== undefined && itemI.label === undefined) {
                itemI.label = itemI.name
              }
              if (itemI.id !== undefined && itemI.value === undefined) {
                itemI.value = itemI.id
              }
              return itemI
            })
          } catch (e) {}
          items = res.data.map((item) => {
            return {
              ...item,
              label: item.label,
              value: item.value
            }
          })
        }
        this.option = items
        return {
          items
        }
      },
      bind_on_optionsUpdated: async (params) => {
        const { self: vm, value } = params
        // 处理默认选中第一项，赋值到filter中
        // const value = await params.value()
        vm.data.options = value
        // if (vm.data.defaultSelected) {
        //   let curSelected = value[0]?.value || false
        //   if (vm.data.cache) {
        //     const storage = sessionStorage.getItem(vm.data.cache)
        //     const curCache = JSON.parse(storage)
        //     curSelected =
        //       !!curCache &&
        //       value.find((item) => {
        //         return item.value == curCache[vm.data.name]?.value
        //       })
        //     // vm.data.defaultValue = value[0].value || null
        //     // vm.data.model[vm.data.name] = curSelected?.value || value[0].value
        //   }

        //   if (curSelected) {
        //     const filter = {}
        //     filter[vm.data.name] = value[0].value
        //     filter[vm.data.name + '___values'] = value[0]
        //     vm.$ds.tableFilter = vm.$ds.tableFilter?.concat(
        //       vm.$cmd.meta.formFormat.getSearchTagsFilter(vm, filter, [vm.data])
        //     )
        //     if (vm.$ds.tableFilter) {
        //       // 节流措施： 防止多个lookup配置defaultSelected触发多次查询
        //       let lookupTimer = vm.$select(vm.$cmd.getIdPre(vm) + 'form_main_table_search').data
        //         .__lookupTimer
        //       if (lookupTimer) {
        //         clearTimeout(lookupTimer)
        //         lookupTimer = null
        //       }
        //       vm.$select(vm.$cmd.getIdPre(vm) + 'form_main_table_search').data.__lookupTimer =
        //         setTimeout(() => {
        //           vm.$select(vm.$cmd.getIdPre(vm) + 'form_main_table_search').$cmd.commonSearch({
        //             self: vm
        //           })
        //         }, 200)
        //     }

        //     vm.$ds.delaySearch = false
        //   }
        // }
      },
      paging: {
        prev: false,
        next: true,
        totalCount: '',
        input: '1-20',
        autoControll: true // 自动识别是否有上一页，下一页
      }
    }
  }
}
