import headerView from './header.js'
import sidebarView from './sidebar.js'
import coverView from './cover.js'

export default {
  type: 'page',
  id: 'page_meta_index',
  name: 'index',
  title: Tech.$t('common.home'),
  layout: 'absolute',
  style: {
    width: '100%',
    height: '100%',
    display: 'flex',
    flexDirection: 'column'
  },
  commands: {
    toMenu: (vm, menuTag) => {
      if (tech?.TABIFRAME?.inner) {
        setTimeout(() => {
          window.parent.postMessage(
            {
              type: 'TABIFRAME_FN',
              fn:
                "()=>{ let v = tech_app.page.getNode(tech_app.page.data.id); v.$cmd.toMenu(v, '" +
                menuTag +
                "'); }"
            },
            window.tech.TABIFRAME.host
          )
        })
      } else if (window?.$wujie?.microApp) {
        // 微应用自身嵌套情况
        $wujie.microApp.toMenu(menuTag)
      } else {
        return new Promise((resolve, reject) => {
          let menuObj = vm.$select('menu_meta_siderbar')
          let appsMenusSrc = menuObj.$ds.appsMenus
          let appsMenusSrcMenu = appsMenusSrc?.find((item) => item?.name === menuTag)
          if (appsMenusSrcMenu) {
            let sidebar_app_base_button = document.getElementById(
              'sidebar_app_' + appsMenusSrcMenu.product + '_button'
            ) // 先点开基本应用产品线
            sidebar_app_base_button.click()
            let getAppMenu = (obj, name) => {
              let appStoreMenu = null
              for (let i = 0; i < obj.length; i++) {
                if (obj[i]?.name === name) {
                  appStoreMenu = obj[i]
                  break
                }
                if (obj[i].children) {
                  appStoreMenu = getAppMenu(obj[i].children, name)
                  if (appStoreMenu) {
                    break
                  }
                }
              }
              return appStoreMenu
            }
            let timerName = 'menu_meta_siderbar_timer_' + menuTag
            let clearTimer = () => {
              if (window[timerName]) {
                window.clearInterval(window[timerName])
                window[timerName] = null
              }
            }
            let count = 0
            window[timerName] = window.setInterval(() => {
              try {
                count++
                if (menuObj) {
                  let appsMenus = menuObj.instance.menus
                  let appStoreMenu = getAppMenu(appsMenus, menuTag)
                  if (appStoreMenu) {
                    clearTimer()
                    menuObj.instance.open(appStoreMenu, true)
                    window.setTimeout(() => {
                      resolve(true)
                    }, 500)
                    getAppMenu = null
                    clearTimer = null
                  }
                  if (count > 40) {
                    // 8秒超时
                    clearTimer()
                    resolve(false)
                    getAppMenu = null
                    clearTimer = null
                  }
                }
              } catch (error) {
                clearTimer()
              }
            }, 200)
          } else {
            resolve(false)
          }
        })
      }
    }
  },
  created: async (vm) => {},
  mounted: async (vm) => {
    // 来源于登录页 没有请求profile接口
    if (window.techFromLogin && !window.techReqLoginProfile && !window.techReqSchemaProfile) {
      window.techFromLogin = false
      let userId = ''
      try {
        let userInfo = JSON.parse(window.Tech.cookies.get('userInfo'))
        userId = userInfo.id
      } catch (e) {}
      if (userId) {
        let result = await window.Tech.httpMeta({
          data: {
            // 参考元模型后端的传参规范
            params: {
              args: { ids: [userId] },
              service: 'profile',
              model: 'rbac_user',
              app: 'base'
            }
          }
        })

        console.log(' === emit req techReqIndexProfile ')
        window.Tech.tBus.$emit('techReqIndexProfile')
      }
    }
    if (window.techReqSchemaProfile) {
      window.techReqSchemaProfile = false
    }
  },
  destory: (vm) => {
    console.log(' === in index page destory ', vm)
  },
  ds_config: {
    list: [
      {
        name: 'checkLogin',
        type: 'meta',
        method: 'service',
        autoRequest: false,
        options: {
          params: {
            args: {
              offset: 0,
              limit: 1,
              properties: ['mobile', 'login', 'name', 'id', 'email']
            },
            service: 'search',
            model: 'rbac_user'
          }
        }
      }
    ]
  },
  items: [headerView, sidebarView, coverView]
}
