const flowStatusBlock = {
  name: 'tech-my-flowStatus-block', // 组件名
  __block: true, // 标识为区块视图组件 固定配置 否则视图组件会失效
  view: {
    type: 'container',
    style: {
      display: 'inline-block'
    },
    className: 'flowStatusIcon',
    css: `.flowStatusIcon .iconfont{font-size: 14px}
          .flowStatusIcon .icon-chaoshi{color:orange}
          .flowStatusIcon .icon-chenggong{color:#67C23A}
          .flowStatusIcon .icon-jinyong{color:#999797}
          .flowStatusIcon .icon-shibai{color:#F56C6C}`,
    items: [
      {
        type: 'n-i',
        className: 'icon iconfont icon-chenggong',
        formatItem: (row, item) => {
          switch (row?.flowStatus) {
            case 'ABORT':
              item.className = 'icon iconfont icon-shibai'
              break
            case 'END':
              item.className = 'icon iconfont icon-chenggong'
              break
            // 作废
            case 'INVALID':
              item.className = 'icon iconfont icon-jinyong'
              break
            default:
              item.className = 'icon iconfont icon-chaoshi'
              break
          }

          return item
        }
      },
      {
        type: 'text',
        value: '',
        formatItem: (row, item) => {
          // switch (row.flowStatus) {
          //   case 'CANCEL':
          //     item.value = Tech.$t('common.flowStatus')
          //     break
          //   case 'BACK':
          //     item.value = Tech.$t('common.flowReject')
          //     break
          //   case 'DRAFT':
          //     item.value = Tech.$t('common.flowDraft')
          //     break
          //   case 'INVALID':
          //     item.value = Tech.$t('common.flowInvalid')
          //     break
          //   default:
          //     item.value = row.filter_flowStatus
          //     break
          // }
          item.value = row?.flowStatus?.label ?? row?.filter_flowStatus
          return item
        }
      }
    ]
  }
}

// 全部导入组件
export default flowStatusBlock
