import row_permission from './row_permission'
import { generateRuleForm } from './row_permission_condition_tree'
// 租户/用户角色——数据权限
export default function (preName) {
  const data_permission_id = preName + 'data_permission'
  const data_permission_radioGroup_id = preName + 'data_permission_radioGroup'
  const col_permission_table_id = preName + 'col_permission_table'
  const rules_box_id = preName + 'rules_box'
  const row_permission_container_id = preName + 'row_permission_container'
  let loadingInstance = null
  return [
    {
      type: 'container',
      id: data_permission_id,
      style: {
        display: 'flex',
        background: 'white'
      },
      css: `
    .ii-tree .ii-tree-wrap .ii-tree-main{
      overflow-x: hidden;
    }
  `,
      ds_config: {
        list: [
          // 树数据请求
          {
            type: 'meta', // 调用元模型引擎API获取数据
            name: 'treeData', // 数据源标识，获取数据后将根据此名称存入dataSource.data1中
            // autoRequest: true, // 在节点渲染后，是否自动触发请求，默认false
            options: {
              params: {
                // 参考元模型api传参规范
                args: {
                  bind_roleId: '$ds.mainTableRowData.id',
                  filter: [],

                  properties: [
                    'name',
                    'code',
                    'model',
                    'service',
                    'children',
                    'parent',
                    'app',
                    'tag',
                    'ruleTag'
                  ]
                },
                service: 'getDataAuthList',
                model: 'tenant_data_auth'
              }
            },
            reqPrep: () => {
              if (!loadingInstance) {
                loadingInstance = window.ELEMENT.Loading.service({
                  text: Tech.$t('tenant.resultHint')
                })
              }
            },
            reqAfter: (vm, res, config) => {
              if (loadingInstance) {
                loadingInstance.close()
                loadingInstance = null
              }
              return res.data?.map((item) => ({
                id: item.id,
                type: item.type ? item.type : null,
                name: item.name,
                ruleTag: item.ruleTag,
                model: item.model,
                icons: item.ruleTag
                  ? [
                      {
                        icon: 'el-icon-edit',
                        type: 'edit'
                      }
                    ]
                  : null,
                parentId:
                  typeof item.parent === 'object' && item.parent !== null
                    ? item.parent.value
                    : item.parent
              }))
            }
          },
          // 树点击时右边数据请求
          {
            type: 'meta', // 调用元模型引擎API获取数据
            name: 'tableData', // 数据源标识，获取数据后将根据此名称存入dataSource.data1中
            options: {
              params: {
                // 参考元模型api传参规范
                service: 'getAllPropertiesByModel',
                model: 'tenant_data_auth'
              }
            },
            reqAfter: (vm, res, config) => {
              return res?.data
            }
          },
          {
            type: 'meta', // 调用元模型引擎API获取数据
            name: 'permissRules', // 数据源标识，获取数据后将根据此名称存入dataSource.data1中
            // autoRequest: true, // 在节点渲染后，是否自动触发请求，默认false
            options: {
              params: {
                // 参考元模型api传参规范
                service: 'listRowAuthDict',
                model: 'tenant_data_auth'
              }
            },
            reqAfter: (vm, res, config) => {
              return res?.data?.map((item) => ({
                text: item.label,
                value: item.value
              }))
            }
          },
          {
            type: 'meta',
            name: 'save',
            options: {
              params: {
                args: {
                  bind_role: '$ds.mainTableRowData.id'
                },
                app: 'sie-iidp-iam',
                service: 'saveDataAuth',
                context: {
                  uid: '',
                  lang: window.Tech?.LANG?.locale || 'zh_CN'
                },
                model: 'tenant_data_auth',
                tag: 'master'
              }
            },
            reqPrep: () => {
              if (!loadingInstance) {
                loadingInstance = window.ELEMENT.Loading.service({
                  text: Tech.$t('tenant.beSaving')
                })
              }
            },
            reqAfter: (vm, res, config) => {
              if (loadingInstance) {
                loadingInstance.close()
                loadingInstance = null
              }
              return res
            }
          },
          {
            type: 'meta',
            name: 'searchByAuthId',
            options: {
              params: {
                args: {
                  bind_role: '$ds.mainTableRowData.id',
                  authId: ''
                },
                app: 'sie-iidp-iam',
                service: 'echoDataAuth',
                context: {
                  uid: '',
                  lang: window.Tech?.LANG?.locale || 'zh_CN'
                },
                model: 'tenant_data_auth',
                tag: 'master'
              }
            },
            reqPrep: () => {
              if (!loadingInstance) {
                loadingInstance = window.ELEMENT.Loading.service({
                  text: Tech.$t('tenant.resultHint')
                })
              }
            },
            reqAfter: (vm, res, config) => {
              if (loadingInstance) {
                loadingInstance.close()
                loadingInstance = null
              }
              return res?.data
            }
          }
        ]
      },
      dataSource: {
        col: [],
        authId: '',
        colDefaultCheck: [],
        model: '',
        rolOrRow: 1,
        rowAllSelected: false,
        rowAllSelectedOrign: false,
        all: false,
        allOrign: false,
        rulesOrign: [],
        isLoading: false,
        isUserTask: false
      },
      commands: {
        renderDataPermission: (curTableData) => {
          const vm = tech_app.page.getNode(data_permission_id)
          vm.$ds.col = []
          vm.$ds.authId = ''
          vm.$ds.colDefaultCheck = []
          vm.$ds.model = ''
          vm.$ds.rolOrRow = 1
          vm.$ds.rowAllSelected = false
          const rulesBox = vm.$select(rules_box_id)
          if (rulesBox) {
            rulesBox.app.updatePageNode({}, rulesBox, () => {
              rulesBox.data.items = []
            })
          }
          if (vm.$ds.clickType !== 'add') {
            // const dialog = vm.$select('data_permission_dialog')
            const id = curTableData.id
            // 切换时 如果有变化，提醒,没变化，
            if (vm.$ds.authId === id) {
              return
            }
            const render = () => {
              const { ruleTag, model, type } = curTableData
              const dataVm = vm.$select(data_permission_id)
              const tableVm = vm.$select(col_permission_table_id)
              const radioGroupVm = vm.$select(data_permission_radioGroup_id)
              if (type === 'ModelRef') {
                dataVm.$ds.isUserTask = true
                tableVm.data.items.map((item) => {
                  if (item.name === 'visible' || item.name === 'C') {
                    item.visible = false
                  }
                })
                if (tableVm.instance) {
                  setTimeout(() => {
                    let copy = window.Tech._cloneDeep(tableVm.data.items)
                    tableVm.data.items = []
                    copy.map((i) => {
                      tableVm.app.updatePageNode(i, vm, () => {
                        tableVm.data.items.push(i)
                      })
                    })
                  }, 500)
                }
                radioGroupVm.data.model.rolOrRow = 2

                dataVm.$ds.rolOrRow = 2
              } else {
                dataVm.$ds.isUserTask = false
                tableVm.data.items.map((item) => {
                  if (item.name === 'visible' || item.name === 'C') {
                    item.visible = true
                  }
                })
                if (tableVm.instance) {
                  setTimeout(() => {
                    let copy = window.Tech._cloneDeep(tableVm.data.items)
                    tableVm.data.items = []
                    copy.map((i) => {
                      tableVm.app.updatePageNode(i, vm, () => {
                        tableVm.data.items.push(i)
                      })
                    })
                  }, 500)
                }
                radioGroupVm.data.model.rolOrRow = 1
                dataVm.$ds.rolOrRow = 1
              }
              // 树节点有ruleTag才可编辑
              // 如果node 的ruleTag为false，没有行列权
              if (!ruleTag) {
                vm.$ds.authId = ''
                vm.$ds.model = ''
                return
              }
              vm.$ds.authId = id
              vm.$ds.model = model
              const searchPromise = vm.request('searchByAuthId', {
                args: {
                  authId: id
                }
              })
              const tableDataPromise = vm.request('tableData', {
                args: {
                  app: 'sie-iidp-iam',
                  tag: 'master',
                  modelName: model,
                  authId: id
                }
              })
              // 请求行权限，列权限数据
              Promise.all([searchPromise, tableDataPromise])
                .then(([pageData, tableData]) => {
                  vm.$ds.tableData = tableData
                  const rulesBox = vm.$select(rules_box_id)
                  if (!pageData || !pageData.length) {
                    pageData = [
                      {
                        all: false,
                        col: [],
                        row: {
                          all: true
                        }
                      }
                    ]
                  }
                  const row_permission_container = vm.$select(row_permission_container_id)
                  row_permission_container.$ds.all = pageData[0].row.all || false
                  row_permission_container.$ds.allOrign = pageData[0].row.all || false
                  vm.$ds.rowAllSelected = pageData[0].all || false
                  vm.$ds.rowAllSelectedOrign = pageData[0].all || false
                  // 设置规则回显
                  // 规则 行权限
                  const rules = []
                  // 行权限默认值构造
                  Object.keys(pageData[0].row).forEach((key) => {
                    if (key !== 'all') {
                      // 规则权限
                      const rulesType = key.split(',')
                      // 条件树
                      const conditional = pageData[0].row[key]?.map((_) =>
                        typeof _ === 'object'
                          ? { display_name1: _.field, display_name2: _.op, display_name3: _.value }
                          : _
                      )
                      if (conditional) {
                        if (conditional.length === 1) {
                          conditional.unshift('&')
                        }
                        rules.push({ rulesType, conditional })
                      }
                    }
                  })
                  vm.$ds.rulesOrign = rules
                  // 增加dom结构
                  const doms = []
                  for (let i = 0; i < rules.length; i++) {
                    const dom = generateRuleForm(preName)
                    dom.dataSource.selectPermissRules = rules[i].rulesType
                    dom.dataSource.conditional = rules[i].conditional
                    dom.dataSource.conditionalData = rules[i].conditional
                    doms.push(dom)
                  }

                  rulesBox.data.items = []
                  setTimeout(() => {
                    doms.map((item) => {
                      // 行权限节点渲染
                      rulesBox.app.updatePageNode(item, rulesBox, () => {
                        rulesBox.data.items.push(item)
                      })
                    })
                  }, 0)

                  // 列权限数据处理
                  // 增加定时器解决首次渲染表格后顶级勾选不回显的问题
                  setTimeout(() => {
                    vm.$ds.tableData = tableData.map((value, index) => ({
                      ...value,
                      R: pageData[0].col?.find((item) => value.name === item.name)?.R,
                      visible:
                        pageData[0].col?.find((item) => value.name === item.name)?.hidden === false
                          ? true
                          : false,
                      C: pageData[0].col?.find((item) => value.name === item.name)?.C,
                      U: pageData[0].col?.find((item) => value.name === item.name)?.U
                    }))
                  }, 500)
                })
                .catch(() => {
                  vm.$ds.authId = ''
                  vm.$ds.model = ''
                  window.ELEMENT.Message.error(Tech.$t('common.requestEr'))
                })
            }
            render()
            vm.request('permissRules', {})
          }
        }
      },
      created: (vm) => {
        window.Tech.tBus.$once('renderDataPermissionEvent', vm.$cmd.renderDataPermission)
      },
      beforeDestroyated: (vm) => {
        window.Tech.tBus.$off('renderDataPermissionEvent', vm.$cmd.renderDataPermission)
      },
      items: [
        {
          type: 'container',
          // bind_display: '${$ds.authId ? true : false}',
          style: {
            width: '100%',
            position: 'relative'
          },

          items: [
            {
              type: 'container',
              style: {
                padding: '16px',
                borderBottom: '2px dotted #cccccc',
                position: 'sticky',
                top: '0',
                background: '#fff',
                zIndex: 100
              },
              items: [
                {
                  type: 'radio-group',
                  id: data_permission_radioGroup_id,
                  dataSource: {
                    options: [
                      { text: Tech.$t('common.linePermission'), value: 1 },
                      { text: Tech.$t('common.columnPermission'), value: 2 }
                    ],
                    userOptions: [{ text: Tech.$t('common.columnPermission'), value: 2 }]
                  },
                  name: 'rolOrRow',
                  model: {
                    rolOrRow: 1
                  },
                  radioStyle: 'button',
                  bind_options: {
                    path: '$ds.isUserTask',
                    selector: data_permission_id,
                    transform: (params) => {
                      if (params.related.$ds.isUserTask) return params.self.$ds.userOptions
                      else return params.self.$ds.options
                    }
                  },
                  bind_on_changeHandler: (data) => {
                    data.self.$ds.rolOrRow = data.self.data.model.rolOrRow
                  }
                },
                {
                  type: 'checkbox',
                  name: 'all',
                  // bind_disabled: "${$ds.clickType === 'preview'}",
                  style: {
                    marginLeft: '20px',
                    bind_display: "${$ds.rolOrRow === 1?'inline-block' : 'none'}"
                  },
                  model: {
                    bind_all: '$ds.all'
                  },
                  text: Tech.$t('common.allLinePermission'),
                  bind_on_changeHandler: (data) => {
                    data.self.$ds.all = data.value
                  }
                },
                {
                  type: 'checkbox',
                  name: 'rowAllSelected',
                  // bind_disabled: "${$ds.clickType === 'preview'}",
                  style: {
                    marginLeft: '20px',
                    bind_display: "${$ds.rolOrRow === 2?'inline-block' : 'none'}"
                  },
                  model: {
                    bind_rowAllSelected: '$ds.rowAllSelected'
                  },
                  text: Tech.$t('common.allColumnPermission'),
                  bind_on_changeHandler: (data) => {
                    data.self.$ds.rowAllSelected = data.value
                  }
                },
                // 数据权限弹窗 - 保存按钮
                {
                  type: 'button',
                  value: Tech.$t('detailView.save'),
                  options: {
                    size: 'medium',
                    type: 'default'
                  },
                  style: {
                    background: 'var(--button-primary-bg, #677177)',
                    border: 'none',
                    color: '#fff',
                    marginLeft: '90px',
                    float: 'right'
                    // bind_display: "${$ds.clickType === 'preview' ? 'none': 'block'}"
                  },
                  bind_loading: '$ds.isLoading',
                  // 绑定按钮的点击事件
                  bind_on_click: (params) => {
                    const col_permission_table = params.self.$select(col_permission_table_id)
                    // 拿到行数据
                    const row_permission_container = params.self.$select(
                      row_permission_container_id
                    )
                    const vm = params.self.$select(rules_box_id)
                    // 选中全部时，清空规则
                    const rules = !row_permission_container.$ds.all
                      ? vm.data.items.map((item) => ({
                          conditional: item.dataSource.conditional,
                          rulesType: item.dataSource.selectPermissRules
                        }))
                      : []
                    // 验证rulesType唯一
                    const map = {}
                    for (let i = 0; i < rules.length; i++) {
                      const rulesTypeStr = rules[i].rulesType?.join('')
                      if (!rulesTypeStr) {
                        window.ELEMENT.Message.warning(
                          Tech.$t('common.ruleNullHint') +
                            (i + 1) +
                            Tech.$t('common.ruleNullHintAfter')
                        )
                        return
                      } else if (map[rulesTypeStr]) {
                        window.ELEMENT.Message.warning(
                          Tech.$t('common.sameRuleHint') +
                            map[rulesTypeStr] +
                            Tech.$t('common.sameRuleHintMiddle') +
                            (i + 1) +
                            Tech.$t('common.sameRuleHintAfter')
                        )
                        return
                      } else {
                        map[rulesTypeStr] = i + 1
                      }
                    }
                    // 数据构造
                    let errMsg = ''
                    const value = [
                      {
                        authId: params.self.$ds.authId,
                        all: params.self.$ds.rowAllSelected,
                        col: col_permission_table.instance.tableData.map((item) => ({
                          name: item.name,
                          R: item.R,
                          hidden: !item.visible,
                          C: item.C,
                          U: item.U
                        })),
                        row: {
                          all: row_permission_container.$ds.all,
                          ...rules
                            .filter((rule) => rule?.rulesType?.length && rule?.conditional?.length)
                            .reduce((pre, cur, index) => {
                              const arr = cur.conditional.map((item) => {
                                if (typeof item === 'object') {
                                  if (
                                    !errMsg &&
                                    (!item.display_name1 ||
                                      !item.display_name2 ||
                                      !item.display_name3)
                                  ) {
                                    errMsg =
                                      Tech.$t('common.ruleNullHint') +
                                      (index + 1) +
                                      Tech.$t('common.ruleNullHintAfter')
                                  }
                                  return [
                                    item.display_name1,
                                    item.display_name2,
                                    item.display_name3
                                  ]
                                }
                                return item
                              })
                              if (arr.length === 2) {
                                arr.shift()
                              }
                              pre[cur.rulesType.join(',')] = arr
                              return pre
                            }, {})
                        }
                      }
                    ]
                    if (errMsg) {
                      window.ELEMENT.Message.warning(errMsg)
                      return
                    }
                    params.self.$ds.isLoading = true
                    params.self
                      .request('save', {
                        args: {
                          value
                        }
                      })
                      .then((data) => {
                        if (data?.response?.data?.error?.message || data?.error?.message) {
                          window.ELEMENT.Message.warning(
                            data?.response?.data?.error?.message || data?.error?.message
                          )
                        } else {
                          params.self.$ds.allOrign = params.self.$ds.all
                          params.self.$ds.rowAllSelectedOrign = params.self.$ds.rowAllSelected
                          window.ELEMENT.Message.success(Tech.$t('common.saveSuccess'))
                        }
                        params.self.$ds.isLoading = false
                      })
                      .catch(() => {
                        params.self.$ds.isLoading = false
                      })
                  }
                }
              ]
            },
            // 行权限
            {
              type: 'container',
              name: 'rowPermisson',
              style: {
                bind_display: "${$ds.rolOrRow === 1?'block' : 'none'}"
              },
              items: row_permission(preName)
            },
            // 列权限
            {
              type: 'container',
              style: {
                bind_display: "${$ds.rolOrRow === 2?'block' : 'none'}",
                padding: '6px 6px 0 6px',
                height: 'calc(100% - 65px)'
              },
              name: 'columnPermisson',

              items: [
                {
                  type: 'table',
                  style: {
                    height: '100%',
                    bind_display: "${$ds.rowAllSelected ? 'none' : 'block'}"
                  },
                  isEdit: true,
                  id: col_permission_table_id,
                  bind_tableData: '$ds.tableData',
                  items: [
                    {
                      label: Tech.$t('common.visible'),
                      type: 'checkbox',
                      field: 'visible',
                      name: 'visible', // 要写name
                      model: {},
                      width: '70px',
                      formatItem: (row, item) => {
                        item.model = row
                        return item
                      },
                      bind_on_change: (param) => {
                        if (param.value?.isCheck === false) {
                          const row = param.value?.ref?.config?.row
                          if (row) {
                            const col_permission_table = param.self.$select(col_permission_table_id)
                            const rowData = col_permission_table.data.tableData.find(
                              (item) => item.id === row.id
                            )
                            rowData.U = false
                            let instance = col_permission_table.instance
                            if (instance) {
                              // 取消勾选时，其他列的列头全选框无法监听到，需要手动取消全选
                              instance?.$refs?.checkbox_ref_U[0]?.setCheck(false)
                            }
                          }
                        } else {
                          const row = param.value?.ref?.config?.row
                          const col_permission_table = param.self.$select(col_permission_table_id)
                          if (row) {
                            const rowData = col_permission_table.data.tableData.find(
                              (item) => item.id === row.id
                            )
                            rowData.R = true
                          } else {
                            // 勾选可见全选，把可读勾上
                            const tableData = col_permission_table?.data?.tableData ?? []
                            // 可读列全选
                            tableData.forEach((item) => {
                              item.R = param.value?.isCheck
                            })
                            let instance = col_permission_table.instance
                            if (instance) {
                              instance?.$refs?.checkbox_ref_R[0]?.setCheck(true)
                            }
                          }
                        }
                      }
                    },
                    {
                      label: Tech.$t('common.readable'),
                      type: 'checkbox',
                      field: 'R',
                      name: 'R', // 要写name
                      width: '70px',
                      model: {},
                      formatItem: (row, item) => {
                        item.model = row
                        return item
                      },
                      bind_on_change: (param) => {
                        if (param.value?.isCheck === false) {
                          const row = param.value?.ref?.config?.row
                          if (row) {
                            const col_permission_table = param.self.$select(col_permission_table_id)
                            const rowData = col_permission_table.data.tableData.find(
                              (item) => item.id === row.id
                            )
                            rowData.U = false
                            rowData.visible = false

                            let instance = col_permission_table.instance
                            if (instance) {
                              // 取消勾选时，其他列的列头全选框无法监听到，需要手动取消全选
                              instance?.$refs?.checkbox_ref_U[0]?.setCheck(false)
                              instance?.$refs?.checkbox_ref_visible[0]?.setCheck(false)
                            }
                          }
                        }
                      }
                    },
                    {
                      label: Tech.$t('common.canAdd'),
                      type: 'checkbox',
                      field: 'C',
                      name: 'C', // 要写name
                      width: '100px',
                      model: {},
                      formatItem: (row, item) => {
                        item.model = row
                        return item
                      },
                      bind_on_change: (param) => {
                        if (param.value?.isCheck) {
                          const row = param.value?.ref?.config?.row
                          const col_permission_table = param.self.$select(col_permission_table_id)
                          if (row) {
                            const rowData = col_permission_table.data.tableData.find(
                              (item) => item.id === row.id
                            )
                            // 勾选可新增，把可见和可读勾上；
                            rowData.visible = param.value?.isCheck
                            rowData.R = param.value?.isCheck
                          } else {
                            // 勾选可修改全选，把可见和可读勾上
                            const tableData = col_permission_table?.data?.tableData ?? []
                            // 列全选
                            tableData.forEach((item) => {
                              item.R = param.value?.isCheck
                              item.visible = param.value?.isCheck
                            })
                            let instance = col_permission_table.instance
                            if (instance) {
                              // 取消勾选时，其他列的列头全选框无法监听到，需要手动取消全选
                              instance?.$refs?.checkbox_ref_R[0]?.setCheck(true)
                              instance?.$refs?.checkbox_ref_visible[0]?.setCheck(true)
                            }
                          }
                        }
                      }
                    },
                    // 可修改
                    {
                      label: Tech.$t('common.revisability'),
                      type: 'checkbox',
                      field: 'U',
                      name: 'U', // 要写name
                      width: '100px',
                      model: {},
                      formatItem: (row, item) => {
                        item.model = row
                        return item
                      },
                      bind_on_change: (param) => {
                        if (param.value?.isCheck) {
                          const row = param.value?.ref?.config?.row
                          const col_permission_table = param.self.$select(col_permission_table_id)
                          if (row) {
                            const rowData = col_permission_table.data.tableData.find(
                              (item) => item.id === row.id
                            )
                            // 勾选可修改，把可见和可读勾上；
                            rowData.visible = param.value?.isCheck
                            rowData.R = param.value?.isCheck
                            // rowData.C = param.value?.isCheck
                          } else {
                            // 勾选可修改全选，把可见和可读勾上
                            const tableData = col_permission_table?.data?.tableData ?? []
                            // 列全选
                            tableData.forEach((item) => {
                              item.R = param.value?.isCheck
                              item.visible = param.value?.isCheck
                            })
                            let instance = col_permission_table.instance
                            if (instance) {
                              // 列头全选回显
                              instance?.$refs?.checkbox_ref_R[0]?.setCheck(true)
                              instance?.$refs?.checkbox_ref_visible[0]?.setCheck(true)
                            }
                          }
                        }
                      }
                    },
                    { prop: 'displayName', label: Tech.$t('common.attributeName'), type: 'text' }, // type设置为text 代表该列为文本列
                    { prop: 'name', label: Tech.$t('common.attributeValue'), type: 'text' }
                  ]
                }
              ]
            }
          ]
        }
      ]
    }
  ]
}
