import resetPasswordView from '../components/resetPassword'
export default {
  pwd_period_extend_view: {
    selector: {
      // 如果是节点id列表
      attr: 'id', // 属性 key
      pre: ['rbac_user_menu_', 'rbac_user_app_menu_', 'user_', 'user_menu_'],
      value: 'form_main_detail_top_common' // 属性值
    },
    type: 'replace',
    view: {
      created: async (vm) => {
        // 根据用户信息里是否包含pwd_expire_day，才调用获取密码规则接口以及相关交互
        const userInfo = window.tech.userInfo
        if (userInfo && userInfo.hasOwnProperty('pwd_expire_day')) {
          window.Tech.httpMeta({
            data: {
              // 参考元模型后端的传参规范
              params: {
                args: {},
                service: 'getPasswordPolicy',
                model: 'rbac_password_policy',
                app: 'sie-iidp-iam'
              }
            }
          }).then((res) => {
            const dataObj = res.data
            const passwordRule = [
              {
                required: true,
                message: Tech.$t('login.pPlaceholder'),
                trigger: 'blur'
              },
              {
                pattern: dataObj.regex,
                message: dataObj.description,
                trigger: 'blur'
              }
              // {
              //   min: dataObj.min_length,
              //   max: 16,
              //   message: Tech.$t('tenant.passwordLenHint'),
              //   trigger: 'blur'
              // }
            ]
            if (res.data?.expire_day && !vm.$ds.form.pwd_expire_day) {
              vm.$ds.form.pwd_expire_day = res.data.expire_day
            }
            if (vm.$ds.clickType === 'edit') {
              // vm.data.items[0].items[5].rules = []
              vm.data.items[0].items.forEach((item) => {
                if (item.name == 'password') {
                  item.rules = []
                }
              })
            } else {
              // vm.data.items[0].items[5].rules = passwordRule
              vm.data.items[0].items.forEach((item) => {
                if (item.name == 'password') {
                  item.rules = passwordRule
                }
              })
            }
          })
        }
      }
    }
  },
  reset_pwd_extend_view: {
    selector: {
      // 如果是节点id列表
      attr: 'id', // 属性 key
      pre: ['rbac_user_menu_', 'user_'],
      value: 'table_main_table' // 属性值
    },
    type: 'custom',
    beforeOperate: (app, operateItem, options) => {
      // 获取重置按钮属性定义
      // console.log(' **=== options.element.columns == ', options.element.columns);
      let ops = options.element.columns.find((item) => item.prop === 'operate')
      // console.log(' **=== ops == ', ops);
      let resetPwdObj = ops?.btns?.find(
        (item) => item.service === 'resetPassword'
      )
      if (resetPwdObj) {
        resetPwdObj.click = (vm, rowData) => {
          // console.log(' **== in resetPwdObj.click ', vm, rowData);
          // 弹窗节点已存在
          let dialog_meta_rest_pwd = vm.$select(
            vm.$ds.idPre + 'dialog_meta_rest_pwd'
          )
          if (dialog_meta_rest_pwd?.instance) {
            dialog_meta_rest_pwd.$ds.rowData = rowData.row
            dialog_meta_rest_pwd.data.display = true
            return
          }

          let resetPassword = window.Tech._cloneDeep(operateItem.view)
          resetPassword.dataSource.rowData = rowData.row
          resetPassword.display = true

          // 弹窗节点不存在，动态添加重置密码弹窗
          vm.$cmd.meta.popupView(vm, resetPassword, vm.$ds.idPre)
        }
      }

      return operateItem.view
    },
    view: resetPasswordView
  }
}
