// 解析转换tabs
export const formatTabs = async (vm, { view, fields, permissions } = {}) => {
  let cTabs = []
  const tabs = window.Tech._cloneDeep(view?.body?.tabs || [])

  if (!tabs || !Array.isArray(tabs) || tabs.length === 0) {
    return cTabs
  }
  let hasTagArr = []
  // 遍历tabs
  for (let i = 0; i < tabs.length; i++) {
    let item = tabs[i]
    item.name = item.header || item.name || ''
    item.label = item.label || item.header || ''
    if (item.body.authInfo) {
      item.display = item.body.authInfo?.isDisplay
    }
    if (!item.dataSource) {
      item.dataSource = {}
    }
    let addTag = i
    if (item?.body?.field) {
      if (typeof item.body.field === 'object') {
        let unique = item?.body?.field?.attrs?.unique || '' // 唯一标识
        addTag = item.body.field.attrs.relateModel + unique
        item.dataSource._field = item.body.field.attrs.relateModel
      } else {
        addTag = item.body.field
        item.dataSource._field = item.body.field
      }
    }
    if (hasTagArr.indexOf(addTag) > -1) {
      addTag = addTag + '_' + i
    }
    hasTagArr.push(addTag)

    // console.log(' ====== item ==== ', item);
    if (!item.dataSource.idPreTab) {
      item.dataSource.idPreTab = vm.$ds.idPre + 'tab_' + addTag + '_'
    }
    if (!item.dataSource.tabUniqueTag) {
      item.dataSource.tabUniqueTag = addTag
    }
    item.dataSource.tabName = item.name
    //是否使用树的查询条件
    item.dataSource.hasTreeFilter = !!item.hasTreeFilter
    item.dataSource._isAloneSave = item.isAloneSave || false
    item.dataSource._drawerDrag = item.drawerDrag
    item.dataSource._pagin = item.pagin || null
    item.dataSource._toolbar = item.toolbar || null
    item.dataSource._columnsConfigMode = item.columnsConfigMode == false ? false : true
    item.dataSource.tabSearchDisplay = item.tabSearchDisplay || null
    item.dataSource.searchByMainTable = item.searchByMainTable || null
    item.dataSource.isTabNotSave = false
    // 子表显示隐藏关联主表
    item.dataSource.hideRelForm = item.body.hideRelForm
    //子表单独保存不拼接主表数据
    item.dataSource.isErAloneSave = item.isErAloneSave || false
    item.bind_name = '${$ds.tabName + ($ds.isTabNotSave?"*":"")}'
    // delete item.name;

    if (!item.id) {
      item.id = item.dataSource.idPreTab + 'content'
    }

    let modelId = vm.$ds.menuConfig.model || ''

    // 获取前端自定义视图
    // item.view = 'tview__smom-wms__material_package_rule'; // test mock
    // if (item.view) {
    //   await vm.app.utils.getExtendView(vm, item.view, modelId, window?.tech?.apiHost);
    // }

    if (item.custom) {
      if (item.body?.app && item.dataSource) {
        setMetaParamsApp(item.dataSource, item.body.app)
      }
      cTabs.push(item)
    } else {
      // tab渲染表格情况
      if (item.body.type.indexOf('grid') !== -1) {
        if (item.body.type.indexOf('singleGrid') !== -1) {
          let gridItem = await vm.$cmd.meta.formatTabsSingleTable(vm, {
            view: item,
            fields,
            permissions
          })
          gridItem.dataSource._viewType = 'singleGrid'
          gridItem.dataSource.tabViewType = 'singleGrid'
          // 如果tabs视图的body里配置了app就修改数据源里用来继承的app变量_metaParamsApp
          if (item.body?.app && gridItem.dataSource) {
            setMetaParamsApp(gridItem.dataSource, item.body.app)
          }
          cTabs.push(gridItem)
        } else {
          let gridItem = await vm.$cmd.meta.formatTabsTable(vm, {
            view: item,
            fields,
            permissions
          })
          gridItem.dataSource._viewType = 'grid'
          gridItem.dataSource.tabViewType = 'grid'
          // 如果tabs视图的body里配置了app就修改数据源里用来继承的app变量_metaParamsApp
          if (item.body?.app && gridItem.dataSource) {
            setMetaParamsApp(gridItem.dataSource, item.body.app)
          }
          cTabs.push(gridItem)
        }
      } else if (
        (item.body.type === 'formpart' || item.body.type === 'formPart') &&
        item.body.field === undefined
      ) {
        let formPartItem = await vm.$cmd.meta.formatTabsFormPart(vm, {
          view: item,
          fields,
          permissions
        })
        formPartItem.dataSource._viewType = 'formpart'
        formPartItem.dataSource.tabViewType = 'formpart'
        // 如果tabs视图的body里配置了app就修改数据源里用来继承的app变量_metaParamsApp
        if (item.body?.app && formPartItem.dataSource) {
          setMetaParamsApp(formPartItem.dataSource, item.body.app)
        }
        cTabs.push(formPartItem)
      } else {
        item.type = 'container'
        // 详情页支持自定义合并布局
        if (vm?.$cmd?.meta?.addMergeAttrs) {
          vm.$cmd.meta.addMergeAttrs(item, item)
        }
        if (item.body?.app && item.dataSource) {
          setMetaParamsApp(item.dataSource, item.body.app)
        }
        cTabs.push(item)
      }
    }
  }

  // console.log(vm.app.utils._cloneDeep(cTabs), permissions, '--------cTabs')

  // 根据权限点过滤
  cTabs = cTabs.filter((tab) => {
    if (
      permissions?.includes('all') ||
      !tab.tabPermission ||
      (tab.tabPermission && permissions?.includes(tab.tabPermission))
    ) {
      return true
    }
    return false
  })

  // console.log(cTabs, permissions, '--------cTabs')
  return cTabs
}
// 解析转换tabs 非er关系table
export const formatTabsSingleTable = async (vm, { view, fields, permissions } = {}) => {
  let newObj = {}
  let erLoadViewParams = {}
  let newModelId = ''
  let inverseName = ''
  let relApp = ''
  let argType = ''
  let transformRes = null
  let transformInitValue = null
  let remoteDefaultData = null
  let formDefaultValue = null
  let fieldObj = null
  let drawerFormTitle = view?.body?.drawerFormTitle || '' // 右侧弹框标题
  let rowCondition = view?.body?.rowCondition || null
  let tabEditObj = view.body.edit // 编辑表单字段
  let tbar = view?.tbar || []
  if (tbar.length === 0) {
    tbar = view?.body?.tbar || []
  }
  let buttons = view?.body?.buttons || []
  let cardModeConf = view?.body?.cardModeConf || null
  let columnsConfigMode = view?.body?.columnsConfigMode ?? null
  let summaryMethod = view?.body?.summaryMethod || null
  let gridEditMode = view?.body?.gridEditMode || null
  let columns = view?.body?.columns || []
  let tabPermissions = view?.body?.permissions || null
  let showSearchConfig = view?.body?.showSearchConfig
  let mainTableColumns = view?.body?.mainTableColumns || null
  try {
    tabEditObj = view.body.edit // 编辑表单字段

    argType = view?.view || view?.body?.type || 'grid,search,form' // 若有配置view属性优先
    // // 判断若没有form则手动加一个form上去
    if (argType && argType !== 'form' && argType.indexOf(',form') === -1) {
      let endWithForm = false
      try {
        let typeArr = argType.split(',')
        typeArr.map((tItem) => {
          if (tItem.endsWith('_form')) {
            endWithForm = true
          }
        })
      } catch (e) {}
      if (!endWithForm) {
        argType = argType + ',form'
      }
    }
    transformRes = view?.body?.transformRes || null
    transformInitValue = view?.body?.transformInitValue || null
    remoteDefaultData = view?.body?.remoteDefaultData || null
    formDefaultValue = view?.body?.formDefaultValue || null
    // 转函数
    if (transformRes && Object.prototype.toString.call(transformRes) === '[object String]') {
      transformRes = new Function('return ' + transformRes)()
    }
    if (
      transformInitValue &&
      Object.prototype.toString.call(transformInitValue) === '[object String]'
    ) {
      transformInitValue = new Function('return ' + transformInitValue)()
    }
    fieldObj = view.body.field
    if (fieldObj) {
      // console.log(' ==== fieldObj === ', fieldObj);
      newModelId = fieldObj.attrs.relateModel || fieldObj.attrs.RelateModel // rbac_role .name
      inverseName = fieldObj.attrs.inverseName || fieldObj.attrs.InverseName // tab 搜索过滤 关联模块key名
      relApp = fieldObj.relApp // tab 二次relApp 名字

      // 获取_metaParamsApp参数
      let appendAppParams = { app: relApp }
      if (!view.dataSource) {
        view.dataSource = {}
      }
      if (view.dataSource.tabModel) {
        // 新拿的tab model
        view.dataSource.tabModel = newModelId
      }
      // console.log(' === newModelId === ', newModelId);
      erLoadViewParams = {
        args: {
          model: newModelId, // 入参模型
          type: argType, // 获取模型类型 ,form
          ...appendAppParams
        },
        service: 'loadView', // 对应的服务
        model: 'ui_view'
        // app: 'base',
      }
    } else {
      console.log(' err == tabs ' + field + ' not found in fields')
    }
  } catch (e) {
    console.log(' == 处理er关系错误 == ', e)
  }

  let tablePage = vm.$cmd.meta.getView(vm, 'formTabsTable', view.dataSource.idPreTab)

  let containerMain = window.Tech.nestGetItemById(
    tablePage,
    view.dataSource.idPreTab + 'container_main_content'
  )
  let tableMain = window.Tech.nestGetItemById(tablePage, view.dataSource.idPreTab + 'table_main')
  let keyPre = 'form.tabs.' + view.dataSource.tabUniqueTag + '.'
  if (vm.$ds.typeView === 'subTable' && !vm.$ds.isDetail) {
    keyPre = 'grid.tabs.' + view.dataSource.tabUniqueTag + '.'
  }

  tableMain.$improve[keyPre + 'queryViewBefore'] = 'commands.queryViewBefore'
  tableMain.$improve[keyPre + 'queryView'] = 'commands.queryView'
  tableMain.$improve[keyPre + 'queryViewAfter'] = 'commands.queryViewAfter'
  delete tableMain.$improve['queryViewBefore']
  delete tableMain.$improve['queryView']
  delete tableMain.$improve['queryViewAfter']

  containerMain.$improve[keyPre + 'drawerForm.queryView'] = 'commands.queryView'
  containerMain.$improve[keyPre + 'drawerForm.beforeQuery'] = 'commands.beforeQuery'
  containerMain.$improve[keyPre + 'drawerForm.query'] = 'commands.query'
  containerMain.$improve[keyPre + 'drawerForm.afterQuery'] = 'commands.afterQuery'
  containerMain.$improve[keyPre + 'drawerForm.init'] = 'commands.init'
  containerMain.$improve[keyPre + 'drawerForm.validate'] = 'commands.validate'
  containerMain.$improve[keyPre + 'drawerForm.beforeSave'] = 'commands.beforeSave'
  containerMain.$improve[keyPre + 'drawerForm.save'] = 'commands.save'
  containerMain.$improve[keyPre + 'drawerForm.afterSave'] = 'commands.afterSave'
  delete containerMain.$improve['drawerForm.queryView']
  delete containerMain.$improve['drawerForm.beforeQuery']
  delete containerMain.$improve['drawerForm.query']
  delete containerMain.$improve['drawerForm.afterQuery']
  delete containerMain.$improve['drawerForm.init']
  delete containerMain.$improve['drawerForm.validate']
  delete containerMain.$improve['drawerForm.beforeSave']
  delete containerMain.$improve['drawerForm.save']
  delete containerMain.$improve['drawerForm.afterSave']

  tablePage = {
    ...view,
    ...tablePage
  }
  delete tablePage.tbar
  delete tablePage.body
  if (!tablePage.dataSource) {
    tablePage.dataSource = {}
  }
  if (!tablePage.dataSource.idPreTab) {
    tablePage.dataSource.idPreTab = view.dataSource.idPreTab
  }
  if (!tablePage.dataSource.tabUniqueTag) {
    tablePage.dataSource.tabUniqueTag = view?.dataSource?.tabUniqueTag
  }
  if (!tablePage.dataSource.tabConfig) {
    tablePage.dataSource.tabConfig = {}
  }

  Object.assign(tablePage.dataSource.tabConfig, view?.body)

  tablePage.dataSource.tabConfig.model = newModelId
  tablePage.dataSource.tabConfig.inverseName = inverseName
  tablePage.dataSource.tabConfig.refApp = relApp
  tablePage.dataSource.tabConfig.argType = argType
  tablePage.dataSource.tabConfig.transformRes = transformRes // TODO 需要处理提交转换逻辑
  tablePage.dataSource.tabConfig.transformInitValue = transformInitValue
  tablePage.dataSource.tabConfig.remoteDefaultData = remoteDefaultData
  tablePage.dataSource.tabConfig.formDefaultValue = formDefaultValue
  tablePage.dataSource.tabConfig.fieldObj = fieldObj
  tablePage.dataSource.tabConfig.drawerFormTitle = drawerFormTitle
  tablePage.dataSource.tabConfig.rowCondition = rowCondition // TODO 需要处理行条件逻辑
  tablePage.dataSource.tabConfig.tabEditObj = tabEditObj
  tablePage.dataSource.tabConfig.tbar = tbar
  tablePage.dataSource.tabConfig.tbarSrc = encodeURIComponent(JSON.stringify(tbar || []))
  tablePage.dataSource.tabConfig.buttons = buttons
  tablePage.dataSource.tabConfig.cardModeConf = cardModeConf
  tablePage.dataSource.tabConfig.columnsConfigMode = columnsConfigMode
  tablePage.dataSource.tabConfig.summaryMethod = summaryMethod
  tablePage.dataSource.tabConfig.gridEditMode = gridEditMode
  tablePage.dataSource.tabConfig.columns = columns
  tablePage.dataSource.tabConfig.permissions = tabPermissions
  // tablePage.dataSource.tabConfig.view = view;
  tablePage.dataSource.tabConfig.checkbox = view.body.checkbox
  tablePage.dataSource.tabConfig.mainFields = fields
  tablePage.dataSource.tabConfig.mainPromissions = permissions
  tablePage.dataSource.tabConfig.showSearchConfig = showSearchConfig // 是否显示搜索右侧的配置图标
  tablePage.dataSource.tabConfig.mainTableColumns = mainTableColumns
  tablePage.dataSource._no_bind_tabConfig = true
  if (!tablePage.commands) {
    tablePage.commands = {}
  }
  tablePage.commands.getTabLoadViewParams = () => {
    return erLoadViewParams
  }
  tablePage.commands.loadViewAfter = (vm, res) => {
    //     console.log(' ==== loadViewAfter res = ', res);
    let paramApp = 'base'
    if (res?.data?.app) {
      paramApp = res.data.app
    }
    let paramModel = ''
    if (res?.data?.model) {
      paramModel = res.data.model
    }

    // newObj.fields = res.data.fields;
    // newObj.view = res.data.views.grid;

    try {
      // 替换columns tbar buttons

      if (res?.data?.views?.grid?.body) {
        res.data.views.grid.body.columns = vm.$ds.tabConfig.columns
        res.data.views.grid.body.tbar = vm.$ds.tabConfig.tbar
        res.data.views.grid.body.buttons = vm.$ds.tabConfig.buttons
        if (res.data.views.grid.body?.cardModeConf !== undefined) {
          res.data.views.grid.body.cardModeConf = vm.$ds.tabConfig.cardModeConf
        }
        if (vm.$ds.tabConfig.tabPermissions) {
          res.data.permissions = vm.$ds.tabConfig.tabPermissions
        }
      }
      if (res?.data?.fields) {
        vm.$ds.tabConfig.erFields = res.data.fields
      }
    } catch (e) {
      console.log(' === tab grid replace columns err == ', e)
    }

    // newObj.search = res.data.views.search;
    // console.log(' === newObj === ', newObj);

    vm.$ds.tabConfig.paramApp = paramApp
    vm.$ds.tabConfig.paramModel = paramModel
    // console.log(' ==== res 22 == ', res);
    return res
  }
  if (vm?.$cmd?.meta?.addMergeAttrs) {
    vm.$cmd.meta.addMergeAttrs(tablePage, view)
  }
  return tablePage
}
