export const handlerBizDetailPage = (nodeId, options = {}) => {
  let curNodeId = nodeId
  let handlers = {
    dataHandler: {
      get: (target, property, receiver) => {
        let curNode = tech_app.page.getNode(curNodeId)
        if (curNode) {
          let pre = curNode.$ds.idPreTab || curNode.$ds.idPre
          let tableMainVm = curNode.$select(pre + 'table_main')
          if (property === 'title') {
            let topHeader = curNode.$select(pre + 'form_main_detail_top_header')
            return topHeader?.$ds?.pageTitle
          } else if (property === 'model') {
            return tableMainVm?.$ds?._metaParamsModel
          } else if (property === 'app') {
            return tableMainVm?.$ds?._metaParamsApp
          }
        }
      }
    },
    reqHandler: {},
    baseMethodsHandler: {
      get: (target, property, receiver) => {
        let val = null
        let curNode = tech_app.page.getNode(curNodeId)
        if (curNode) {
          let pre = curNode.$ds.idPreTab || curNode.$ds.idPre
          let tableMainVm = curNode.$select(pre + 'table_detail')
          if (['created', 'mounted', 'destroy'].includes(property)) {
            let __srcHookFn = { ...tableMainVm?.data?.__srcHookFn }
            val = __srcHookFn?.[property]
          }
        }
        return val
      }
    },
    methodsHandler: {
      get: (target, property, receiver) => {
        let val = null
        let curNode = tech_app.page.getNode(curNodeId)
        if (curNode) {
          let pre = curNode.$ds.idPreTab || curNode.$ds.idPre
          let tableMainVm = curNode.$select(pre + 'table_detail')
          if (['created', 'mounted', 'destroy'].includes(property)) {
            val = tableMainVm?.data?.[property]
          } else if (property === 'runback') {
            return function () {
              let topHeader = curNode.$select(pre + 'form_main_detail_top_header')
              topHeader?.$cmd?.preBack({ self: topHeader })
            }
          }
        }
        return val
      }
    },
    nodesHandler: {
      get: (target, property, receiver) => {
        let curNode = tech_app.page.getNode(curNodeId)
        if (curNode) {
          let pre = curNode.$ds.idPreTab || curNode.$ds.idPre
          if (property === 'self') {
            return curNode.$select(pre + 'table_detail')
          } else if (property === 'backNode') {
            return curNode.$select(pre + 'form_main_detail_top_back')
          }
        }
      }
    }
  }
  return handlers
}
