export default {
  // 设置查询条件行数
  type: 'dialog',
  id: 'meta_query_search_setting',
  width: '300px',
  title: Tech.$t('seniorTable.setTingconditionRowNum'),
  display: false,
  confirmText: Tech.$t('toolbar.dialogConfirm'),
  cancelText: Tech.$t('toolbar.dialogCancle'),
  commands: {},
  bind_on_opreates: async (params) => {
    const { self: vm, value } = params
    if (value.type === 'cancel') {
      value.close()
    } else {
      const idPre = vm.$cmd.fromTab(vm) ? vm.$ds.idPreTab : vm.$ds.idPre
      const tableMain = vm.$select(idPre + 'table_main_wrap')
      const { fields, views } = tableMain.$ds.tableView.data
      let searchView = { ...views?.search }
      const dialogForm = await vm
        .$select(idPre + 'meta_query_search_setting_form')
        .instance.submit()
      if (tableMain.$ds.seniorTable.search?.body) {
        searchView = window.tech_app.utils.deepMerge(searchView, tableMain.$ds.seniorTable.search) // 深度合并 tableMain.$ds.seniorTable.search的优先级最高
      }
      tableMain.$ds.seniorTable.search = searchView
      searchView.body.row = dialogForm.row
      // 设置行数后，需要更新数据
      sessionStorage.setItem(vm.$ds.idPre + 'SEARCH_CONFIG', JSON.stringify(searchView))

      const commonForm = vm.$select(idPre + 'form_main_table_search_common')
      const dropdownForm = vm.$select(idPre + 'form_main_table_search_dropdown')
      const search_form_data = {
        // 缓存现有搜索的数据
        tableFilter: commonForm.$ds.tableFilter,
        tableFilterTags: commonForm.$ds.tableFilterTags,
        formData: { ...commonForm.$ds.form, ...dropdownForm?.$ds.form }
      }
      sessionStorage.setItem(idPre + 'SEARCH_FORM_DATA', JSON.stringify(search_form_data))
      tableMain.$ds.resing = false // 把resing重置成false

      tableMain.$cmd.initTableSearch(tableMain, searchView)
      value.close()
    }
  },
  items: [
    {
      type: 'form',
      id: 'meta_query_search_setting_form',
      formConfig: {
        inline: false,
        labelPosition: 'left',
        labelWidth: '130px'
      },
      dataSource: {
        form: { row: 1 }
      },
      items: [
        {
          type: 'number',
          rules: [
            {
              required: true,
              trigger: 'blur',
              message: Tech.$t('seniorTable.enterTheCollapsibleRows')
            }
          ],
          text: Tech.$t('seniorTable.numberConditionRows'),
          id: 'meta_query_search_setting_form_item',
          name: 'row',
          maxValue: 10,
          minValue: 1
        }
      ]
    }
  ]
}
