import resetPasswordView from '../components/resetPassword'
export default {
  // 租户用户状态不能设置为锁定
  multi_tenant_root_user_menu_status: {
    type: 'custom',
    selector: {
      attr: 'id',
      value: 'user_menu_form_main_detail_top_common_items_0_items_status'
    },
    beforeOperate: (vm, operateItem, options) => {
      options.element.options = options.element.options.map((option) => {
        if (option.value === '1') {
          return { ...option, disabled: true }
        } else {
          return { ...option }
        }
      })
    }
  },
  // 租户管理、租户用户 'name'字段增加字节限制
  multi_tenant_user_menu_name_lenghth_limit: {
    type: 'custom',
    selector: {
      attr: 'id',
      pre: ['user_menu_', 'tenant_management_menu_'],
      value: 'form_main_detail_top_common_items_0_items_name'
    },
    beforeOperate: (vm, operateItem, options) => {
      let instance = options.element
      instance.rules = [
        {
          required: true,
          validator: (rule, el) => {
            const value = rule.value
            if (!value) {
              rule.callback(
                new Error(Tech.$t('customPermission.nameValidateNotNull'))
              )
            } else {
              const getByteLength = (str) => {
                let len = 0
                for (let i = 0; i < str.length; i++) {
                  const code = str.charCodeAt(i)
                  if (code <= 127) {
                    len += 1
                  } else {
                    len += 2 // 中文字符占两个字节
                  }
                }
                return len
              }
              const byteLength = getByteLength(value)
              const maxByteLength = 60
              if (byteLength > maxByteLength) {
                rule.callback(
                  new Error(Tech.$t('customPermission.nameValidateLen'))
                )
              } else {
                rule.callback()
              }
            }
          }
        }
      ]
      return operateItem.view
    }
  },
  user_menu__grid_reset_pwd_extend_view: {
    selector: {
      // 如果是节点id列表
      attr: 'id', // 属性 key
      pre: ['user_menu_'],
      value: 'table_main_table' // 属性值 // 动态drawForm打开的例子 id text_test_open_input
    },
    type: 'custom',
    beforeOperate: (app, operateItem, options) => {
      // 获取重置按钮属性定义
      // console.log(' **=== options.element.columns == ', options.element.columns)
      let ops = options.element.columns.find((item) => item.prop === 'operate')
      // console.log(' **=== ops == ', ops);
      let resetPwdObj = ops?.btns?.find(
        (item) => item.service === 'resetPassword'
      )
      if (resetPwdObj) {
        resetPwdObj.click = (vm, rowData) => {
          // console.log(' **== in resetPwdObj.click ', vm, rowData);
          // 弹窗节点已存在
          let dialog_meta_rest_pwd = vm.$select(
            vm.$ds.idPre + 'dialog_meta_rest_pwd'
          )
          if (dialog_meta_rest_pwd?.instance) {
            dialog_meta_rest_pwd.$ds.rowData = rowData.row
            dialog_meta_rest_pwd.data.display = true
            return
          }

          let resetPassword = window.Tech._cloneDeep(operateItem.view)
          resetPassword.dataSource.rowData = rowData.row
          resetPassword.display = true

          // 弹窗节点不存在，动态添加重置密码弹窗
          vm.$cmd.meta.popupView(vm, resetPassword, vm.$ds.idPre)
        }
      }
      return operateItem.view
    },
    view: resetPasswordView
  },
  user_menu_tree_main_wrap_extend_view: {
    selector: {
      // 如果是节点id列表
      attr: 'id', // 属性 key
      value: 'user_menu_tree_main_wrap' // 属性值 // 动态drawForm打开的例子 id text_test_open_input
    },
    type: 'custom',
    beforeOperate: (app, operateItem, options) => {
      const treeDataConfig = options.element.ds_config.list.find(
        (item) => item.name === 'treeData'
      )
      if (treeDataConfig) {
        treeDataConfig.reqPrep = (vm, options, config) => {
          options.params.args.filter?.push(['tenantType', '=', 'TENANT'])
          return options
        }
      }
    },
    view: {}
  }
}
