import toLowerCase from '../../common/utils/toLowerCase'

import MetaColumn from './metaColumn'

const searchFlgDataTypes = new Set([
  'auto',
  'boolean',
  'integer',
  'string',
  'text',
  'long',
  'float',
  'double',
  'date',
  'datetime',
  'bigdecimal',
  'enummodel'
]) // 可以查找的类型

export default class MetaContext {
  constructor(modelMeta) {
    if (!modelMeta.view || !modelMeta.view) {
      console.error('不存在此表单数据')
      return
    }
    this.modelMeta = modelMeta.view // 后台获取的模型数据
    this.meta = modelMeta
    if (!this.modelMeta.body) {
      return
    }
    if (Array.isArray(this.modelMeta.body.columns)) {
      this._columns = this.modelMeta.body.columns
        .filter((e) => this.meta?.fields?.[e.name || e] || e.dataType === 'condition')
        .map((c) => {
          return this.getFormItem(c)
        })
    }
  }
  /** 前端视图 */
  get customView() {
    if (this.modelMeta?.body?.customView) {
      // 字符串function转js function
      if (!this.modelMeta.body.customView?.[0]?.__isStrFuncChange) {
        // 在第一个元素添加是否初次转换过的标识
        this.modelMeta.body.customView = this.dealCustomViewStrFunc(this.modelMeta.body.customView)
        if (this.modelMeta.body.customView?.[0] !== undefined) {
          this.modelMeta.body.customView[0].__isStrFuncChange = true
        }
      }
      // console.log(' === this.modelMeta.body.customView == ', this.modelMeta.body.customView);
      return this.modelMeta.body.customView
    } else {
      return null
    }
  }

  get customFormPageTitle() {
    return this.modelMeta.body.customFormPageTitle
  }

  get childModels() {
    return this.modelMeta.childModels
  }

  get selectAction() {
    return this.getAction('search')
  }

  get deleteAction() {
    return this.getAction('delete')
  }

  get updateAction() {
    return this.getAction('update')
  }

  get insertAction() {
    return this.getAction('create')
  }

  /**
   * ER关系数据
   */
  get er() {
    return this.modelMeta.er
  }

  get columnsList() {
    return this._columns
  }

  get columnGroups() {
    return this.modelMeta.columnGroups
  }

  /** 模型ID */
  get modelId() {
    return this.modelMeta.body.model
  }

  get displayName() {
    return this.modelMeta.displayName
  }

  get action() {
    return this.modelMeta.action
  }

  get tabsFields() {
    // 获取form里面tabs对应的field列表
    let re = []
    try {
      re = this.modelMeta.body.tabs.map((c) => c.body.field)
    } catch (e) {
      // tabsFields e
    }
    return re
  }

  // 处理前端视图 customView 的js 字符串方法 转js方法
  dealCustomViewStrFunc(view) {
    if (Object.prototype.toString.call(view) === '[object Array]') {
      for (let i = 0; i < view.length; i++) {
        view[i] = this.dealCustomViewStrFunc(view[i])
      }
    } else if (Object.prototype.toString.call(view) === '[object Object]') {
      // test mock 测试写死的方法
      // if (view.name === 'thing_model_id') {
      //   view = {
      //     // ...
      //   };
      // }
      // console.log(' **** view *** ', view);

      // eslint-disable-next-line @typescript-eslint/prefer-for-of
      Object.keys(view).map((key) => {
        // eslint-disable-next-line @typescript-eslint/prefer-optional-chain
        if (view && view[key]) {
          if (
            window?.Tech?.isFunctionStringNew?.(view[key]) ||
            window?.Tech?.isArrayOrObjectString?.(view[key])
          ) {
            try {
              let fn = new Function('return ' + view[key]).bind(window)
              view[key] = fn()
            } catch (e) {
              console.log(' === change str function error == ', e)
            }
          }
        }
      })
      // eslint-disable-next-line @typescript-eslint/prefer-optional-chain
      // if (view && view.items) {
      //   view.items = this.dealCustomViewStrFunc(view.items);
      // }
      Object.keys(view).map((k) => {
        if (
          Object.prototype.toString.call(view[k]) === '[object Array]' ||
          Object.prototype.toString.call(view[k]) === '[object Object]'
        ) {
          view[k] = this.dealCustomViewStrFunc(view[k])
        }
      })
    }
    return view
  }

  // 获取表单项接口获取到的配置
  getFormItem(c) {
    let cData = {
      name: c,
      dataType: 'String'
    }
    if (typeof c === 'string') {
      cData = this.meta.fields[c]
    } else if (c.name) {
      if (c.custom) {
        cData = { ...(this.meta.fields[c.name] || {}), ...c }
        // 兼容以前的hidden写法
        if (cData.hasOwnProperty('hidden')) {
          cData.display = cData.hidden
        }
      } else {
        cData = { ...c, ...(this.meta.fields[c.name] || {}) }
      }
    }

    return new MetaColumn(cData)
  }

  getManyToOne() {
    const items = this.getSortedColumnsList()
    // console.log(items, '-----------getManyToOne');
    if (Array.isArray(items)) {
      return items.filter((item) => toLowerCase(item.datatype) === 'manytoone')
    }
  }

  /**
   * 查询n是否是ManyToOne中的某一项的名称
   * @param {String} n name
   * @returns boolean
   */
  isManyToOneName(n) {
    const manyToOneItems = this.getManyToOne()
    return manyToOneItems?.some((item) => item.name === n)
  }

  /** 主键 */
  get pk() {
    return this.getSortedColumnsList().filter((c) => c.uniquekey === true)
  }

  getPkData(row) {
    return this.pk.reduce((a, b) => {
      a[b.name] = row[b.name]
      return a
    }, {})
  }

  getSortedColumnsList() {
    if (!this.columnsList) {
      return []
    }
    return this.columnsList.sort((a, b) => this.sort(a, b))
  }

  getAllSearchColumns() {
    const sortedColumnsList = this.getSortedColumnsList().filter(
      (c) => ['Local', 'Relative'].includes(c.searchFlg) && searchFlgDataTypes.has(c.datatype)
    )
    // console.log(sortedColumnsList, this.er);
    if (Array.isArray(this.er)) {
      for (const erItem of this.er) {
        if (Array.isArray(erItem.columnsList)) {
          erItem.columnsList.forEach((c) => {
            const metaColumn = new MetaColumn(c, erItem)
            if (
              ['Local', 'Relative'].includes(metaColumn.searchFlg) &&
              searchFlgDataTypes.has(metaColumn.datatype)
            ) {
              sortedColumnsList.push(metaColumn)
            }
          })
        }
      }
    }
    return sortedColumnsList
  }

  /**
   * 列排序算法
   * @param {*} a
   * @param {*} b
   * @returns
   */
  sort(a, b) {
    const aGroup = this.getColumnGroup(a.id)
    const bGroup = this.getColumnGroup(b.id)

    // 有父组则按照父组比较
    if (aGroup != null && bGroup != null) {
      return (aGroup.index || 0) - (bGroup.index || 0)
    } else if (aGroup != null) {
      return (aGroup.index || 0) - (b.index || 0)
    } else if (bGroup != null) {
      return (a.index || 0) - (bGroup.index || 0)
    } else {
      return (a.index || 0) - (b.index || 0)
    }
  }

  getDataTypeByColumnName(name) {
    const column = this.columnsList.find((c) => c.name === name)
    return column && toLowerCase(column.datatype)
  }

  /**
   * 获得传入行的主键字符串
   * @param {*} row 传入的一行数据
   * @returns 字符串形式的主键
   */
  getRowPkId(row) {
    const pks = this.pk
    if (pks.length === 0) return null
    let pkStr = ''
    for (const pk of pks) {
      const v = row[pk.name]
      if (v !== undefined && v !== null) {
        pkStr += v
      }
    }
    return pkStr
  }

  // eslint-disable-next-line @typescript-eslint/member-ordering
  static async groupBy(items, groupLength, cb) {
    const result = []
    for (let i = 0; i < items.length; i += groupLength) {
      const segment = []
      for (let j = i; j < items.length && j < i + groupLength; j++) {
        const tt = await cb(items[j])
        segment.push(tt)
      }
      result.push(segment)
    }
    return result
  }

  /**
   * 获得指定列的直接父属性组
   * @param {*} columnId
   */
  getColumnGroup(columnId) {
    if (this.modelMeta.columnGroups) {
      for (const columnGroup of this.modelMeta.columnGroups) {
        if (columnGroup.columnIds.includes(columnId)) {
          return columnGroup
        }
      }
    }
  }

  /**
   * 获得全名称 组名-列名
   * @param {*} columnId
   */
  getColumnFullName(column) {
    if (column.erItem) {
      return `${column.erItem.name}-${column.displayName || column.name}`
    }
    const group = this.getColumnGroup(column.id)
    return group
      ? `${group.name}-${column.displayName || column.name}`
      : column.displayName || column.name
  }

  getAction(actionType) {
    const actionItem = this.action.find((a) => a.type.toLowerCase() === actionType.toLowerCase())
    return actionItem
  }

  getActionId(actionType) {
    const actionItem = this.getAction(actionType)
    return actionItem?.id
  }

  /* 获得一个新的由默认值组成的对象 */
  getDefaultValueObject() {
    return this.columnsList.reduce((obj, column) => {
      if (column.defaultValue !== null && column.defaultValue !== undefined) {
        obj[column.name] = column.defaultValue
      }
      return obj
    }, {})
  }
}
