      bind_cardModeConf: '$ds.cardModeConf',
      checkbox: false, //单选：'single'，多选：'multiple', 'multiple_2'
      checkboxWidth: '55px',
      showEmpty: true, //是否显示‘空数据’提示文案
      bind_pagingIndexStart: '$ds.paging.pageStart', //数据的序号
      columns: [],
      itemsOrigin: [], // 备份
      items: [],
      rules: {},
      summaryMethod: null, // 行末方法
      mergeMethod: null,
