            vm.$cmd.meta.tableFormat.setEditChange(popSelectTable.items[0].items[1].items[2], views)
            popSelectTable.items[0].items[1].items[2].columns = columns

            let keyPre = 'form.tabs.' + vm.$ds.tabUniqueTag + '.'
