            addRelVm.$improve[keyPre + 'addRel.beforeQuery'] = 'commands.beforeQuery'
            addRelVm.$improve[keyPre + 'addRel.query'] = 'commands.query'
            addRelVm.$improve[keyPre + 'addRel.afterQuery'] = 'commands.afterQuery'
            addRelVm.$improve[keyPre + 'addRel.queryCount'] = 'commands.queryCount'
            addRelVm.$improve[keyPre + 'addRel.save'] = 'commands.save'
            delete addRelVm.$improve['addRel.created']
            delete addRelVm.$improve['addRel.mounted']
            delete addRelVm.$improve['addRel.destroy']
            delete addRelVm.$improve['addRel.queryView']
            delete addRelVm.$improve['addRel.beforeQuery']
            delete addRelVm.$improve['addRel.query']
            delete addRelVm.$improve['addRel.afterQuery']
            delete addRelVm.$improve['addRel.queryCount']
            delete addRelVm.$improve['addRel.save']

            popSelectTable.className = 'dialog_pop_select_table_className'
